/* 平成16年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h16.committeeSessions.push(...[{"id":"h16-20040413-8","meetingId":"h16-cm04","date":"2004年4月13日","dateIso":"2004-04-13","committee":"建設委員会","time":"午後１時０４分～午後４時０３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件整理しています。","topics":[{"id":"topic-01","title":"平成１５年請願第９号「（仮称）大井３丁目マンション新築工事」および「（仮称）大井３丁目計画に伴う解体工事」に関する請願","agenda":"平成１５年請願第９号「（仮称）大井３丁目マンション新築工事」および「（仮称）大井３丁目計画に伴う解体工事」に関する請願","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"１年ですか、今高いところですと１３階まで建ち上がったということですけれども、ちょっと説明を求めました。","respondent":"浜脇住環境整備課長","answer":"それですから、約６０％ぐらいの部分ができ上がったみたいな形になるんでしょうか。電波障害についてはやっていくというふうに言っておりますので、その辺は現場のほうで処理しているものと、こういうふうに思っております。","id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"６０％からの工事が終わってきているということで、今の電波障害のことだけ。電波障害が実際にもう起きてきていて、ぜひ区のほうでとらえて指導していくような方向を考えておいていただければなというふうに思いますとの意見を述べました。","respondent":"浜脇住環境整備課長","answer":"厳重に対応するように、私におきましてもやるように、この業者を指導してまいります。","id":"exchange-002"},{"speaker":"原委員","kind":"意見","question":"ある程度の誠意は持っての話し合いに臨んでいるのかなという部分と、これから、ここで３回継続をして４回目になるということもありますね。会派としても採決をしたいなというふうに思いますけれども、取り扱いも含めてお願いできればと考えておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、趣旨からしますと、建築主側の回答、対応ですか、その辺としては、課長のほうからどのような印象を持たれていますか。そういう十分対応しているような業者側の状況か尋ねました。","respondent":"浜脇住環境整備課長","answer":"地下１階があるんですけれども、もうその辺のことは、私どもはちょっと判断するにはきついかなと思います。やはり、住民から見れば階数の問題と地下室の問題というのは、ずっと持っているんだろう、こういうふうに思われます。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"聞くところによりますと、民事裁判ですか、それを起こしたというようなお話も聞きますけれども、その辺は何かつかんでおりますか。それはないか尋ねました。","respondent":"浜脇住環境整備課長","answer":"私は裁判の話はつかんでおりませんが、東京都の建築審査会のほうに審査請求をされた。その後、業者のほうからもそういう情報はもらっておりませんので、今のところはないと思います。","id":"exchange-005"},{"speaker":"藤田委員","kind":"意見","question":"過去３回審査してきました。したがいまして、私どもとしましては、願意に添いがたいという結論を出していきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問・要望","question":"いろいろな形で近隣住民の方のほうから、まだ工事協定がはっきり結ばれていない状況下にあるということですから、ぜひ業者との橋渡しも含めて。結論を出してと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"私もこれだけ長期間、業者の方も誠意を尽くされたと思いますので、あとは今菊地委員もおっしゃったとおり、今後の対応をまた十分業者が地域の人々にやってくれることを望みまして、今回採決したほうがいいんじゃないかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"６月からということで、ほんとうにそちらのほうも誠意をもって対応していただきたいということをお願いして、結論を出してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"本多委員","kind":"意見","question":"請願項目１６項目ありまして、建設委員会に付託をされたこれまでの審議で当然結論を出すべきだったんですが、審査請求、司法の場ですとか、そういった様子を我々委員会で見てきましたので、そういった状況も踏まえて、今日結論を出すべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"}]},{"id":"topic-02","title":"の聴取をいたします。 (1) のねむの木の庭の工事の延伸","agenda":"の聴取をいたします。 (1) のねむの木の庭の工事の延伸","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"１カ月かかって、まして教育委員会がやっているということですから、一部を出す場合の公園もありますよね。何かそういったものがあるのか、ただ記録だけで残すのか、その辺だけちょっと教えていただきたいんですが。","respondent":"岩田管理工事課長","answer":"ただ、もし着手してもいいという結論が出た場合でも、基本的に壊す必要のないところについては、埋め戻して保存をする予定です。どうしても一部壊さざるを得ない部分のみ手をつけて、あとは埋め戻して保存をする、こういう考え方です。","id":"exchange-011"},{"speaker":"原委員","kind":"質問","question":"埋蔵文化財が出てきたということで、予備調査をかけるわけですけれども、これは費用はどういう形で、保存するなり、あるいは埋め戻すなりを含めて。それから委員とかいろんな方がいらっしゃる、その辺のところはどうなっているか、ちょっと教えていただけますか。","respondent":"岩田管理工事課長","answer":"今回のここのケースの場合は、教育委員会そのものも私どもも同じ区ですので、区の費用で行います。今回の場合は品川歴史館の館長を団長にお願いをしまして、組織をつくって今、調査をしていただいております。","id":"exchange-012"},{"speaker":"原委員","kind":"意見","question":"この前報告ございましたけれども、その形状はどういう形に。その辺を、もしわかる部分があれば、このたび調査してみないとわからないよというふうな部分があるんでしょうがお願いしますとの意見を述べました。","respondent":"岩田管理工事課長","answer":"ここの場合は５cmとか、２５cmで出てきておりますので、相当破壊されているだろう。ただ、大幅に変えるということは、ちょっと難しいです。","id":"exchange-013"}]},{"id":"topic-03","title":"の八ツ山アンダーパスの一部供用開始","agenda":"の八ツ山アンダーパスの一部供用開始","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"実際に開発地域に通勤をされるような方も皆さん含めて、どれぐらいの方がいらっしゃるのか、ちょっと教えていただけますか。あまり人が歩道でも通行しているような地域じゃなくて、ちょっとその辺ありましたら、教えてほしいと求めました。","respondent":"岩田管理工事課長","answer":"たしかあれは２００から２５０ルクス程度に上げました。住宅街で１ルクスから５ルクスという値ですから、やはりトンネル状のところというのは、まず明るくするというのが大事だということで考えております。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、今、課長が言われたような対策をとっていくのは開発業者の側だということなんですか。そういう問題がこれから起きてきたときに、じゃあどこがどういうふうに対処するのかというのをちょっと教えてほしいと求めました。","respondent":"岩田管理工事課長","answer":"今回ご説明しております部分については、今後、問題が起きれば品川区が対応をするということになります。これから４月１日に供用を開始したばかりですし、不都合があれば、きちっと対応してまいりたいと思います。","id":"exchange-015"},{"speaker":"山村委員","kind":"質問","question":"大体のことがもう終わっていると思うんですが、落書き等が起こりそうな感じがするなと思っているんですが、落書き対策というのは考えていらっしゃるのか、何かありますか尋ねました。","respondent":"岩田管理工事課長","answer":"逆に見てほしいような、おそらくやるとしたら車道で人から見えるような、そういうカンバスとして都合のよいところをねらってくると思うんですね。ここの場合は、おそらくそういう場所じゃないので、一応そういう落ちやすいような塗料で壁面を今のところ塗装をしております。","id":"exchange-016"},{"speaker":"山村委員","kind":"質問","question":"そうすると、何か区のほうから絵を描いていくとか、そういう対策は別に考えて、白いままということでよろしいのか尋ねました。","respondent":"岩田管理工事課長","answer":"過去にいろいろ私どもでも絵を描いてまいりました。そういう地元の方の運動と合わせながら、必要であれば、区のほうで考えてまいりたいと思います。","id":"exchange-017"},{"speaker":"山村委員","kind":"質問・要望","question":"浮世絵の絵を描けだとか、そういうような要望が地域のほうからあるやもしれませんので、そのような要望があった場合には、できるだけそのように応対していただければと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"}]},{"id":"topic-04","title":"の羽田空港再拡張後の飛行ルート","agenda":"の羽田空港再拡張後の飛行ルート","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"そして幾ら高度を高めたとしましても、必ず羽田空港を中心に離着陸するわけですから、今後十分な主張を図ってほしいと求めました。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"質問ということなんですけれども、こういう計画があるとか、そういったことの区民への周知の方法をどう考えているのかということ。今、それがどのようになって、いつその結果が戻ってきてというところでの大まかなスケジュールはどうなっているのかを説明を求めました。","respondent":"藤田都市計画課長","answer":"今回、国土交通省のほうからは、大きな行程といたしましては、２００９年に供用開始をするんだというのが一つの大きな形です。そうした中で、国の考え方というのがある程度見えてきた段階で、区民への周知というような形も考えていくべきかなと考えています。","id":"exchange-020"},{"speaker":"原委員","kind":"質問・要望","question":"品川区の意見を求められているというお話だったんですけれども、こういう動きの中で、他区はどういう対応をとろうとしているんでしょうか。いろいろあると思うんですが、その辺、考え方はどのようか尋ねました。","respondent":"藤田都市計画課長","answer":"そういった幅広い話になりますと、今回、東京都のほうでは全体の意見集約をすることはちょっとできないというふうに聞いてあります。特に影響の大きいところが大田区、江戸川区、この辺が品川区と並んでいろいろ考え方があるようだというふうには聞いてあります。","id":"exchange-021"},{"speaker":"原委員","kind":"質問","question":"関西なんかでもやってるんでしょうけれども、そういったところは、そういう手法をとるものですかね。今までのかつての例からいったりするとどうか尋ねました。","respondent":"藤田都市計画課長","answer":"その中で、この案については、この案は使えるねというようなことの最終的には組み合わせを行っていきたいというふうに国のほうは考えているようです。自区の部分、品川区の部分について、意見を述べていきたいというふうに考えているものです。","id":"exchange-022"},{"speaker":"菊地委員","kind":"質問・要望","question":"これができると１時間当たり１１便ですか、これが増えるんだと。これは、例えば今までの状況というんですか、八潮の上空を通過する状況と、どれほど違いがあるのかというのをちょっと教えていただけますか。","respondent":"藤田都市計画課長","answer":"近い空港から、飛行機の大きさの小さいものとか、そういったものが検討の俎上には乗っているというふうに聞いてあります。この都心ルート、これについては新たな騒音を住宅地に落としていくものだということで反対をしていきたいということで考えているものです。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問・要望","question":"先ほどの国際定期便ですか、韓国だとかそれとかというような便のお話なのかどうか、これはこれまで成田を利用していたわけですから。本来、ぜひとも私はこの辺については反対の声を上げていただきたいなというふうに思いますけれども、どうなんか尋ねました。","respondent":"藤田都市計画課長","answer":"成田空港のほうも、今大分容量がいっぱいになってきておりまして、２０１４年にはもう満杯になってしまうというふうに言われてあります。国際便の関係のほうは、また別に国のほうの政策の中で判断をされることだと考えておりますので、区の考え方を示したものです。","id":"exchange-024"},{"speaker":"藤田委員","kind":"質問・要望","question":"非常にこれは解せないルートじゃないかなという意味で、これは強力にひとつ反対していただきたいと思うんですね。十何年前ですか、かなり委員会でも反対があるという意見があったわけですけれども、あれは生きているんか尋ねました。","respondent":"藤田都市計画課長","answer":"現在、その辺の関係については、今、運航は実際にはなされていないというふうに聞いておりますし、今回拡張後については、その考え方はなくすというふうに聞いてあります。","id":"exchange-025"},{"speaker":"藤田委員","kind":"質問・要望","question":"その後、こうして上空を通っていないのでどうなっているのかなというふうに思っていたんですけれども、今の話を聞きましてわかりました。要望しておきます。","respondent":"藤田都市計画課長","answer":"国土交通省としては基本案というのをベースに考えてありますけれども、分散ケースについて考えてきているということで聞いてあります。じゃあ、５,０００フィート、あえてなぜ低い高度で市街地を飛ぶルートを設定する必要があるのかということで反対をしていくという考えです。","id":"exchange-026"},{"speaker":"山村委員","kind":"質問","question":"木更津の人たちが思っているよりも、普通の状態で飛行機がなくても都心では当然電車も多いわけですし、車も多いわけですから、騒音に悩まされている。反対していただくようにと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"不時着するスペースが何もないのに、ただそのルートを勝手につくるというのは、これは国土交通省のほうでも責任を感じていただきたい。何も事故を全く想定しないルート、それに対して必ず無事にある程度かなりの確率で着陸できる、そこも一つ要望させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]},{"id":"topic-05","title":"の東急目黒線（西小山駅付近）の地盤変状","agenda":"の東急目黒線（西小山駅付近）の地盤変状","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"鉄道工事の沿線の中で１００カ所ということなんでしょうけれども、とるべき手だてというのはとっていなかったんでしょうけれども、本来とるべき手だてというのはどういう流れなんか尋ねました。","respondent":"中島街路事業担当課長","answer":"地下水位の低下の原因が何なのかという原因を究明するのがまず第１だろうという考えでございまして、その原因究明に相当時間を要したということです。ここが原因だというような原始的な方法でしか調査できないところもございまして、今回そういう形で原因がわかった。","id":"exchange-029"},{"speaker":"菊地委員","kind":"質問・要望","question":"教えていただきたいのは、当然１年間通して言えば、地下水脈が増えたり減ったりとかというのは当然あるんでしょうから。例えば土壌を固めるような工事をしていくとか、そういうものというのはあるのかどうか、ちょっとその辺を教えてほしいと求めました。","respondent":"中島街路事業担当課長","answer":"専門会社の人の説明では、逆に地盤的には強くなる傾向があるというふうに、その専門の会社から説明を受けております。現在あわせて検討していますので、地盤環境の保全をしていくということは、事業者としてやっていくのが責務だろうというふうに考えてあります。","id":"exchange-030"}]},{"id":"topic-06","title":"５番目の報告事項、武蔵小山駅東地区のまちづくりの状況","agenda":"５番目の報告事項、武蔵小山駅東地区のまちづくりの状況","exchanges":[{"speaker":"山村委員","kind":"質問","question":"もう説明会が一応開かれているようなんですが、先ほど説明会の説明もあったと思うんですけれども、基本的には合意がすんなりいきそうなのかどうか。６０ｍぐらいとありますけれども、どこまで考えているか、そこら辺のことを詳しく教えていただけますか。","respondent":"上野都市開発課長","answer":"これまでかなりの、地元の方々の賛同を得ながら、この案の検討が進められてきたという状況にあるというふうな認識をしています。この方針、これから各ブロックごとにその辺の合意形成の手続を地元のほうで進めていただけるような手順になっていくというふうに考えてあります。","id":"exchange-031"},{"speaker":"山村委員","kind":"質問","question":"買い物客のための一時駐輪スペースなども設けていきますと書いてあるんだけれども、駐車場も設けたほうがいいんじゃないかと思っています。大体どのぐらいであらかた完成するというふうに予想されているというか、イメージされているのか教えていただけますか。","respondent":"上野都市開発課長","answer":"車の設置場所とかについては、これは個別の開発の中で、この方針の中では特にまとまって公共駐車場をつくるとかいう考え方は打ち出してございません。ただ、その合意が整ったところから順次進められていくというように考えてあります。","id":"exchange-032"},{"speaker":"山村委員","kind":"意見","question":"聞きたいところは、この再生地区区域というのは、拡大するということはあるのかどうかとの意見を述べました。","respondent":"上野都市開発課長","answer":"この地区内がうまく機運が高まっているところというふうに認識していますから、それを踏まえて地区を拡大していくということは考えられます。その辺の動きを見ながら、その辺の区域どりは検討していく必要があるというふうに考えてあります。","id":"exchange-033"},{"speaker":"井上委員","kind":"意見","question":"このまちづくり協議会の前にもご説明いただいたかもしれないんですけれども、申しわけないんですが、まちづくり協議会のメンバーがどういった方たちがここで組織されているかということと…","respondent":"上野都市開発課長","answer":"あるいはまちづくりの方向性についての検討とか、あるいは区に対しての提案とかいったものがなされてきてあります。その後、このまちづくりに関しても検討を進めてきたという経緯がございまして、まちづくり協議会が組織されているというものです。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"それと、昨年の秋ぐらいに、これと関係しているかどうか、西小山のほうの緑道の公募、そちらのまちづくりに関しても公募があったんですが、これとは全然事業が別か尋ねました。","respondent":"上野都市開発課長","answer":"西小山の公募そのものは、この事業とは関連してございません。独立したものです。","id":"exchange-035"},{"speaker":"原委員","kind":"質問・要望","question":"要するにこの制度の使い方、この街区再編まちづくり制度という中で、この地区について再生方針を決めていかれたわけですよね。うちのところもやってほしいよという、これは平成９年から働きかけて、その辺の状況をちょっと教えていただきたい。","respondent":"上野都市開発課長","answer":"この新しい制度を使ってまちづくりを検討してほしいというふうに地元の方から要請がありますのは、ちょっと私のほうでは伺ってございません。武蔵小山の事例を見ながら、それで同様な区に対しての支援の要望というものがあれば…","id":"exchange-036"},{"speaker":"原委員","kind":"質問","question":"もう１点だけなんだけれども、これは今３haですよね。もうちょっと例えば大きく広げるとか、あるいはもうちょっとコンパクトな形でという、そういう網かけみたいなものはあるんか尋ねました。","respondent":"上野都市開発課長","answer":"できないところができたときに、ある基本的な方針を決めまして、それで３haぐらいの広がりは必要であろうという趣旨から設定されているものです。それ以上のものであるのであれば、ある程度かなり広い範囲を対象として…","id":"exchange-037"},{"speaker":"菊地委員","kind":"質問・要望","question":"要望があった地区を設定しましたという話がありましたけれども、それだけの要望というか、ちょっとその辺を説明をしていただきたい。それぞれのブロックの中で、この考え方に沿って進めていくとすると、その辺説明していただけますか尋ねました。","respondent":"上野都市開発課長","answer":"ただ、やはり地元の方々の自主的な取り組みというのが不可欠になってまいりますから、区としては支援していきますというスタンスですので。それからあと、個別の建てかえでもある程度のものであれば個別でも対応ができるような、そういう方針にしたいなというふうに考えてありま…","id":"exchange-038"},{"speaker":"菊地委員","kind":"意見","question":"５１０名の方のうち３０名、正直言ってこの３０名の方が参加をされたというのは、ちょっとどうもそこがよくわからないんですよね。どういうまちづくり、自分たちのまちをどうするんだというところが話されたのかどうか、この辺はどうでしょうとの意見を述べました。","respondent":"上野都市開発課長","answer":"当分は建てかえ予定はないけれども、そういったところでは、かなりの地元の方々がまとまっておられるということは認識しています。ですから、あとはこの後、そこでやはり事業化を急ぐところについてはかなり合意形成を進めなければいけないでしょうという考えです。","id":"exchange-039"},{"speaker":"菊地委員","kind":"意見","question":"今の考え方でいけば、例えばこの６街区、一部のブロックが事業として進んでいく。その際、区というのはどういう立場と言うか、どんな指導をすることになるのかなというところをちょっと聞かせてくださいとの意見を述べました。","respondent":"上野都市開発課長","answer":"その中で空地を確保していきたいという考え方がありますし、駅前の密集したところでも、かなり動きが出てきているかなという認識をしています。そういう面では、それをさらに後押しするようなことが、区として今重要かなというふうに考えてあります。","id":"exchange-040"},{"speaker":"菊地委員","kind":"質問","question":"とりあえずブロックごとにこの構想に沿ったまちづくりを考えてくださいというわけですから、１年間で住民の皆さんがまとまって、それで黙っていれば。だから、そういう可能性は生まれてくるわけですから、そのときのもう少し区としての具体的な指導の部分というのが聞きたいんです。","respondent":"上野都市開発課長","answer":"せんだっての説明会でも質問が出ておりましたけれども、区としてもぜひ地元でブロック別の話し合いを進めていただきたいという説明をしています。まずこうして住民説明会などもそうですけれども…","id":"exchange-041"},{"speaker":"須貝委員","kind":"質問","question":"その辺は、中にはほんとうに木造２階建て、そういう小さな住宅もあります。その辺の心配というのはどうなんか尋ねました。","respondent":"上野都市開発課長","answer":"各ブロックごとでの詳細についての検討がなされるのかなと考えてございまして、そのときに、共同化はどうしても避けたいんだと。もしこの考え方に賛同していただければ、そういったものの中で、いろいろと納得していただきながら進めていただければなというふうに考えてあります。","id":"exchange-042"},{"speaker":"須貝委員","kind":"質問・要望","question":"ぜひ、新しい制度ということで成功させていただきたいということと、そういうふうな長年住まわれている方がいますので、今度建て直ししようとしたら建てられなくなったという状況だと非常にまたトラブルのもとなので、その辺のご配慮を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"藤田委員","kind":"質問","question":"ほんとうに新しいまち、魅力あるますますよいまちになっていくんじゃないかなと期待しております。１点だけなんですが、こういう絵は、これはどなたが描かれたんか尋ねました。","respondent":"上野都市開発課長","answer":"先ほどの地元の協議会の組織でもって、既に平成１５年１月に１回方針というものを取りまとめてありますけれども。区としての考え方も伝えまして、そういう中で一緒に検討しながら、たたき台は地元の組織でもって検討されてきたものをたたき台としているです。","id":"exchange-044"},{"speaker":"藤田委員","kind":"質問","question":"おそらく皆さんが集まっていろいろ協議されていると思うんですけれども、やはりどうしても素人といいますか、その分はあると思うんですよね。まちづくりのアドバイザーというんですか、それからまちのにぎわいも知っている、そういう専門家をこの地区に派遣ができないかということなんです。","respondent":"上野都市開発課長","answer":"この案をいろいろと検討してきたという経緯がございまして、その調査につきましては、そこの顧問をされている建築事務所に業務委託をしています。これからもかかわっていくという認識で、区としては対応してございまして、かなり動いていただいているという状況です。","id":"exchange-045"},{"speaker":"藤田委員","kind":"質問・要望","question":"ほんとうにいいのかどうかというのを、このわずか３haの中ですけれども、支援をお願いしたいなと考えています。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"菊地委員","kind":"質問・要望","question":"１点だけ要望があるんですけれども、土曜日に開かれた説明会と、これから木曜日に開かれる説明会での、住民の皆さんの意見をまとめたものを資料としていただきたいんですけれども、いかがでしょう。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]},{"id":"topic-07","title":"６番目の木造住宅耐震診断支援事業の概要","agenda":"６番目の木造住宅耐震診断支援事業の概要","exchanges":[{"speaker":"山村委員","kind":"質問","question":"１２万円というお金の大体算出方法というのを聞いてみようかなと思うのが１つと、あと、これでほんとうにものすごく危ないということになった場合、その助成について区としての対応はどのように考えられているのか教えていただけますか。","respondent":"片田建築課長","answer":"１５万円が１２万円になったというのは、トータルの当初予定の金額を、下まわったものです。どういう区として対応を考えるかといったご質問ですけれども、変更したり進めてありますので、そういう方法になっています。","id":"exchange-048"},{"speaker":"山村委員","kind":"確認","question":"この昭和５６年６月１日以前に建築確認を受け建築されたもの、対象建築物というのは、予定件数は４０棟ですけれども、大体区内でどのくらいあるというふうに予想されているんか尋ねました。","respondent":"片田建築課長","answer":"平成１３年の土地利用の現況調査、それで住宅系と住宅以外の事務所系とか、振り分けた調査棟数があります。約７５％ぐらいが住宅だということで、それが大体昭和５６年以前に出されたものが、大体半数を占めているという認識の中で大ざっぱですけれども。","id":"exchange-049"},{"speaker":"山村委員","kind":"意見","question":"２万あって、予定件数４０棟。どうにかこの診断する件数を増やすために、例えば助成をもっと増やすとか、今後もっともっと増やしていかないといけないと思うんですけれどもとの意見を述べました。","respondent":"片田建築課長","answer":"できるだけの利用者を見込みたいということで、そういうことを十分含めて、一応このぐらいで計算を組みたい。なおかつさらにもっと行いたいというようなことがあれば、区としても十分ケアしてまいりたいと思いますので、よろしくお願いしたいと思います。","id":"exchange-050"},{"speaker":"山村委員","kind":"質問","question":"こういう木造の例えば建築物というのは、一般的には何か診察しなきゃいけないとか、そういうことというのはは全くないと思っていいんですか。ある程度年数がたったら、そういう診断をするとかいうようなのは、現在ないんか尋ねました。","respondent":"片田建築課長","answer":"平成７年の阪神・淡路大震災の後、建主あるいは所有者の方の努力義務ということで、法律そのものが遡及適用するというものではない。ただ、増改築する場合には、一応それはきちっと現行法に合わせていただくといったような方向で考えてありますので、そこまでは決めないです。","id":"exchange-051"},{"speaker":"須貝委員","kind":"確認","question":"この補助する金額というのがむだになると言ったら失礼なんですけれども、やはりせっかく我々区のほうで出すんですから、有効に使ってもらいたい。その辺の認識、確認はどういうふうに。","respondent":"片田建築課長","answer":"区も当然立ち会うという形で建主のほうにお伺いして、お話をして、きちっと図面として残っているのは十分問題ないとする。ほんとうに次のステップとして、ヒアリングも含めてお話を聞いた上で、有効に使われるような方法を考えていきたいということで考えてあります。","id":"exchange-052"},{"speaker":"須貝委員","kind":"意見","question":"先ほど山村議員からも言われましたけれども、ほんとうに４０棟というのは、やはり相当区民の中には、もうぜひ見てもらいたいという宣伝、パンフレット、案内等によっては殺到する場合も出てくるかもしれないので、その場合にはぜひ、何とかもっと棟数を増やしてやる予定等…","respondent":"片田建築課長","answer":"先ほど当初予算の中で１５万円として見ています。今１０件ぐらいと見ていますけれども、後々の事務事業評価もありますことですし、いろいろ検討してまいりたいと考えています。","id":"exchange-053"},{"speaker":"藤田委員","kind":"質問・要望","question":"どういう方法で診断をするのかというのを一つ教えていただきたいのと、この人はいいですよと、所得の多い人はだめですとかありますよね。もう受けた人から、はい、結構ですやってくださいというふうに言っていくんか尋ねました。","respondent":"片田建築課長","answer":"あるいは耐震診断マニュアルというものを出していますので、そういうものを十分活用した中で進めていただくということで考えております。ある程度見れば、これは分別すべきこともわかりますので…","id":"exchange-054"},{"speaker":"藤田委員","kind":"質問","question":"よくわかりませんけれども、建物の修理では、そういう図面というのは皆さんお持ちなんですかね。最近の住宅か何かは、手抜きだとか何とかいろいろ言われていますけれども、古い家ほどきちっとなっているわけなんですがどうなんか尋ねました。","respondent":"片田建築課長","answer":"具体的にはなかなか３０年もたつと、ご自分で図面を持っていらっしゃらない方のほうが割合としては多いんじゃないかなと思います。ただ、マニュアルがありますので、それに基づいた形で進めたいと考えています。","id":"exchange-055"},{"speaker":"原委員","kind":"質問・要望","question":"それからもう一つは、今、お話に出てきました４０棟ですか、１０棟ぐらいは予備があればという話ですけれども、この選択の方法なんですね。そうすると、順位づけみたいなものも出てきて、危なそうなところから随時やるとか、どういう形でその４０棟を選択していくんか尋ねました。","respondent":"片田建築課長","answer":"アドバイスしたほうがいいというふうなところで、きちっと受けて対応していくような方法になります。ただ、ほんとうに４０棟をオーバーしてしまったということになれば、またいろいろ予算のことを含めて、検討させていただければと考えています。","id":"exchange-056"},{"speaker":"原委員","kind":"質問・要望","question":"順位づけは別にどうでもいいんですけれども、もしたくさん要望があったときに、そこのところをちょっとはっきりさせたかったんですけれども。申請を出してから、行きますよという結果を学ぶまで、時間的にはかなりかかっているんじゃないかなと思うんですが、どうなんか尋ねました。","respondent":"片田建築課長","answer":"やっぱり人手をもたせて図面の作成とか計算などを行いますので、その辺はやはり１週間ぐらいあればできるなと考えています。先ほど言った３週間ぐらいでできるんじゃないかなと考えていますけれども、その辺はできるだけ圧縮していきたいということで考えております。","id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/107143?Template=document&Id=3778#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":52129,"voices":161}},{"id":"h16-20040414-12","meetingId":"h16-cm04","date":"2004年4月14日","dateIso":"2004-04-14","committee":"清掃制度特別委員会","time":"午後１時０４分～午後３時２８分","status":"正式会議録","sourceType":"formal","overview":"清掃制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件整理しています。","topics":[{"id":"topic-01","title":"各戸収集の実施状況","agenda":"各戸収集の実施状況","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"各戸収集にまつわる、道路幅員が４ｍ以下の密集した場所について軽自動車を使っているというんですけれども、本区において軽自動車はどのぐらいの数で稼動されているのか、教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"従来から狭小地対策に稼動をしているものがございまして、直営の清掃事務所に配備している車両と、雇い上げているものがあります。総台数ですけれども、品川清掃事務所が７台、荏原清掃事務所が６台、合計１３台です。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"それも一つの特色というか、そういう意味でやっているんだろうけれども、２３区の状況というのはつかめるんですか。もう１点、荏原、品川のバランスは今どういうふうになっているのか分かっていたら説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"課長会等をやっているわけですが、そういう中で移管以降の独自の取り組みについて集計しようという動きがございまして、集計した経過があります。もとより世帯数が品川清掃事務所の管内が約６割ぐらいになっておりまして、４割が荏原清掃事務所ですから、ほぼ五分五分の状況です。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"意見","question":"工場がない区がどういう特色を出しているのかとか、あるいは出しづらいのか、清掃制度特別委員会も５月の何日かにもう一回あるでしょう。一部事務組合をどうするかを、我々の収集・運搬にどう影響があるのかというのも、これから考えていかなければいけないと思うんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問","question":"どういう予定で全戸に持っていくという、大体来年度どれぐらいまでに持っていって、最終的には平成１８年度に終わる。そういうことも含めて、人員的にどれぐらいの配置を考えておられるのか、そこら辺の点もお聞かせ願いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"今年度約１２万世帯というところの拡大に、約１０台ぐらい台数を新たに検討していますが、事業の見直しで捻出するという考え方を基本にしております。できるだけコストについても既存の事業の見直しの中で圧縮していくということを従来どおり基本に努めてまいりたいというふうに…","id":"exchange-004"},{"speaker":"石田委員","kind":"提案","question":"今のお考えは何回もお聞きしているんだけれども、いろいろ我々の思いをするところは地域処理というところの部分の話とかも提案しているわけで。そういう点のお考えも資料としてお出しいただけるなら、それとも、これはお願いしておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"平成７年のときですけれども、私は平成７年のしか見ていないんですけれども、新しい資料ができているのであればこの次に見せていただきたいなというお願いです。","respondent":"中山清掃リサイクル課長","answer":"平成１１年度はその研修というよりは、移管の実務になっておりましたので、平成１１年度は発行しなかったです。清掃移管後も協議会、これは必要に応じて資料提供はできようかと思いますが、派遣記録はそういうことで平成１０年度で終わっておるです。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"各戸収集がすでに始められていて、目的のところには、美観向上を図るというのがありますけれども、地域の方に伺うと、美観向上が図られていない。近くなったということで、メリットもあるかもしれませんけれども、どういった声が上がっているのかを教えていただけますか。","respondent":"中山清掃リサイクル課長","answer":"排出者自らのことを考えていただく施策ということで、１カ月経つぐらいの間には、そういう意味では好評の声も伺った例も結構あります。いずれにしても、そういうさまざまなご意見をいただきながら、まだ改良できる余地があれば、曜日も含めて検討をしていきたいと考えています。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"平成１６年度に拡大して、７割カバーできたということですけれども、平成１７年度中には前倒しで全部終わりそうだということです。残りの３割の地域というのはどの辺が中心になっているんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"ある地区を実施しますと、隣接のところから広げていくような形になりますので、どうしても地域的に空いてくる部分があるのは事実です。四万世帯ということで広うありますので、先ほど申し上げたようなペースをなるべく上げて…","id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"裏面で１０月までに新規に実施していくということですけれども、平成１７年度はこうやりますよというような形での広報というんですかね、その辺の周知徹底の仕方はどういうふうにしていくんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"広報紙等でも施策の方向性としてという紹介をしたことがあるんですが、そういう具体的なエリアを入れての広報等はやっておりませんでした。そういう具体的なエリア等残りの地区についても速やかに進めていく予定というふうなことも含めた広報を今後考えていきたいというふうに思…","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"そのときの施策というんでしょうか、それに関係しているという考え方はないんですか。都派遣職員の比率が低いですから、いろいろなことを踏まえての施策、そういう考え方というものはなかったんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"施策を進めていくわけで、あまり身分切り替えを意識した施策というのを考えて、こういう施策を実施してきたという意識はございません。ただ、先ほどもさらにいろいろな取り組みというお話もございましたけれども、発展させていくきっかけにはなろうかなというふうに思ってありま…","id":"exchange-010"},{"speaker":"本田委員","kind":"質問","question":"先ほど車を１０台増やして、車も今までよりも多くなければ、お金がふくらんでいくんじゃないですかというような話も聞きますよね。具体的には減量というのがどういうふうにあてがわれてくるのか、どうつかんでいくのか、その辺をちょっとお尋ねしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"今までは集積所エリアの車と各戸収集のエリアの車が混在してというか、その年度の地域の拡大の数値を測るのが難しい部分がございました。いずれにしましても、より精緻な全体量の件数というものは、今回の拡大に合わせてきちんと把握していきたいというふうに思っております。","id":"exchange-011"},{"speaker":"本田委員","kind":"意見","question":"７割実施ということになれば、車の配置の問題など、プラスマイナスいろいろ出てくると思うんです。そういう点が数量的に見えるように、本年の施行の中で見えるようになるようにひとつお願いをしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"}]},{"id":"topic-02","title":"番目の特定事件調査を行います。 前回の委員会において、東京二十三区清掃一部事務組合に係る考え方","agenda":"番目の特定事件調査を行います。 前回の委員会において、東京二十三区清掃一部事務組合に係る考え方","exchanges":[{"speaker":"本田委員","kind":"質問","question":"これまでいろいろ発言をしてきたことをまとめられているようですが、今の委員長の言っていることは、これはまとめて品川区長に出すんですか。いわゆる委員会として１年間こういうことを議論しましたというまとめ文なのか、どういうふうに使うということでしたか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"本田委員","kind":"質問","question":"当清掃制度特別委員会として１年間こういうことを議論し、最終的にこういう文書にまとめましたということで、議長に報告をするということで、これからいろいろとそういう文書をまとめるための議論をするというふうに理解してよろしいんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"土井副委員長","kind":"意見","question":"その中に東京２３区清掃一部事務組合のことがある。議長のほうからそれ以降の扱い等についてはお願いをするなり何なりという形で進めるべきではなかろうかと、こんな議論をしておりますからとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問・要望","question":"今のところの確認だけしますと、議長に対する報告という形の文をここで確定をさせていくという理解でいいんでしょうか。どういう要望をということの判断はということで、その要望をしたものを、そこら辺の確認をまずしていただいてからのほうがいいかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"土井副委員長","kind":"質問","question":"そんなことがあるものですから、２３区の一部事務組合の議会にお願いをするという動きがあったり、ご出席もいただいていることですから。したがって、皆さんのほうからも、その思いですよということで一致をすれば、非常にありがたいということだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"本田委員","kind":"意見","question":"非常に大きな変化がこの１年間の中で起きておりまして、そこで当然会派によって、何が重要問題かというところの捉え方など。焦点をどこに定めていくのかなと、正副委員長のところではその辺の一つがどういうふうにされて出てきているのかなというふうに思っているんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"土井副委員長","kind":"質問","question":"これは区長にお話をするべきことだという、若干の整理もしていただける場合にはしていただいて、出していただく。したがって、少なくとも我々の議長にお願いをするわけですから、そういうふうに思ってまとめていただければいいんじゃないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"土井副委員長","kind":"意見","question":"議長も困りますからね。そういう考え方でおりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ですから、１年ごとに、こういうことをやったという報告書を議長に上げる。その報告の内容をどうしようかという議論に入っていくわけですから、なるべくなら１本にまとめようよということなら、まとめればいい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"平成１７年度末という時期があるわけですから、うちの内部で話をしていてもどうしようもならないことで、そういうところへいかなければならない。まだ平成１７年度末というのは時間的にはあるんだという考え方と大きい違いがあるので、その辺、共産党の意見を聞かないとまとまらないと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"１番目ですと、先ほどからの論議ですけれども、区長会でもう一度このことについて話し合えということを区長に求めるのかどうかというと。前段になっている重要性という部分では、一切変わるものではありません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"質問","question":"「今の時点では、区が独自性を出して何か方向を出すという時期ではない」、これは何を言っているんですか。区が独自性を出してというのは、どこで区が独自性を出すという意味なんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"中塚委員","kind":"意見","question":"ない区もある中で、そういう事情をきちんと踏まえた上で議論をしていかなければいけないんじゃないのかなという意見を述べさせていただきました。清掃事業をきちんと区に移管する方向というのは当然必要であるだろうし…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"林（宏）委員","kind":"意見","question":"何もしないで見ているだけという考え方なのかなと、この文章だととれるから、説明をしてください。あなたの答えはまるっきり答えになっていないとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"菊地副委員長","kind":"意見","question":"当然区として、私たちの委員会として、区長会にしろ何にしろ働きかけをしていくことはもちろん重要なことだと思っています。結果的に当分の間このまま一部事務組合を存続するんだという方向性が出されてきたことに対して何もしなくてもいいという意味では決してないですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"意見","question":"方向という字が二つ書かれていて、これは同じ意味なんでしょう。一部事務組合の方向という意味なんでしょうとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、一部事務組合の方向が出されたから、今はそれに沿っていくべきだというふうに、この文章を読みと受けとるんだけど、それで間違いありませんかとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"菊地副委員長","kind":"意見","question":"前回の中塚委員の発言をひもといて、もう一度明確なお答えをします。どうしても繰り返しになっちゃうんですけれども、決して区が何もしなくてもいいんだということを言っているわけではありませんとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問","question":"方向を出すという時期ではないというのは、どういう意味か尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"ここは後ほどもう一度ひもといてお知らせをさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"土井副委員長","kind":"質問","question":"しかるべき取り扱いをしていただく、ここを何か構造体にすべきかどうかという議論もあったわけですから、今のご発言なんだと思うんですよ。ですから、前回の委員会でのご発言の中から言葉を取ってまとめさせてもらっただけなものですから、まとめさせていただけるとありがたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"本田委員","kind":"質問","question":"別の、一部事務組合はこうあるべきだというような問題提起を、そういう形でこれはしようがないのかなというふうに今受け止めているんです。具体的にはどういうふうにこれを詰めていくかという問題などあるわけで、再考するように、この辺はどうなんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"林（宏）委員","kind":"質問","question":"だったら、もっと早くからやるべきじゃないんですか。もうしようがないや、方向が決められたんだから、このまま平成１７年度末、平成１８年４月以降どうするかという話に今度は移るわけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"本田委員","kind":"質問","question":"この方向を７月、それはそういう方向でいくんだという形でいろいろなもろもろの作業が進んでいるというふうに理解してよろしいんですか。それをもう一回聞きますよというような状況に今あるんか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"大まかに言えばそういうことですが、この４月にまた人事異動がありましたので、実は今日も部長会がありまして、やっているはずです。今日は代理で課長が行っておりますけれども、そういう中で、もうちょっと具体的な姿が見えてくるです。","id":"exchange-036"},{"speaker":"本田委員","kind":"確認","question":"１１月１４日の決定、区長会の方針とするということを確認するということで、いろいろな経過等の説明を受けたわけです。ですから、今の部長のお話ですと、こういう方針を受けて、一部事務組合のあり方について細々と改革案も含めて詰めているということなんか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"この委員会も含めていろいろとご説明をしている方向性をそのままほかの２２区がある中で、そのまますーっといっているかということではありません。私は会議に出ていないですから、わからないですが、いろいろとほかのルートで聞いた限りでは…","id":"exchange-037"},{"speaker":"本田委員","kind":"質問","question":"今のようなお話を伺いますと、平成１２年から始まった方針からすれば、条文上もそうなっているわけですよね。どうなんですか、今までの報告とちょっとニュアンスが違ったように受け止めるんですが。","respondent":"中尾根企画部長","answer":"今のは、先ほど環境清掃事業部長が言った、それは事務的な流れであるとか、今組織の内部で起こっている状況の説明としてはそういうことだと思います。考え方がどっちに転んでも、また、動いていきますということがお答えになると思います。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"確認","question":"ほかの会派は確認していないけれども、自民党の会派はそういうふうな読み方をしていた。ですから、うちの考え方を、あの文章の中に汲み取るということをまだ言っていけるだろうと僕は思っているんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"本田委員","kind":"質問","question":"今の話は、これまでも理事者からの報告で、そういう報告だったんじゃないですか。いわゆる平成１２年から出発する。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"石田委員","kind":"質問・要望","question":"さまざま認識の問題がまず違うとするならば、区長の部分でも本当に認識をしながら、区長会でそういう確認をしたのか。そこの場所で同じような確認をされたから同じようにいくかもしれないけれども、これを再考するように求めていく期間が、各区に。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"林（宏）委員","kind":"意見","question":"なぜ決めたかというと、６年間という理由があったんです。こういうところに入っているというのを、これは私見も大分入っていますけれども、思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"本田委員","kind":"質問","question":"直接一部事務組合から状況を聞いたなどというのはないわけですから、この１年間、６区については工場をつくらなくてもいいと。改めてもう一回強く平成１２年の時点に立ち返って、再度検討をしろというようなことを言うことが適切かどうかというのは、聞き直したわけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"土井副委員長","kind":"質問","question":"そして、そのほかのこと等については、当然の話の中身ですから、その辺をベースにしてまとめていったらいいのかなと思いました。それはそれで約束どおりですから、１番と５番が融合して、読ませていただいたです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"土井副委員長","kind":"質問","question":"質問も含めて、この前のいろいろな決定等とか、あり方論議等々の中で、一部事務組合職員の採用云々という話がありましたね。我々が入れるにも、何かそれを入れておかなければいけないのではないかなという感じを持ったものですから、発言をいたしました。","respondent":"中山清掃リサイクル課長","answer":"１１月の区長会決定以降の清掃事業の検討課題の２４項目の中に、基本の部分で検討をしている、こういうこともあります。いずれにしましても、組織の部分と、人的な面の残りの課題については、まだあるなということで現在検討をしているという状況です。","id":"exchange-045"},{"speaker":"石田委員","kind":"質問・要望","question":"副委員長のさっきの部分、もちろん我々もその話を考えながら４番はつくっているつもりでありまして、あえてそこに触れなかった部分もある。今ちょっと話に出た部分は、直接的な触れ方はというような意味合いがあって、こういう文章になっているということをご理解ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"若林委員","kind":"質問・要望","question":"普通特別区以外という呼び方でいいんでしょうか、当然２３区、品川区にもそういうものがありません。これがずっと、基礎的自治体としての私たちの真意というんでしょうか、そこら辺の理解の仕方を教えてほしいと求めました。","respondent":"市岡企画財政課長","answer":"１点は、都から区へ移管したわけですから、これは区がやっているわけです。今、実態としてこういう共同処理の仕方が基礎的自治体の内実を貫いていくものなのかどうなのか、こういうご議論になろうかと思います。","id":"exchange-047"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"最初に平成１２年からスタートしたのは、そういった意味ではちょっとイレギュラーなんですよ。それはシチュエーションとしてはやむを得ない選択だったと僕は理解しているんだけれども、間違っていたら補足をしてほしいと求めました。","respondent":"市岡企画財政課長","answer":"間違いとか、そういうことではないんですが、一応形の上では、この一部事務組合も各区が協議して設立しております。","id":"exchange-048"},{"speaker":"土井副委員長","kind":"意見","question":"何かしないと、何かみんな持っていっちゃうという感じに見えちゃって、なかなか難しいなという感じ。唐突さを覚えるというのはそこなんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"林（宏）委員","kind":"意見","question":"その職員を、ではどうするという話になったら、必ずや大きな問題が出てくる。それは当分の間というのがエンドレスになりかねない大きな問題であるというふうに僕は感じているとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"大西委員","kind":"質問・要望","question":"本来平成１２年度に決められていた移管をすべて行うようにやるべきであるという、もっと強い前文にすべきじゃないかと思うんです。もし間違っているなら、どういう点が間違っているのかわからないので、少しご意見をいただきたいんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"林（宏）委員","kind":"意見","question":"この文章の中で、平成１７年度末までに解散すべきであるというような意味合いを明記しちゃった場合、僕らはもうそう思っているわけですよ。これは特にという部分で挙げていったのが下の５項目になってくるわけで、決して間違いじゃないんだけれども、そういうふうに僕は感じますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"石田委員","kind":"質問・要望","question":"それに基づいて、以下の事項を要望しますよということで、先ほど来１番と５番は非常にお話が出ておりまして、ここでは省かします。その間には２２区に質問状を配布し、この５項目ではないかということになりまして、意見として要望を出させていただいているということであります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"林（宏）委員","kind":"意見","question":"２の中の、自区内処理という大きな問題のハザードというか、ない区は絶対的に今のままやってほしいと言っているわけです。そういう資格を持っている人たちは民間にたくさんいるんだという意味も含まれている民間ということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"井上委員","kind":"意見","question":"平成１７年度末までに残された課題を解決していくという、そういったところをさらに検討していってほしいというところで。こういったところにそれが反映されているということだと思っているので、ここのところでは特別な意見ということはありませんとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"中塚委員","kind":"意見","question":"４番のなお書きの後なんですけれども、十分な説明や論議を重ねていく必要があるのではないかなとは思うんです。なお書き以降は、まだ審議は尽くされていないんじゃないのかなと思うので、違和感を感じますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"若林委員","kind":"質問","question":"２番目の「自区内処理の原則を視野に入れつつ」、これは「踏まえ」というようなニュアンスなのかなというふうに思ったんですが、いかがでしょうか。「自区内処理という原則を踏まえながら、地域処理」というふうに、日本語で正しいかどうか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"石田委員","kind":"意見","question":"踏まえちゃうと、それに拘束をされる部分が出てくるという考え方で、見えるところの視野に入れておくよと。それは地域処理体制に向けていくんだから、視野に入れておくよという意味合いで、こういう言葉を使いましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"若林委員","kind":"意見","question":"説明を受ければ受けるほど、自区内処理という言葉を抜くと、どうなっちゃいますかね。原則を、視野に入れると聞けば聞くほど、「踏まえ」のほうが日本語としては趣旨に合っているのかなという思いを強くしたんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"林（宏）委員","kind":"意見","question":"現在みたいな技術では千代田区内に清掃工場はほとんど９９.９％ぐらい不可能だ。自区内処理というのは見ているよということの意味があるんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"若林委員","kind":"意見","question":"自分の言葉としては、１回否定されたものを自区内処理という言葉を土台に踏まえて、そういう問い掛けをさせていただきました。理解の仕方は委員の言い方と全く同じですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"堺委員","kind":"意見","question":"強いて申し上げれば、公明党としては１番、２番、そういう言い方で申し上げたわけですが、これが具体的に申し上げるとすると、自民党が示してくださったような五つの項目になるというふうに理解をしておりますので、委員長が示されたように…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"土井副委員長","kind":"質問・要望","question":"３行目のところの「このような立場から、以下の事項を要望する」というところについて、議長に対してどうするということが大前提ですから。最低５番のところはやってくださいよというふうにつなげて、そこら辺をちょっと議論をしていただければまとめやすいんじゃないかなと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"本田委員","kind":"質問","question":"２３区でどう協力して、議会の中でもいろいろな議論を区長は受け止めておきながら、そういう判断をされたというふうに理解をしていたわけです。ですから、今いろいろと２３区の中でもあるという話ですから、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"林（宏）委員","kind":"意見","question":"だれがということは、できる人は、例えばそれぞれの会派で２３区の中で連絡会みたいなものがあるでしょう。自分たちのできる活動の中にこの考え方を訴えてもらうという意味だったら、手法は要らないとの意見を述べました。","respondent":"中尾根企画部長","answer":"運動というのは強くいけませんので、そうすると、その辺のところのすり合わせは非常に必要なのではないかというふうには受け止めました。委員のおっしゃっている意味もよく分かりますけれども、そういう手続きがむしろ必要なのではないかというふうにちょっと受け止めました。","id":"exchange-065"},{"speaker":"林（宏）委員","kind":"確認","question":"あるいは部長の立場で強く言っていってほしいというのは、この中のニュアンスとして入っているんだという、「すべきである」という中には。そういうのをこの委員会で確認するように、どうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"石田委員","kind":"意見","question":"先ほど説明した１番の考え方が前提で、こういう考え方を出すのであれば、今みたいな形で「すべきである」という形のほうが、あるいは「考え方を出す」という形であるならば、それでもいいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"土井副委員長","kind":"質問","question":"ということであれば、まとめる立場で話をしますので、「方針を再考すべきと考える」という形でよろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"本田委員","kind":"質問","question":"ない区に対する問題意識も議会の中で持っているんだというのが２番のところでしょう。ですから、１番のところで考え方を明確に示しながら、こういう記述になっていけばいいんじゃないですかね。","respondent":"中尾根企画部長","answer":"１番はそれでいいんですが、その上のところですね、「このような立場から、以下の事項を要望します」という要望事項としたときに、考えるという表現が要望として通じるかどうかというのは、今ちょっと心配になりまして、この辺はもう少し整理される必要があるかなと。","id":"exchange-069"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"だから、全体を何を出すかというものは、さっき報告はするということなんだけれども、この文章を委員会としての何にするかで、今言った、要望するのか、決議をするのか、意見書を出せというのか、いろいろ変わってくると思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"土井副委員長","kind":"質問","question":"議長にお渡しするのは我々の仕事ですから、これは必ずやらなければならないことですから、ここまでは当然のことです。済むということにしておかないと、決めていただかないと、我々もやりにくいものですから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"若林委員","kind":"質問・要望","question":"例えば要望事項になるんでしょうか、それがそのまま皆さんの意思によっては区長にいくとか、関係各所にいくとかということなんでしょうか。そういうフォームに書き替える、とりあえずここでまとめるのは、あくまでも議長に報告をする内容を吟味しているということじゃないんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"土井副委員長","kind":"質問・要望","question":"ここで決議しなければどうにもなりませんし、それを踏まえて、そのように「よしなにお願いします」とかと書かなければいけないわけですよ。ですから、議長に言うんですから、決議文の形につくり直さなければいけない。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"林（宏）委員","kind":"意見","question":"もちろん議員に諮ってだけれども、区長部局、行政側に議会の意思として伝えてくださいという形でないかなと思いますね。議長会に物を申すとすれば、またそれなりの意見書なりそういうものになっていくから、この後になるんだろうと思いますけれどもねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"本田委員","kind":"質問","question":"議長に報告をして、この１年間当委員会はいくんだと思いますけれども、当然今回のまとめに基づいてこれからの１年間また継承されていく。どういうふうにするかわかりませんが、流動的に動いていくわけですから、議会としてはやったほうがいいんじゃないかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"大西委員","kind":"質問・要望","question":"先ほどの議会の事項を要望するということなので、「再考すべきである」というふうにしないと、かえっておかしいと思います。「再考すべきであると考える」という形に、「考える」を入れてしまうと、要望にならない。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"石田委員","kind":"質問","question":"時期尚早という意味がどういう意味なのか教えてもらえたらありがたいんです。内容を含めて。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"中塚委員","kind":"意見","question":"特別委員会の中でいろいろ審議がありましたけれども、民間委託については、僕の受け止めとしては、今日この場が初めてかなと思いますので、最後に出てきた時期というのがよく理解できないので、何でこの時期なのかと思っているだけですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"石田委員","kind":"質問・要望","question":"１１月以降、それからどういう形だというと、それを特別区で職員としていくのはというような考え方も出てきているんだと。具体的などういう部分かということを示していただきたいということを、我々はそういう説明を受けたと思って、このことを書いているということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"本田委員","kind":"意見","question":"だから、一部事務組合そのものをスリム化していくという方針が出ているわけだから、それはもうそう受け止めるべきだというふうに私は思います。文章上はお任せしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"土井副委員長","kind":"意見","question":"今お話のあったように、特に技術系の職員を中心とした意味での発想等があるということなんです。ここは大変重要な話なんで、まとめるのを任せると言われたって、大変困るんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"菊地副委員長","kind":"意見","question":"正副委員長という立場で言わせてもらいますと、今のところは文言として、民間活力に係わってくるという話が出ましたけれども、正副委員長のほうでまとめさせていただければなというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"若林委員","kind":"質問・要望","question":"１番と５番は文言整理をするという方向なんでしょうか。それだけ確認をさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"石田委員","kind":"質問・要望","question":"要望という言葉の対応することも含め、５番でそれにつなげていくということも含め、それもお考えいただいてということでいいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/987464?Template=document&Id=5634#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=12&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":38563,"voices":149}},{"id":"h16-20040414-16","meetingId":"h16-cm04","date":"2004年4月14日","dateIso":"2004-04-14","committee":"街づくり特別委員会","time":"午後１時０４分～午後３時５７分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"平成１５年１１月に、下水道事業促進に係る２３特別区連絡会が要望書を出されていますよね、ご承知のように。２３区の区長が名前を出して要望をして、どう聞いたらいいんですかね、答えられるところだけ教えてほしいと求めました。","respondent":"矢部下水道河川課長","answer":"頭から１０％カットとか、東京都の中の組織として、やはりそういうものに合わさざるを得ないというところがあるという説明を聞いております。２３区の要望書を持って行って、そうなのかということで、非常に役立っていると聞いております。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、当初、品川区がさまざまな計画を、下水道整備事業をやっていますよね。そういう計画の進捗に、この東京都の予算の規模でおくれは出るんでしょうかということをお伺いしたい。","respondent":"矢部下水道河川課長","answer":"やはり、緊急性の低いものについては、当初計画には載っていたけれども先送りしたという事業があるとは聞いております。ただし、品川区に関しては、先送りになったという事業については、私のほうでは聞いておりません。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"例えば、将来その分を東京都からもらえるという約束を取り付けた上で、品川区が事業することはできるんでしょうか。それから、そういう東京都と品川区の財調との関係の中で、できますかということをお伺いしたいんです。","respondent":"矢部下水道河川課長","answer":"下水道事業につきましては、公益義務ということで、その対象になってないんです。ですから、やはり受託か、あるいは下水道局みずからやっていただかないと、それを後からもらうという形はできないと思います。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"１点だけ言っておきますけれども、現状の仕組みはそうかもしれませんけれども、でも、この特別委員会でやってきたことというのは、そうは言うものの、現実は大変だということをずっと述べてきたわけでありますから、そういう仕組みの中で、さらに要望していただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"藤田委員","kind":"質問・要望","question":"中延５・６丁目の水害防止対策なんですが、今、説明を受けまして、一歩前進したなと考えています。やはり東京都のほうに要望活動をやってきていますので、地域住民が非常に被害をこうむっている、その辺についてのお考えをお聞きしたい。","respondent":"矢部下水道河川課長","answer":"何か月という細かい数字はちょっと聞いてないんですけれども、ただ、今年の雨期までに完成するというのはちょっと厳しいかと思います。説明会なんですが、そういうのがはっきりした段階で、地元のほうに入っていきたいと考えています。","id":"exchange-005"},{"speaker":"藤田委員","kind":"質問・要望","question":"要望だけにしておきますが、やっぱり早めてもらうというのが品川区としての立場だと思うんですけれども、ぜひそれをやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、中川邸の跡地に公園をつくるということで、あそこの地下に調整池をつくれないかという要望が地域の方から出されているんです。溢水対策の４５cmの８０ｍの排水管をつくることで、予算がどのぐらいかかるのかということについてもお聞かせほしいと求めました。","respondent":"矢部下水道河川課長","answer":"先ほどちょっとご説明いたしましたけれども、やはり中流部の工事の完成、それと並行してというのは非常に厳しいのかなという感じがしております。貯留管もやっておりますけれども、同じような理由で、ちょっと厳しいかなという感じがいたします。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明会のことは、時期が決まり次第ということで、今ご説明いただいたけれども、これはぜひしていただきたいと思うんです。おおよその時期というのは、大体どれぐらいになるかというところでは、わかったら教えてほしいと求めました。","respondent":"矢部下水道河川課長","answer":"８０ｍの管はそんなに大きなものではないと、私も考えていますので、引き続いてさらなる要望をお願いしていきたいと思っています。それから説明会のことですが、申しわけございません、ちょっと今の時点で、いつというような約束は。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"では、ぜひ、よろしくお願いいたします。３,５００ｔの調整池が鈴ケ森公園のところにできるということですけれども、これの面積と深さがどれぐらいなのか教えていただきたいんです。","respondent":"矢部下水道河川課長","answer":"ちょっと、先ほど私が早口で言いましたので、もう一度ゆっくりお話しします。縦横が、１３.４ｍ掛ける３２.４ｍ、深さが８ｍと聞いております。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"平成１５年度でやって、すぐに２期間工事か何かで平成１６年度に移るような予算になるんですか、早く終わらせるために契約をしているんだったら。やはり、その辺のところは、品川区からもっと強く要望していってもらいたいなと思うんですが、その辺はいかがか尋ねました。","respondent":"矢部下水道河川課長","answer":"平成１５年度、１６年度の２か年の債務負担工事で、３か年になってしまうということです。２か年までは大体認めてくれるんですけれども、３か年についてはだめと言われていまして、お願いした話です。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺はわかるんですけれども、南大井地区を見て、一日も早く終わらせるための作業でやっていると思うんですが、同じ発想でいけば、３か年になるけれども、その辺、さらに折衝していただきたいと、もう１回、要望だけしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"西本委員","kind":"確認","question":"要は、災害の状況を見て、効果があった、なかったという判断をするには、逆から見ると、災害があるんではないかということでしょうか。効果を見てから検討というのは、どういうことなのか、ちょっと確認だけしておきたいと思います。","respondent":"矢部下水道河川課長","answer":"上流部につきましては、実は既に荏原南公園に、たしか１万４,０００ｔだったと思うんですが、雨水調整池ができております。という意味で、一つは荏原南公園の雨水調整池の役割、それと、今の中流部、その２点で、その効果を見てからやっていきたいと言っております。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"いずれにしても、いろいろと検討されている中で、効果を見て検討するというのは、それなりの根拠があってのことだと思うんですね。これは要望ですけれども、そういう決断のほうは柔軟にとっていただくように、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"駅前広場の問題で１点、お伺いしてもいいですか。〔「次回」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"ばらばらな関係なんですけれども、駅前広場との関連で行われているのかどうかという、その辺の質問。どのぐらいの人がかかわって計画が進んでいるのかとか、その辺をちょっと質問を受けているので、その辺を伺いたいんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"原副委員長","kind":"意見","question":"一応の審議がされていまして、いろいろな意見も出されてきていますので、そちらのほうの調査事項だと判断をしております。建設委員会の事件調査のほうでかかっておりますので、ここではよろしいんではないかなと、私は思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"意見","question":"街並みづくりのほうはいいんですけれども、結局、駅前広場づくりの問題として、その地域のまちづくりの中核になる駅前広場のところで、どのぐらいの方がかかわっているのかというところで、一つ聞きたかったんで、ぜひ次のときに時間をつくってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"原副委員長","kind":"質問","question":"特別委員会の場合は、調査事項が限定されていまして、その部分だけをここに持ち出してやっているものですから、今、建設委員会で取り上げられているような事項については、ここの問題ではないと、私は思っています。","respondent":"宮崎委員長","answer":"その仕切りを含めて、正副委員長で検討します。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/408110?Template=document&Id=6272#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":10825,"voices":43}},{"id":"h16-20040415-14","meetingId":"h16-cm04","date":"2004年4月15日","dateIso":"2004-04-15","committee":"行財政改革特別委員会","time":"午後１時０６分～午後２時０１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件整理しています。","topics":[{"id":"topic-01","title":"行財政改革に関することのうち「電子区役所に関すること」","agenda":"行財政改革に関することのうち「電子区役所に関すること」","exchanges":[{"speaker":"高星委員","kind":"質問","question":"文書として盛り込むかどうかは別にしても、こんなふうに思ったものですから、意見として言わせていただきました。ほかにもし議論になるようであるならば、皆さんにも諮ってもらいたいなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"中島委員","kind":"質問","question":"今の高星委員の、私も当然だと思うんですが、ただここに「インターネットの接続環境のない区民に対しては」というのが入っているので、私はそういう方も含めてここに書いてあるのかなと思ったんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"}]},{"id":"topic-02","title":"続きまして、(2) の議員定数に関すること","agenda":"続きまして、(2) の議員定数に関すること","exchanges":[{"speaker":"田中委員","kind":"意見","question":"果たして適正な議員定数というのはどうやって導き出すべきなのかというのが、まだまだ結論が出せないような状況ではないのかなと考えています。議論を深めていくべきではないかなという思いから、議会でさらに慎重な審議を踏まえて…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"中島委員","kind":"質問・要望","question":"現実に、私はここに書いたように４０名でなくても３８名でも、本気になってみんなが取り組めばできないことはないと。何かを調べるにしてもいろんな手段があるわけですから、本当にこれからの定数削減というのは、区民の方にとっても要望されていることでありますので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"沢田委員","kind":"提案","question":"私が入った頃は確か４００億円ぐらいですから、膨大な事務事業、議員がチェックするべきところというのはますます増えているわけです。実際的には予算の本体の提案権はなくて修正しかできなかったり、ものすごい労力とデータをもっていなければ、現実にはできていないとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"山村委員","kind":"質問・要望","question":"我々議員および区役所も仕事をしているわけですから、議員定数を考える部分があってもいいんじゃないかとは思っております。３番に書いてあるところで、それに対して役所側に何を求めるのかとか、早急に結論を出すべきじゃないと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"それこそ議論すべき問題であって、昭和５６年１１月に行財政検討委員会設置から、品川区の職員も１,４６５名減らしてきたという実績があります。我々も１０年ですけれども、やはり削減に向けて努力するという方向に持っていかなきゃいけないんじゃないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"中島委員","kind":"質問","question":"ですから、このチェック機関というのは、もっとほかの形をつくってもいいんじゃないかなということも、この案の中に検討すべき課題じゃないのかな。ですから、本当に公平性のあるチェック機関というものが、これからますます必要ではないかなと考えております。","respondent":"須藤委員長","answer":"その辺のところを次のまとめに関してのお考え、それについてどういう方向性でというご意見もいただければ幸いですので、どうぞよろしくお願いいたします。","id":"exchange-008"},{"speaker":"三上委員","kind":"意見","question":"今、方向性という話、それは内容的な部分でいろいろあると思います。次の委員会でもっと時間をかけて、ある方向性に見出せるものがあれば、そういう方向に努力していくということしかないのかなと思うんですけれどもねとの意見を述べました。","respondent":"須藤委員長","answer":"そういうご意見をいただきたかったんですね。全部表記しておいて、正副でまとめるについても次回に出しようがないので、よろしくお願いいたします。","id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"営利企業ですから、じゃ民間委託をどんどん進んだら、議会は要らないのかということになりかねない。最終的には結論をどうするのかというのを皆さんに諮って、次期委員会に送ることしかできないんじゃないかなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"できたらそれ以降もこういう形の委員会を設置してということも含んでのお話だったのかなと伺ってはいたんですけれども、大方が基本的な考え方で。区民連合のところでは、「住民ニーズはより複雑になり、私もそういうふうな時代になっているなというふうに実感しながら説明を伺っていました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"もうこれでほとんどまとまっているわけですから、委員会としてこれをどういうスタイルで議長に報告するかという、その問題だろうと思います。次はどう判断するか、次回の行財政改革特別委員会があるかどうかもわからないわけですから、報告していただきたいというのが自民党の願いです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"高星委員","kind":"質問","question":"取りまとめの方向というか、基本的には行財政改革特別委員会ですから、当然一定程度のまとめをして報告しなければならないという使命はあるわけです。最近の児童委員も兼ねるわけですけれども、最近またさらに児童虐待の問題も出てきたものですから、より一層仕事が忙しくなる。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"沢田委員","kind":"質問・要望","question":"本来やるべき先を見通した手が遅れたら大変なことになっちゃうんじゃないかなというふうに思います。追加しておきます。","respondent":"須藤委員長","answer":"大方、お考えを出していただきました。〔「異議なし」と呼ぶ者あり〕 ご提案をもとにいたしまして、今まで討議しましたことをベースにして、議長に提出する文案を正副でつくらせていただきます。特定事件調査を終了いたします。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/892144?Template=document&Id=5748#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":14511,"voices":35}},{"id":"h16-20040511-6","meetingId":"h16-cm05","date":"2004年5月11日","dateIso":"2004-05-11","committee":"区民委員会","time":"午後１時０５分～午後２時５３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"これは３月１日に継続をしてきたものなんですけれども、こういうときに、意見書提出の請願というものを審査する時期なのかなという気もするんですよ。区民委員会ですから、本来的には審査して結論を出したいということなんですけれども、もう１回あるんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"そうしてみると、今、ここで審査するのが妥当かどうか。こういう形は滅多にないんですけれども、継続にせざるを得ないのかなという気がするんですけれども、どうでしょうかね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"高星委員長","kind":"意見","question":"意見書を出せる時期かまとまっているかどうかということ、ご案内のとおり、３月１日については継続扱いになった。〔「なし」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"松澤委員","kind":"質問","question":"毎月、１人３回の活動ということですけれども、１０８人ですから３２４回、３０日で割ると、１日１０人程度出動ということですが、これは毎日活動するということなんか尋ねました。","respondent":"杉浦生活安全担当課長","answer":"毎日ということは想定してないんです。ではその日の７時、ないし８時から２時間ぐらいやろうとか、そういった主体性を重んじていきたいと考えています。","id":"exchange-004"},{"speaker":"松澤委員","kind":"意見","question":"今、地域では、空き交番対策ということで、地域から大変声が出ているんです。これとの連携というもの、あるいは、空き交番で一休みしながら活動するという形があるのかどうか、その辺もひとつとの意見を述べました。","respondent":"杉浦生活安全担当課長","answer":"もちろん、各警察署に空き交番といいますか、警察官が不在の時間帯の交番があれば、そちらに立ち寄ることも問題はないと思います。それについては、従来から、警察署との申し合わせというものはできてあります。","id":"exchange-005"},{"speaker":"松澤委員","kind":"意見","question":"目立つ活動、ああ、空き交番に「我が町パトロール」の人が集まっているよという形ができるといいなという気がするんです。区民に信頼を得るために、そういうふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"嶋委員","kind":"質問","question":"この方々、地域から選ばれた方が全員なのか、どういう形で選ばれたのか。そういうものが条件なのか、どういう形のときに保険がきちっとかかるのか、ちょっとお聞きしたいと思います。","respondent":"杉浦生活安全担当課長","answer":"ちなみに、年齢平均を取ってみましたら５９.６歳ということで、予想より若く、大変に嬉しく感じております。警察官、あるいは生活安全サポート隊、こういう方々と連携をして活動をしているときに障害が出た場合には適用になるです。","id":"exchange-007"},{"speaker":"嶋委員","kind":"質問・要望","question":"では、このボランティア保険の場合は、これは警察署関係ですけれども、責任者というか、そういう形が決まっているのか。２４名の中の役割分担的なものと、どこにどういうふうにしてご連絡をするのか、この流れだけ教えていただきたい。","respondent":"杉浦生活安全担当課長","answer":"活動する場合の責任者ですけれども、今、グループ分けなりを進めているところです。やはりそういったグループの中の責任者的なものは必要なのかという気がしております。","id":"exchange-008"},{"speaker":"嶋委員","kind":"意見","question":"これから責任者を決めていくから、もし責任者が決まったら、その方を通すんでしょうけれども、万が一けがをしたときに、どういうふうにしたらとの意見を述べました。","respondent":"杉浦生活安全担当課長","answer":"私のところに連絡が来て、そして私のほうから申請をするという形になります。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"ボランティアの方の平均年齢が５９.６歳ということだったんですが、その中でも、一番多い年齢と、それと男性が何人、女性が何人か。それから、防犯協会にお願いしたときに、実際にどんな職業の方がこれに参加をしてきているのか説明を求めました。","respondent":"杉浦生活安全担当課長","answer":"それから、男女比ですけれども、男性が７７名、女性が３１名ということで、３分の１が女性ということになっております。特に地域的には、八潮団地あたりでは会社員が多いというふうに聞いております。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"それに含めて、なぜ１,０００円なのかということ。この課に伺うことじゃないかもしれないんですけれども、値段は１,０００円じゃなくても、払わないという形にしていくのか。","respondent":"杉浦生活安全担当課長、山田区民生活事業部長","answer":"１,０００円を払うのがいいのか、やはり最初からきれいな真珠がアコヤガイの中でできるわけではありませんで、核が必要です。ですから、この先の二次的なパトロールボランティアについては、交通費の支給というのは… そういったことも、どうあるべきかを含めて、今年度、検討に入るということになってあります。あくまで交通費の実費弁償という意味合いで１,０００円だけ支払いをさせていただきたいというふうな考え方ですので…","id":"exchange-011"},{"speaker":"木下委員","kind":"質問","question":"何か、そういうものの基準となるようなものはありますでしょうか。そういう手続的な面ですとか、どういうふうな形をとればいいのか、そこら辺を教えていただけますか尋ねました。","respondent":"杉浦生活安全担当課長","answer":"生活安全担当課のほうにお話をいただければ、若干のこういった制服がありますので、それについてはご協力できるということであります。それを待っているというのが本音でございまして、ぽつぽつとそういう話も出始めてきておるわけでございまして…","id":"exchange-012"},{"speaker":"木下委員","kind":"確認","question":"交通費の実費弁償ということなんですが、まず確認なんですけれども、生活安全サポート隊の方と、警察官と一緒にパトロールしたときだけつくという認識でよろしいんか尋ねました。","respondent":"杉浦生活安全担当課長","answer":"基本的には、そういうふうに考えてあります。","id":"exchange-013"},{"speaker":"三村委員","kind":"質問・要望","question":"こども１１０番の家の訪問というのが、そういうこども１１０番みたいなシステムをとっていても、やっていただきたいなと思います。そういったところを、今後、どのようにお考えなのかお聞きしたいと思います。","respondent":"杉浦生活安全担当課長","answer":"最初のご質問なんですけれども、落書き消し作業が有償かということですか。","id":"exchange-014"},{"speaker":"三村委員","kind":"質問","question":"同じ２時間拘束されるということであっても、どうしても大変さにかなり開きがあるかと思いますので、有償というような考え方もあるんか尋ねました。","respondent":"杉浦生活安全担当課長","answer":"それからもう一つの、こども１１０番の、実際に子どもも一緒に回ってみるというのはすばらしいお考えです。アイデアをいただいていきたいと思います。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"お伺いしますが、どちらを優先して参加しなさいみたいな指導というか、指示はしてあるんか尋ねました。","respondent":"久保田防災課長","answer":"緊急時の災害対策本部等が設置されますと、風水害、あるいは水防対策等を優先して駆けつけてもらうということが前提になってあります。９０％は駆けつけて来れるという状況になってありますので、訓練等についてはかなり有効に機能しているかと、私どもも考えているところです。","id":"exchange-016"},{"speaker":"松澤委員","kind":"質問","question":"こういうのがありますよという情報伝達が伝わっているのか、そこまでの訓練というのはなさらないんですか。あるいは、その訓練は個別にやっているんか尋ねました。","respondent":"久保田防災課長","answer":"そういう点では、確認の意味合いでも、「本日は水防演習です」という形でお流ししようかなと考えております。そういう点では、その中の一つに組み入れまして、防災伝言板で一斉に町会長たちにはお知らせするということは取り入れていきたいと考えております。","id":"exchange-017"},{"speaker":"松澤委員","kind":"質問","question":"せっかく新しい伝達手段をつくったんですから、その活用、訓練というのをこういうときにやられれば。総合的な水防演習であり、風水害早朝参集訓練ですので、そういう形で訓練と同時に警報もできればと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"木下委員","kind":"質問","question":"私も役所のほうに電話をかけて、どういう状況かと聞いたりして、ご近所にお伝えしたりしたんです。そういう情報等があったら即時に流していただけたらありがたいなと思っているんですけれども、そういうところはいかがですか尋ねました。","respondent":"久保田防災課長","answer":"問い合わせていただければ、逐次その辺の状況についてお知らせできるというようになってありますし、そのほうが逆に早い場合もあります。防災テルてるなんかでもお流しできませんので、逆に早い場合もありますので、そちらのほうをお願いできればと考えています。","id":"exchange-019"},{"speaker":"木下委員","kind":"意見","question":"町会長方が支給されている電話は、今はもう携帯電話も持っていますから、メールで一斉にお流しすることもできると思うんですよね。基本的な最低限の情報でも、そういう形で、情報の伝達をやっていただければありがたいなと考えていますので、お願いということですとの意見を述べました。","respondent":"久保田防災課長","answer":"これも以前にご説明したとおりですけれども、地域センターと、各警察署と消防署というふうに限られてあります。５カ所しか通話できないようになっています。","id":"exchange-020","title":"町会・自治会支援"},{"speaker":"藤原委員","kind":"意見","question":"袋ですが、全部で５万セットということですが、予算はどのぐらいかかるのかという点。裏面なんですけれども(3) の1)、人を含めて、どんな罪になるのかとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"集団回収でも、瞬間を見ないと、実際には捕まえることはできない。警察も含めた目があると、地域の方からそういう通報が行くこともありますよということでの警告に重きを置いた表示ということで考えております。","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"区のために使われていると思っているのに、いろいろな特別委員会のほうでも質問が出てきますけれども、トラックが来て持って行ってしまう。対応の仕方というのも、少し話しておくべきではないかなと思うんですけれども、いかがか尋ねました。","respondent":"中山清掃リサイクル課長、杉浦生活安全担当課長、岩崎環境清掃事業部長","answer":"ただ、先ほど申し上げたように、実際にこのことによってすぐに立件できるかというような問題があるんです。… それ以降も、大分警察内でも検討はしたんですけれども、送っても、どうも地方検察庁のほうで立件しないということになっております。窃盗罪は… 警察が今までそうだったということの説明だったわけですけれども、態度も変わってくることもあると、私は思っております。区民…","id":"exchange-022"},{"speaker":"三村委員","kind":"質問","question":"市況は若干復帰しているんじゃないかと思うんですけれども、そういうような動きが出てくるところまでは、まだいっていないということですか。ちりがみ交換で対価を払って回収するというところまでは、市況は回復をしていないんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"従来はわかりにくかったんですが、これをより明確にする、そういう意味で対応するものです。今、言われたのは、純粋にちゃんと合意の上で市場で流れているものとの対応とは別で、行政に出されたものに対してです。","id":"exchange-023"},{"speaker":"木下委員","kind":"質問","question":"処理するのにそれだけ費用をかけなきゃならないわけですから、持って行ってくれるんだからありがたいことじゃないかなという考え方も一部できます。１０年の中で１回とか、自分が経営者だったら、かえって行政のそういう回収にかかるコストが安くなるんじゃないかなという気もするんです。","respondent":"中山清掃リサイクル課長","answer":"やはり仕組みの安定性というものを考えたときに、１kg当たり６円という形ですけれども、７,０００ｔ強の資源がリサイクルされております。その中で、今後、先ほど申し上げたように、コストをいかに下げるかというのは、我々の科された課題と考えています。","id":"exchange-024"},{"speaker":"木下委員","kind":"質問","question":"そこら辺のコスト意識をもっと周知徹底していただければ、盗まれた云々という感情的な部分も、ある程度和らぐかなという気もします。私は普通に、所有もなくなっちゃったものじゃないかなと考えていますので、少数意見としてお聞きほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"嶋委員","kind":"意見","question":"申込み、早いもの勝ちなのか、５万セットというのは１回限りかどうかということ。それから、地域センターでの窓口配布とかありますけれども、そこら辺をもう少し説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"新聞の量で言えば１枚１月分ぐらいということなんですが、１月もたないという声もありますが、おおむね年度分をお出しすると考えております。再度作成していきたいと考えていますが、何分、このことによる利用の度合と効果をまず見たいと考えている次第です。","id":"exchange-026"},{"speaker":"嶋委員","kind":"意見","question":"見て見ぬふりをするという部分があるんですが、業者がやっていそうなときには、ちょっと待てということでやっています。アルミ缶の持ち去りのほうは、どういうふうに考えていらっしゃるのかとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"行政に出されたものは抜き取ってはいけないという表示を、コンテナのほうも含めてやっていくという対応を、缶については考えております。アルミ缶がほとんどなんですけれども、そういう対応を考えているところです。","id":"exchange-027"},{"speaker":"松澤委員","kind":"質問・要望","question":"もう一つ、４月１２日でしたでしょうか、区民委員会の中で、飛行ルートについて説明されているんですよね。そのことについてお尋ねします。","respondent":"金井環境課長","answer":"私どもは、こちらで飛行ルートをご説明をさせていただきました。当委員会を無視してということではございませんので、ひとつよくよくご理解のほどをお願いしたいと思います。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"だから、記事になった内容について、前回の報告事項でやりながら、なぜないのですかということですけれども、今、その席で報告しましたと、その内容が新聞に出たということですので、それでしたら構いません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"嶋委員","kind":"確認","question":"今、６月中にある程度めどが立って、広報ということは、品川区広報ということなんでしょうか、その辺を確認したいと思います。","respondent":"中山清掃リサイクル課長","answer":"基本的には、２３区の清掃協議会というところから、いわゆるプレスをする予定です。そちらの広報と連携して、そういう袋が製品として出てまいりますし、そのことを認めますという形で広報を図ってまいりたいと考えております。","id":"exchange-030"},{"speaker":"嶋委員","kind":"質問","question":"出す人がすごく色目で見られていく部分があるでしょうから、町会にもチラシというか、看板でもちょっと出したらと思います。この辺をちょっと心配します。","respondent":"中山清掃リサイクル課長","answer":"ちょっと説明が、きちんと推奨するということは残してまいりますので、よろしくご理解のほどをお願いします。","id":"exchange-031"},{"speaker":"三村委員","kind":"質問","question":"炭酸カリシウム入りでなくても大丈夫ということで、今まで、こういうのが導入されたときに、スーパーのレジ袋との関連性があったと思うんですけれども、今後はどういうふうになるんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"あれでも構わないという扱いになっていますので、その辺は、従来と変更ございません。要は、炭酸カルシウム以外でも可能になれば、そういうものも構いません。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/663620?Template=document&Id=2390#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":31730,"voices":107}},{"id":"h16-20040511-7","meetingId":"h16-cm05","date":"2004年5月11日","dateIso":"2004-05-11","committee":"厚生委員会","time":"午後１時０３分～午後４時２４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼副委員長","kind":"質問","question":"この配布のところなんですけれども、この保育園とか幼稚園、かなりお子さんの割合が占めていますよね。ここらあたりは、いつぐらいに配付のご予定なんか尋ねました。","respondent":"田中健康課長","answer":"できましたら、今月中にお手元に行けるようにということで、現在作業を進めてあります。ちょっと説明しますと、新しい事業ということで国庫補助もお願いしまして、実はその部分も認めていただいておるところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"配付対象のところなんですけれども、小児科のある医院のところなんかにもこういうのがあると、いろいろとアドバイスができたりとか、その職員とかもいいかなというふうに思ったんですが、そういう小児科とかに配付というふうなところでは、いかがか尋ねました。","respondent":"田中健康課長","answer":"どこというか、今回１万部増刷していますので、ご要望のあるところを検討させていただきながら、できるだけ広く配布させていただきたいと存じます。","id":"exchange-002"},{"speaker":"三上委員","kind":"質問","question":"ちょっと見ていて、これ２０ページのところの右の表の３９番、ぷりすくーる西五反田ですね、これは、電話番号というのは、この印刷する時期でも最終的に決まらなかったんか尋ねました。","respondent":"田中健康課長","answer":"ただ、いろいろ今回もちょっとミスも出ておりますし、その際にもっと詳しい情報を各関係課と協議しながら入れていこうというふうに考えてあります。あくまで４月時点にわかっているものということで各課から情報をいただいて、今回に限ってはさせていただいた次第です。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう保育園に預けている方がこういう要求があった場合はどういうふうにするのかということが、２点目で教えてほしいと求めました。そういう預かる子の配慮も含めたチェックの機構とか何かも含めて、どういうふうになっているのかということを教えてほしいと求めました。","respondent":"金子保育課長","answer":"それから３番目、細かいところは今日は明示しておりませんが、一応受付のところで各実施園において受け付けるというふうにしております。アレルギーの場合の食事等々、そういった情報もそこで得ながら対応していこうというふうに考えておるところです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いないというふうなことを関係なく検討すべきではないかなというふうに思うんですけれども、そこの考え方も教えてほしいと求めました。６人もプラスで見るというふうなことになるんですが、それから、保育をどのようにしていくのかということもあわせて教えてほしいと求めました。","respondent":"金子保育課長","answer":"これは今年度スタートする事業でありますので、今年度についてはこの人材派遣で対応していこうというところで考えているところです。それは、基本的には育児保育につながらない方向で私どもの保育というのは実施していこうと考えておりますので…","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"在宅の方はこういうことが育児放棄でなくて、就労の方がこういうふうなことがあると育児放棄というふうなことにはならないと思うんですね。ぜひこれは保育園に預けている方からもこういう要求があれば、やっぱり含めて検討をしていくように要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"須藤委員","kind":"質問","question":"あらかじめどの程度、今定員６名とかというような予想をされているんですが、そのあたりはいかがにお考えでしょうか。ですから、そのあたりの困難さと、その辺の利用の頻度的なものはどういうふうにお考えになっているか尋ねました。","respondent":"金子保育課長","answer":"一応年齢については低いところに限らず、就学前すべてを対象にする、保育園で預かっている子どもの範囲ですべて対応するというふうに設定しています。ニーズ自体は一応各地区６人ということで、ある程度、充足率は高くなってくるんではないかなというふうには考えてあります。","id":"exchange-007"},{"speaker":"須藤委員","kind":"質問","question":"小さなお子さんでとまっているというほうがいいのか、これからやる子育て支援という考え方ではどういうふうにお考えでしょうか。やはり、本来的にどうかなというような懸念があるんだけれども、そのあたりのお考えはいかがか尋ねました。","respondent":"金子保育課長","answer":"そういうところで子育て困難な方を見つければ、私どもとして対応するか、あるいは児童相談所等に通報して対応するかというふうになってきますが。ですが、この辺の見きわめというのは…","id":"exchange-008"},{"speaker":"三上委員","kind":"意見","question":"しかし、集中してどうしても預かってもらわなきゃならないというような事態も生じてくるということだって、状態によってはありますよね。１日考えてみれば、ああ４,５００円かというようなことで考えるかもわからないけれども…","respondent":"金子保育課長","answer":"説明のほうでそこまで十分説明しなかったんですが、従来から一時保育、各園２名充て実施しているということは先ほどちょっと申し上げたとおりですが。従来どおりこの１日単位で２,０００円いただく一時保育を実施してまいりますので、頻度等も含めて、私どももご案内をしますが。","id":"exchange-009"},{"speaker":"三上委員","kind":"質問・要望","question":"確かに１日２,０００円で預かれるところがあるべきだけれども、あっちもこっちも探さざるを得ないとかという話もあるかもわかりませんよね。それから、その上で、これでいいんですねというような相手に理解をしてもらった上での預かり方ということを十分努力していっていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"大沢委員","kind":"意見","question":"この実施場所四つの行政地域ということで、品川、大井、大崎、荏原なんですけれども、この５園が選ばれたまず基準というのが何かあるのであれば、それをちょっとお教え願いたいんですけれどもとの意見を述べました。","respondent":"金子保育課長","answer":"この５園に決定した理由ということですが、まずは各地区に分散した形でそれぞれの地区で選んでいこう。０歳児室、それから１歳児室にそれぞれ３名ずつが上限だというふうに申し上げましたが、この５園について決定してきたです。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問","question":"そうしますと、余裕があるという基準のもとで言いますと、保育園で言いますと、これで荏原地区の小山台、中原、平塚、荏原、荏原西においては、ここの部分は抜けているような気がするんですが、余裕がなかったという部分で抜けているんか尋ねました。","respondent":"金子保育課長","answer":"全体として６名が入る、０歳、確かに荏原地区ではこの中延ぐらいが余裕があるという園だったように記憶しております。実際は、もう１園も０歳児園からにすればよかったんですが、もう１園については１歳児園ということで東中延に選定した経過があります。","id":"exchange-012"},{"speaker":"大沢委員","kind":"意見","question":"６人を受け入れるべきスペースがあるところに関しては、この生活支援型一時保育を設置をしていくこの５園についての利用状況その他もろもろを検証しながら設置をしていくというような方向性はあるのかどうか、ちょっとお答え願いたいとの意見を述べました。","respondent":"金子保育課長","answer":"委員ご指摘のとおり、確かにこの新しいタイプの一時保育、それから従来からの一時保育、それぞれのニーズを見ながら今後の展開については考えていきたいというふうに思っております。","id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"さっき質問の中にもあったんですが、例えばきちんとこの５園のところで端的につかめるようなチェックリストとかつくるご予定はあるんでしょうか。お子さんの様子を把握するようなシートとかつくるんか尋ねました。","respondent":"金子保育課長","answer":"事業を運営していく中で、そういうものが有効であれば、またそういうものも使っていくというふうには考えていかなければならないと思います。そういう意味で、そういった経験を踏まえながら、今回の事業についても安全面に関しては十分配慮していきたいというふうに考えてありま…","id":"exchange-014"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"とても神経が細やかで、どういった方が見えても安心して預けられるような確保をしっかりしていただきたいなと思うのが１点です。先ほど人材派遣を各園２名ということで、実際にどういうふうに見られるのか、もうちょっと具体的に教えていただきたいんですが。","respondent":"金子保育課長","answer":"その辺の在園児の月齢、それから預かる子の月齢等々も見ながら、対応については現場で工夫していくようになるというふうに考えてあります。今の段階では各園長に考えてもらっているところですが、その辺についてはご理解いただきたいと思います。","id":"exchange-015"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"現在でも子どもと職員の比率とか、かなりどういうお子さんが入っていらっしゃるのかというので、日々その都度対応が違っていくだろうなと思います。そういった対応をぜひしていただきたいと思うんですが、いかがか尋ねました。","respondent":"金子保育課長","answer":"やはり場面場面で違うことがありますから、私どものほうからこうこうというふうには言ってもあまり実益がないかなと思うんですね。私どもとしましても、今回初めて実施する事業ですから、それについては現場でどういうふうに対応しているかということについては。","id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"質問","question":"そういった面では、今預かっているところで少しゆとりを持って、仕事以外のところでも温かく受けとめてほしいという声が率直なところなんです。例えば平日のところで仕事を若干休んで美容院に行くのも温かく受けとめてほしいということなんですけれども、最後になりますが、いかがか尋ねました。","respondent":"金子保育課長","answer":"これは、はっきり申し上げますと、保護者の状態によっては変わってくるとは思っています。それがもちろん、その辺のところは私ども現場と意見交換しながら、趣旨に沿う形での運用を心がけていきたいというふうに考えてあります。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"幼児教育施設のほうの３歳児は申込者数が５２から３７人になって抽選したということですが、抽選はどういうやり方でしたのかということと、保育園のほうも含めてどういう状況になっているのかということを説明を求めました。","respondent":"金子保育課長","answer":"抽選のやり方ということですけれども、事前に説明会をしておりまして、その時点で抽選の立ち会いのご希望の方について希望を募りました。今現在、さらに新たに申し込みをし直した方が何人かというのはちょっと集計をしておりませんので、その辺のところは数字は持ってございませ…","id":"exchange-018"},{"speaker":"大西委員","kind":"質問","question":"ちょっと基本的なことでお尋ねしておきたいんてすけれども、もう１点この３歳から５歳に関しては面接重視でないというふうに受け取れるんですけれども、その違いはどこかにあれば教えていただけますか。","respondent":"金子保育課長","answer":"０歳から２歳までのお子さんに関しては、ここは認可保育園の施設ですので、まずはその指数での高い方から内定するというような格好で決めしています。３～５歳につきましては、一応この施設に毎日通えるという方について…","id":"exchange-019"},{"speaker":"大西委員","kind":"質問","question":"わかりました。ただ、事情が千差万別であるんじゃないかなと思うんですけれども、そういった方面の考慮をなされるという考え方はないんか尋ねました。","respondent":"金子保育課長","answer":"０歳から２歳は従来の保育園ということで、この３歳から５歳については特段幼児教育に、特に入っていただきたいという希望を持ってございました。この施設の条例制定のときから、そういう意味では、ご希望の方の中で淡々と抽選をさせていただいたというのが全体の経過です。","id":"exchange-020"},{"speaker":"大西委員","kind":"質問","question":"としますと、各家庭の事情を、制約がないから、区立でやりたいような形で構わないから考慮をしないというふうにも受け取れるんですけれども、そういうことになるんか尋ねました。","respondent":"金子保育課長","answer":"区として、そういう意味では平たく抽選していきたいというふうに考えておりましたので、そういうような形態としております。ちなみに、区立の幼稚園についても抽選という格好にしておりますので、同じような格好ではあります。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問","question":"この東北大学の教授の学習療法、これが品川区の中で注目されてきた経緯をまず教えていただけますか。","respondent":"蓼沼高齢事業課長","answer":"そういう実症例が蓄積されているという結果にかんがみまして、これについて痴呆予防に効果があるということで、モデル的に実施してみようというふうに至ったのが経緯です。","id":"exchange-022"},{"speaker":"若林委員","kind":"質問・要望","question":"では、具体的な効果があると、そういう実際に東北大学に足を運んで視察をしたとか、またそのデータがこういうものですとかいう研究内容、そういうものが提示される資料があれば教えていただきたいんですが。","respondent":"蓼沼高齢事業課長","answer":"それから、仙台のほうでも介護老人保健施設でそういう改善が確かに見られたということで伺っております。手元には、その具体的な数字等については持ち合わせていないです。","id":"exchange-023"},{"speaker":"若林委員","kind":"質問・要望","question":"それからもう一つは、これは介護保険との兼ね合いは、特にないと思うんですが確認です。ここら辺の考え方を、もう１回再度間違いないように進めてほしいと求めましたので、よろしくお願いをいたします。","respondent":"蓼沼高齢事業課長","answer":"モデル実施を３カ月程度やる予定ですが、それについて検査をしながら進めるということで、３カ月ほどモデル実施をする予定です。１１月以降、本格実施にできれば移っていきたいということで予定をしているものですが、とりあえずモデル実施を３カ月ほどやってみて。","id":"exchange-024"},{"speaker":"若林委員","kind":"質問・要望","question":"じゃあ、途中の話になりますけれども、資料等々ありましたら、ぜひいただきたいと要望しまして終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"須藤委員","kind":"質問・要望","question":"そういう読み書き云々という形で非常に創造力を伸ばしたり前頭葉の働きを活性化させるというようなデータが出ているわけですから、自分で「うん？今度１カ所やっていらっしゃるわけですけれども、いわゆる実費をきちんととって、その辺のお考えを説明を求めました。","respondent":"蓼沼高齢事業課長","answer":"それは、公文と十分協議して、その提供については対応していきたいというふうに考えてあります。それから、実施箇所につきましては、今後のこの荏原南学童で実施をしてみて、その可能性については今後検討していきたいというふうに考えてあります。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問","question":"いろんなこういった場所でやられるのと、あと特別養護老人ホームとかそういう、あるいは老人保健施設でとか、そういうところの活用というのはいかがお考えか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"これにつきましては、当面はまず元気高齢者の予防ということで、まずは始めてみたいというふうに考えてあります。その実績を踏まえて、その次の展開については検討していきたいというふうに考えてあります。","id":"exchange-027"},{"speaker":"須藤委員","kind":"質問・要望","question":"あまり真剣にやっちゃうと、その辺を上手に考えながら、今後の施策の中に取り入れていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"三上委員","kind":"質問・要望","question":"健康課、やっぱり生涯にわたって声を出すということの機会をどうつくっていくかということの、こういう事業ということの展開をやっていくべきだろう。事業展開を、事業部を超えてやっぱりやっていっていただきたい、これを強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"大西委員","kind":"質問・要望","question":"どういう形に推移していくのかというのも同時にやっていっても、それによって、この痴呆の方々の改善が非常によく見られた。より痴呆が進まない可能性があるんであれば、それを実施していかれるというのも一手ではないかと思いますので、要望としてお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それ以外のサポーターというのはどういう体制でやるのかということを一つ教えていただきたいのと、そこら辺のところはどうするのかということについて、説明を求めました。","respondent":"蓼沼高齢事業課長","answer":"先ほど申し上げましたいろいろな事務的な部分、サポーターの支援ということで、学習者の募集といったような役割分担で当面はやっていくです。データ提供ということで、当然、個人のプライバシーの保護ということはきちんとやっていくのが前提だというふうに考えてあります。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ということは、ボランティアがすべてサポーターになるということで、５名のボランティアが公文教育研究会から研修を受けて、サポーターとしてやっていく体制をしていくという、そういうふうなことになるわけなんですねとの意見を述べました。","respondent":"蓼沼高齢事業課長","answer":"基本的には事前に研修を受けて、ボランティアとして学習支援をしていただくです。そういったサポーター、その他運営体制等を含めて、そのモデル実施をしている間に十分検討しながら確立はしていきたいというふうに考えてあります。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この予算と利用料ですか、このことを一つ教えていただきたいのと、どういうことか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"本格実施以降につきましては、これに教材費ですとか、あるいはサポーター研修にかかわる経費等がプラス１,５００円程度上乗せされる。それで、モデル実施の期間については公文が無償で教材、研修等についてはノウハウを提供していただけるです。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、このボランティアの謝礼というのは１カ月大体３,０００円というふうな形になるんでしょうか。そこのところだけ、最後に説明を求めました。","respondent":"蓼沼高齢事業課長","answer":"１回２,０００円を予定しております。","id":"exchange-034"},{"speaker":"飯沼副委員長","kind":"意見","question":"そことの絡みと、運営自体はどこに。これがやられることで変化はないのか、ちょっとその辺を説明を求めました。","respondent":"蓼沼高齢事業課長","answer":"荏原南学童の跡施設で筋力トレーニングも実施をいたします。これと並行して、時間とか場所とか重ならないように、施設の有効活用もかねて同時に実施をしていく予定です。","id":"exchange-035"},{"speaker":"飯沼副委員長","kind":"質問","question":"そういった面で、何か教材の販売にルートを開くみたいなところがあるんですけれども、その辺についてはどうなんですかね。区がこの事業を始めることで、教材販売のルートになるみたいな印象を非常に受けるんですが、その辺についてのお考えはいかがか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"教材につきましては、いわゆる一般に市販されておりますものが学習療法の考え方に基づいて一般的に使われるものというふうに考えてあります。それぞれ対象者、個人個人の能力に応じた形で教材を用意いたしますので…","id":"exchange-036"},{"speaker":"飯沼副委員長","kind":"質問","question":"一般のものとは違うということなんですけれども、週１回ここに来て学習するだけじゃなくて、結果的には自宅に帰って復習をするとか、そういう意味でもこの教材を販売していくというところに協力をしていくような状態にとられるのではないかなとも思うんですが、いかがか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"毎日１０分あるいは２０分、それを、この週１回の場にまたお持ちになっていただいて答え合わせをしたりしながら進めていくです。これは今、いわゆる研修の研究の成果に基づいた取り組みということですので、ちょっと今のところはっきりとわかりかねるところです。","id":"exchange-037"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"その辺の集約ですか、中身をきちんとまとめたものをご提示いただいて、次のステップを考えていただきたいなと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"須藤委員","kind":"質問","question":"簡単なあれなんで教えてもらいたいんですけれども、１月１日の人口報告で、その辺の要因というのは何か考えられてきているのか。これと、この辺の差というのはどういうふうに理解をしていいのかなというようなことがちょっとあったんで、その２点をお聞かせ願いたいと思います。","respondent":"金子保育課長","answer":"それからまた、これによって、こういったものがいろいろかみ合って転入されてくる層も増えてきているんではないかというふうに考えられると思います。この１万３,３２３人と、先ほどの７,６０１というのは…","id":"exchange-039"},{"speaker":"須藤委員","kind":"意見","question":"その他というのが４２で在宅等という表現をされたんで、１万３千幾つにならなきゃおかしいんじゃないかなというんで、その辺との関連はどうなっているのかなとの意見を述べました。","respondent":"金子保育課長","answer":"７,６０１人というのは、私立幼稚園、ここまでの数字が７,６０１人。ちょっとわかりにくくて恐縮なんですが、そういうことでちょっとご理解をいただきたいと思います。","id":"exchange-040"},{"speaker":"須藤委員","kind":"意見","question":"そうすると、その他のほうは、この１万３,３２３人引く５,０００人ちょっとがその他というふうに見てくださいよという考え方でいいわけですね。わかりましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"予算のときにもお伺いしたんですが、財源の都のところは都区財調で算入されるとお伺いしたんですが、この辺の影響をひとつお伺いしたいのと。でも、認可もとれているところもあるようなんで、その辺の今の流れの中でどうなのかなというところを一遍お聞かせほしいと求めました。","respondent":"金子保育課長","answer":"それが国の従来の負担金がそのまま１００％税源移譲されたわけではなくて、一定程度、結果的には低い額になっているというふうに聞いてあります。そういう意味では私どもが提起しました区長部局でのこれの運営等々、今後ともその辺を視野に入れながら…","id":"exchange-042"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"三位一体のところの税源移譲のところでは、平成１６年度の保育予算について具体的にこのくらい影響を受けているという数字は出ているのでしょうか。その辺が１点と、その辺は現在どうなっているのか、お聞かせほしいと求めました。","respondent":"金子保育課長","answer":"１点目の、幾ら幾らという額はちょっと申し上げられませんので、ご理解いただきたいと思います。先ほどちょっと申し上げたとおり、今後の検討の選択肢の一つであるというふうに認識しておりまして、現在それも含めて検討をしています。","id":"exchange-043"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"変化をしていくのかどうか、その辺の負担の割合なんかに今後の変化があるのかどうか、その辺をお聞かせほしいと求めました。","respondent":"金子保育課長","answer":"平成１５年度、今のところ特段の連絡、通知等をいただいているわけではありません。対応も考えていきたいというふうに、今、思っているところです。","id":"exchange-044"},{"speaker":"飯沼副委員長","kind":"意見","question":"現在ではまだわからないというところなんで、ぜひ区に影響する部分のところがわかり次第、ぜひご報告をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"須藤委員","kind":"意見","question":"０歳児で在宅というのが８２％ですよという、これは２３区いろいろ出てくるんですけれども、絵図は書かれてくるのかなと。区立は１％増で、５歳児が増えてくるのかなと思ったけれども、そのあたりは何かあるのかなというあたりをちょっと聞かせてくださいとの意見を述べました。","respondent":"金子保育課長","answer":"私立幼稚園が減って、これも数字を見たばかりではっきりした答えではないかもしれませんが、いわゆる認可外にいろんな施設があろうかと思います。これはまた、幼稚園の関係者等に聞いて、わかることはお伝えしていきたいというふうに考えております。","id":"exchange-046"},{"speaker":"須藤委員","kind":"意見","question":"私立幼稚園もそんなに５％という数字がダウンしてくるというのは、そういうあれで違った施設へ行くような傾向があるならば、それはちょっと一考しなきゃいけないかなというような思いがありましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"}]},{"id":"topic-02","title":"次の介護保険の運営状況","agenda":"次の介護保険の運営状況","exchanges":[{"speaker":"若林委員","kind":"意見","question":"全体、ほんとうにどれだけ踏み込んで研究をしながら実施をしていくかということが大変に大事なこれから５年、１０年になっていくと思います。とりあえずこの５年、１０年を見越した上での品川区としての介護予防の考え方、考え方をぜひお聞かせ願いたいと思いますとの意見を述べました。","respondent":"早津高齢福祉課長","answer":"昨年８月に開始をしまして１月に２カ所増やして３カ所、筋力向上トレーニングというものも３カ所で実施をいたします。身近でリハビリについてはもう１カ所今年度実施したいと考えていますので、今年度中に７カ所で本格的なリハビリサービスがされる。","id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"どうしても箱を思い浮かべがちですが、これは７０とか６０とか、介護予防はあまり生まれないような気がいたします。そういう目でぜひ見れるのが、高齢福祉課だと思いますので、しっかりリーダーシップをとって巻き込んでいただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この実態がどうなっているのかということでちょっと教えていただきたいんですけれども、そこら辺のところをつかんでいたら教えていただきたいのと、そこら辺のところも教えてほしいと求めました。","respondent":"早津高齢福祉課長","answer":"１割負担で済むものを一たん全額自己負担をしていただいて、後に９割お返しするとか、それが段階を追ってあります。そうならないように、国保当局と連携をとりながら、滞納が継続しないような形での連携をとって、徴収に努めているという状況です。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういうときには答えていただけるように把握をしておいていただきたいなというふうに思いますので、これは要望しておきます。こういう実態に対して区としてはどういうふうに考えられているのか、こういう実態になっている中でも同じなのかどうか、説明を求めました。","respondent":"早津高齢福祉課長","answer":"なお、特養の申込者については、先般の３月の直近の会議で前回よりも減をするというような実績にもなってあります。区の施設整備計画につきましては、再三お話し申し上げておりますとおり在宅への施設を中心として整備をしていくという考えに変わりはございません。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"具体的に何人になったのかをちょっと教えていただきたいのと、６カ月前に予約をせざるを得ないというふうな状況があるというのをいろんな方からお聞きしていますので、改めてご検討いただきたいという要望をさせてほしいと求めました。","respondent":"早津高齢福祉課長","answer":"特養の申込者、希望者の人数ですが、正確ではないかもしれませんが６８６名だったと思います。その前が７２１名だったという記憶です。","id":"exchange-052"},{"speaker":"須藤委員","kind":"質問","question":"運営状況、毎回いろいろ大変なデータを出していただいてありがとうあります。品川区としてはどういうような考え方で、介護保険の制度というか、そのサービスを考えていらっしゃいますか尋ねました。","respondent":"早津高齢福祉課長","answer":"この考え方は、支援センターを中心とした在宅サービスの拠点整備をしていこうというものと基本的には軌を一にするものだと考えていますので。むしろ歓迎すべきといいますか、従来の方針に大きな変更をする必要はない、こんなように考えているところです。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"〔「読めばわかる」と呼ぶ者あり〕参考資料ということなんですね。具体的に自治体の実態がどういう形で反映されていくのかということと、品川区としては、そういう考え方があるのかどうかを一つ説明を求めました。","respondent":"新美福祉高齢事業部長","answer":"これまでもやってきました世論調査を活用しての全般的な区民の意識調査を行う予定と、これは利用者のアンケート等もとる予定ですので、調査をする予定です。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"介護保険の５年後の制度見直しに向けての品川区としてのまとめというか、提案とか、そういうふうなのはつくる予定があるんでしょうか。そこら辺のところはいかがか尋ねました。","respondent":"新美福祉高齢事業部長","answer":"国のほうの見直しが３月で部会論議を終了して６月ごろまとめという当初のスケジュールがありましたが、夏ごろに取りまとめという話も聞いております。この段階にまいりますと、この段階で、特に取りまとめるという予定はございません。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"じゃあ、利用者はどうなっているのかというふうなところでは、それから利用者というふうなところではあると思うんですよね。品川区としてはどうなっているのかというふうなことが一つと、どう考えられているかの考え方をちょっとお聞かせいただけたらと思います。","respondent":"新美福祉高齢事業部長","answer":"それが具体的にどのような仕組みでやっていくのかということは、まだ詳細ではありませんが、すべての給付を外すというふうには受けとめておりません。その辺、きちんと適正な形で利用者の意向と…","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"もう１点だけちょっとお聞きしたいんですが、今年度やはり三位一体の改革の中身になるんでしょうか。この点で、品川区に対しての影響というふうなのがどうなっているのかというのを、ちょっと説明を求めました。","respondent":"早津高齢福祉課長","answer":"財調に算定されているという理解をしておりますが、それが実際どういうふうになるかというのは、ちょっとまだ詳細のほうは把握しかねております。先ほどの認定制度ではありませんけれども、それにかかる費用が相対的に減る、結果的に減るような措置もあわせてとってあります。","id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/256749?Template=document&Id=3076#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":54766,"voices":145}},{"id":"h16-20040511-8","meetingId":"h16-cm05","date":"2004年5月11日","dateIso":"2004-05-11","committee":"建設委員会","time":"午後１時０４分～午後２時４５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件整理しています。","topics":[{"id":"topic-01","title":"平成１５年請願第２２号、（仮称）品川区上大崎二丁目計画再開発プロジェクトに関する請願","agenda":"平成１５年請願第２２号、（仮称）品川区上大崎二丁目計画再開発プロジェクトに関する請願","exchanges":[{"speaker":"山村委員","kind":"質問","question":"それをはっきりと認めているのか、首都高の下の出入りと工事をやることを認めているのかどうか、ちょっと教えていただけますか。","respondent":"浜脇住環境整備課長","answer":"ちょっと我々も現場、前回この委員会のために見ましたけども、それは難しいと考えています。","id":"exchange-001"},{"speaker":"山村委員","kind":"質問","question":"そこら辺でちょっと衝突を起こしているようなことをおっしゃっていたんですが、そういう情報は、あまり詳しい情報は入っていないんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"私のほうはまだどちらというふうに決まったというご報告はもらってございませんので、まだ調整について協議しているというのが、今の状況です。","id":"exchange-002"},{"speaker":"山村委員","kind":"質問","question":"警察が許可を出したのかどうか、もし許さなかった場合は、区として何かできることがあるのかどうか説明を求めました。","respondent":"浜脇住環境整備課長","answer":"私のほうはこの関係に対して、こういう住宅地の中でやられているわけですから、やはり周辺環境との調和というものは大事だと考えています。それをやっていってどうこうするというような立場ではないと考えていますので、私ども…","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"先ほど車の出入りの問題で、住民との話し合いが継続をしているという話がありました。業者のほうが要求に応じたような部分と、それと今の車の出入りの問題だけが今の協議の対象になっているのかどうか、ちょっとそこだけ説明を求めました。","respondent":"浜脇住環境整備課長","answer":"それなりに対応をしたんだなというふうに思われて、いいと言わないところでも、そういう説明は終わっているんじゃないかというふうに思われます。残っているのがその２点じゃないかということが私のほうに入っている情報です。","id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"２回この委員会で審議をさせていただいたんですけれども、この請願趣旨５項目が来ていますね。観察してきた項目があるんですか、この５項目の請願項目をどのぐらいクリア、あるいはこなされていると見ていらっしゃるのかわかりますか。","respondent":"浜脇住環境整備課長","answer":"それぞれについてご説明はされているということがわかってきたのではないかなですけれども、擁壁の問題、それについては残っていると。騒音に対応した建て方がいいかということはありましたけども、その件は終わったということでございまして、そういうふうに判断をしております。","id":"exchange-005"},{"speaker":"原委員","kind":"意見","question":"今のご説明でも、完璧にはいかないでしょうけれども、それなりのお話し合いの中で徐々に難点を解決していくという姿勢が見えているわけですよね。この手の問題について、やっぱり早急に今回の委員会の中で話し合って結論を出したほうがよろしいんではないのかなというふうに思っておりますとの意見を…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"ただ、業者と交渉云々という余地がまだあるようならば、もうしばらく見守ってやるということも大事なことなのかなと。まだ話し合いの余地が見受けられるかなというような感じがしますので、もうちょっと観察したほうがいいんじゃないかなというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"本多委員","kind":"意見","question":"これまで説明会などで数多くの協議をされてきまして、問題をクリアするものはクリアされてきたり、また当然工事の進捗と合わせて、解決できないものは解決できないということで、ある一定の結論を出すべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"藤田委員","kind":"意見","question":"５項目にわたる請願の趣旨はすべてクリアされているわけではありませんけれども、この２点に集約されているんじゃないかなということで、今日結論を出したほうがいいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"井上委員","kind":"意見","question":"何回か回数を重ねていますけれども、菊地委員、須貝委員と同じように、この騒音のことに対してもまだ働きかけを業者にしているということであれば、継続ということで審議したほうがいいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"山村委員","kind":"意見","question":"本来なら、そろそろ結論を出したほうがいいのはわかるんですが、どうしても車の問題だけは、下手をすると事故につながると私は思っています。もう少し私としてはというか、区民連合としては様子を見たいということで、継続でどうかとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"}]},{"id":"topic-02","title":"平成１６年請願第３号、戸越１丁目１７番高層ワンルームマンション建築に関する請願","agenda":"平成１６年請願第３号、戸越１丁目１７番高層ワンルームマンション建築に関する請願","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"連休中かなんかですかね、裁判そのものの運営を見守って、しばらく継続をすることが必要なのかなと思いますけど。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"よく住民と建築会社、施主とよく話し合って、いい方向に行くようにもう少し見守ってやったらいかがかなと。せっかく今住民の方が頑張って提訴したりいろいろやっていますので、私も当面見守ってと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"住民の方にもお話を伺いましたけれども、皆さんおっしゃったような状況であったり、工事による今後の交通の問題とか、さまざまなところで今裁判されているということですので、ここでは状況を見守っていきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"山村委員","kind":"質問","question":"ただいま裁判中ということですが、そうすると、全く住民と建設会社の間で何がしかの進展は、現状は全くないと思ってよろしいんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"何かしなさいと、そういう指示がないと、業者のほうからはそういった説明会等の話し合いはしないんじゃなかろうかと思う。ですから、私どものほうが連絡したところ、今裁判中なので、ほとんど何もないですよと、こういうご意見でした。","id":"exchange-015"},{"speaker":"山村委員","kind":"質問","question":"私、あまり詳しくないのでわからないんですが、大体このような裁判はどのぐらいの期間を有するものなんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"実はちょっと前の事例では、半年ぐらいかかっているような感じでした。やっぱり、こんなふうにしたらということを言って、裁判でやったことだからといって合意したような感じでやったというふうに把握しております。","id":"exchange-016"},{"speaker":"山村委員","kind":"質問","question":"そうすると、はっきり言ってしまえば、区よりも上の権限のところに今話し合いが起きていると考えていいわけか尋ねました。","respondent":"浜脇住環境整備課長","answer":"なかなかうまくいきませんから、そういった意味では、裁判が一番住民側も建主側も判断がつくものだというふうに思います。","id":"exchange-017"},{"speaker":"原委員","kind":"質問","question":"じゃあ延ばしたから、民民の話ですから、建主と周りの住民の皆さん方で一番よりよい解決方法を探していくというのが原則のところだと思うんですよね。これは裁判にかかっているですから、裁判を見守りましょうかというふうに言わざるを得ないなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"藤田委員","kind":"質問","question":"ですから、議会が何かやってくれるんじゃないかなと、そういうものでは決してないわけですよ。マンション紛争というのは、きちっとやっぱり、我々としても決断をつけていかないといけないんじゃないかなというふうに私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]},{"id":"topic-03","title":"平成１６年請願第１２号、（仮称）カテリーナ戸越III新築工事に関する請願","agenda":"平成１６年請願第１２号、（仮称）カテリーナ戸越III新築工事に関する請願","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"今、個別の話し合いの形になっているということですけれども、請願を上げられた住民の皆さんのほうは、全体での説明会を要求しているとか、その辺の経過はありますか尋ねました。","respondent":"浜脇住環境整備課長","answer":"その他は、やはり近接の方と離れたところでは状況が違うということで、今個別にということで個別に当たっているということだと思われます。ですから、いついつ要望していますよという話ではありませんから、個別にやっているということしか私どもには入ってございません。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問・要望","question":"こうして請願まで出されたわけですから、３回目にどういう住民から要望を出されたという区に報告があるんですけれども、実際にはどうなるんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"ですから、やはり個別のものが取り組んだ場合には、なかなか私どものほうには上がってこないというのが状況です。そういうことであればわかるんですが、ちょっと個別になると、そういったことでなかなか情報が入ってこないというのが大体この手の状況です。","id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"そうすると、区は住民の皆さんが請願をした時点での引いた図面ですよね。住民の声に応えたような部分というのは、ちょっとさっきと同じような話ですけれども、あるのかどうかとの意見を述べました。","respondent":"浜脇住環境整備課長","answer":"先ほど個人の話をしていくと、そういった協定が結ばれているという部分で、全体というのはある意味では薄まってきたのかなというふうに思われます。工事に関しては、住民と事業者側とは一定の協定を結んだということになっていて、そういうふうに個別になっているかもしれません…","id":"exchange-022"},{"speaker":"原委員","kind":"意見","question":"建物が高いから低くせよとか、電波障害があるからどうしろこうしろというマンションのほんとうの紛争ではない。条例を直さなきゃいけないよという話になるわけで、そこまで、ここでは審議するということは難しいと私は思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"井上委員","kind":"質問","question":"そういうやむを得ないと認めた場合、区長が承認したというようなことに対してアプローチは何かお聞きになったんでしょうか。住民の方の動きを掌握されていたんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"そういうような部分がありますので、ここについてはたびたびご説明申し上げているとおりで、住民が来てもそういうふうに説明をしているわけです。私も随分これを考えて、失礼ですけれども、すべてのことを全部見直しするというふうなことは今でも考えておりません。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"地元の方々から、東京都知事に向けて不服申し立てが現在出されているということですが、そのことに対しての都側からのどういった状況なのかとか、これに対しては何もないんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"４月の中旬でしたか、そこから問い合わせがありまして、それにつきましては回答しています。４月の中旬です。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"今回の場合には、やむを得ない場合と判断した理由のようなところについては、どのようなご依頼で、品川区としては出されたんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"これについては、区としてはこういうことについては認めておりましたというような内容の回答でございまして、これだけについては言ってございません。要するに一般論として話をしたです。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問","question":"ということは、そういう承認はしましたという答えを出したということか尋ねました。","respondent":"浜脇住環境整備課長","answer":"こういう要綱について、こういうような問い合わせがあって、こういうふうに答えてありますと、そういうことについては述べてあります。","id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"ですから、納得して協定書を結んだわけではないという思いをやっぱり私も伺っていますから、認識が違うなというふうに感じました。ですから、そういう件については、気をつけてと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"須貝委員","kind":"意見","question":"それを今住民の皆さんが３月に提起なさって、実際に裁判までいくのかどうかわからないですけど、そういう判断も大事じゃないのかな。それは我々の立場、この委員会の立場とすれば、もうちょっと見守ってあげていいんじゃないかなという気がしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"原委員","kind":"質問","question":"今たまたまご存じの方々、何名かわかりませんけど、どういう形で東京都に対して出されているんですか。それから条項なり、別に飛ばしなり何なりについてはおかしいよという話で、それについて東京都は言っているわけか尋ねました。","respondent":"浜脇住環境整備課長","answer":"内容的にはそういう内容です。","id":"exchange-030"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、今は住民の方が行った申請について区へ問い合わせがあったとかで、この後の流れというのはどういうふうになっているんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"私どもでそういう行為が、事実があったかどうかだけ回答したのであって、都からいろいろ判断はないというふうに聞いてあります。その照会というのは、あるいはその指導要綱についての管理監督する権限はございませんから、上の判断はしにくいかなというふうに思ってあります。","id":"exchange-031"},{"speaker":"菊地委員","kind":"質問","question":"住民の皆さんが行った請求そのものを別に東京都が受け付けたということではなくて、どういう意味なんですか、今課長が言われたのは。","respondent":"浜脇住環境整備課長","answer":"窓口でこれは区の問題だよとやるんじゃなくて、都のほうも一回聞いてみようということで受け取ったんじゃなかろうかと私は思ってあります。私どものほうの意見としては、指導要綱はあくまでも行政指導ですので、法的なものではないです。","id":"exchange-032"},{"speaker":"本多委員","kind":"質問","question":"どうしても制度の要綱どおりの計画に対するものですから、これは建設委員会で請願に対し結論を出すのがやはり請願者に対しての親切だと思います。結論を出すということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"藤田委員","kind":"意見","question":"これについては、現時点では各条例、我々がつくっている条例ですので、それに従って進めていただくのがいいんではないかなというふうに思います。したがって、今日結論を出すということであれば、私も賛成いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"菊地委員","kind":"質問・要望","question":"都に対して請求したと、それを受け付けられるかどうかは別問題としても、もう少し都に対してどういう要望を住民の皆さんが行ったのかも含めて。ですから、私も改めて今しばらくこの問題については継続すべきではないかなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"}]},{"id":"topic-04","title":"の大崎駅東口第３地区再開発事業の状況","agenda":"の大崎駅東口第３地区再開発事業の状況","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"すみません、ちょっとよくわからないんですけど、大崎一丁目ビル、仮称なんですけれども、この部分というのは、３月の施工区間とはまた別なんですね。事業主の単独事業として立ち上げるビルという見方なんか尋ねました。","respondent":"上野都市開発課長","answer":"これ以外の、大崎駅東口第３地区の施工区域になってありますけれども、ここは組合再開発事業で実施いたします。ただ、地区計画は一体的に地区計画が定められてありますし、この御成橋とかの工事調整も一体的に調整して行われる予定です。","id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと今まとめて話すと、もう一点、大崎駅の東口の歩行者デッキ、平成１８年度までに完成をさせる。今実際に事業費として第３地区の開発事業者が手がけるものなのか、ちょっとその辺、よくわからないので教えていただけますか。","respondent":"上野都市開発課長","answer":"現在のところ、区が施行者となりまして、国費を導入して整備いたす予定です。都市再生総合整備事業という制度を使いまして整備いたす予定ですけれども、第３地区のほうの、あるいはティクスの負担を考えてあります。","id":"exchange-037"}]},{"id":"topic-05","title":"の二世代住宅取得および環境共生住宅助成の募集","agenda":"の二世代住宅取得および環境共生住宅助成の募集","exchanges":[{"speaker":"藤田委員","kind":"質問","question":"ですから、この環境助成については、それはやっぱりプラスする方向で今後ぜひ取り組んでいってはいかがかなと思うんです。重い水を持っていくのは大変なんだという話をよく聞きますので、これについてはどのような認識をされているのか。","respondent":"松代道路公園課長","answer":"具体的にまだそれを設置したというのは、ちょっと今のところはございません。今まで新築、そういった例は今までは１件もございませんが、具体的にお示しをして漏れのないようにしていきたいと考えております。","id":"exchange-038"},{"speaker":"藤田委員","kind":"質問・要望","question":"ですから、行かれるかどうかわかりません。これは、ここで結論を出すというようなことではありませんので、ぜひ前向きに検討していただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"原委員","kind":"質問","question":"参考までに一つ伺いたいんですけれども、それから太陽熱温水設備工事というんですか、現状どうなのか。５件３０万円という助成件数になってきているわけなんですが、ちょっとその辺を説明を求めました。","respondent":"阿部住宅課長","answer":"その場合、実際は大手のメーカーが直接やられたというふうなことで、金額的にはお渡しをしているのはその１件だけです。ですから、その助成については、平成１５年度は１５万円でございましたので、１５万円を助成したです。","id":"exchange-040"},{"speaker":"原委員","kind":"質問","question":"それと、区内でどのぐらいこういう設備をつけているのか調べていないか尋ねました。","respondent":"阿部住宅課長","answer":"それについてはちょっと調べてございません。","id":"exchange-041"},{"speaker":"原委員","kind":"意見","question":"そして、そういう下調べをしないでもって、これは助成したほうがいいよとか、要するに、これを普及させていこうという趣旨でしょう。何かちょっとこの事業をやる上において、もう少し何かちょっとした調査があってしかるべきだろうと思うんだけどとの意見を述べました。","respondent":"阿部住宅課長","answer":"そのときに、私ども工務店等の方と協議会を持ってありますけれども、その中でも意見を聞きながら、こういう事業を平成１４年度から始めたです。その時点で業者の意見を聞いて、ただ、その時点で確かに委員おっしゃるとおり区内にどれぐらいの設置をしているのかということまでは。","id":"exchange-042"},{"speaker":"原委員","kind":"質問","question":"こういった事業をするに当たって、それにおける周りの環境を調整しないでもって事業を立てていくということをするんですかね。この事業だけじゃなくて、いろんな事業について調べているんだろうと思うんだけど、何かちょっと伝わってこない。","respondent":"阿部住宅課長","answer":"区内の工務店などの事業者の方に、どういう区民の方のニーズがあるんだろうかと、そういうことをご相談しながら始めたという事業です。今申し上げたとおり、事業者の方に相談しながら、こういう需要があるということを認識して始めたという事業です。","id":"exchange-043"},{"speaker":"原委員","kind":"質問・要望","question":"それも住民に広めていこうという大きな大前提があるわけですから、いろんな部分でしっかりした調査と助成をしてほしいなという気がいたします。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"本多委員","kind":"確認","question":"環境をよくするということで促進をお願いしたいと思います。改修が終わってホルムアルデヒドの発散基準の数値というのは、基本的にだれが、改修が終わった後はどのように確認するんか尋ねました。","respondent":"片田建築課長","answer":"昨年の７月から建築基準法が改定するということで、今回の事業の内容についても、基準の内容が記載されているものです。したがいまして、空気環境を、空気を測定していただくということまではやっていないというのが実情です。","id":"exchange-045"}]},{"id":"topic-06","title":"の区民住宅（あき家）入居予定者登録募集","agenda":"の区民住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"一つだけ教えていただきたいんですけれども、前年度、実際に区民住宅に入居できた方と、それから平成１５年度のときに申し込まれた方を教えていただきたい。","respondent":"阿部住宅課長","answer":"というのは、単身用がありますので、世帯につきましては１５９世帯、単身については９人、合計１６８です。４月現在、空き家を募集しているというのが１０戸ですので、そのほかについては入居なさっているということになります。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問","question":"何か重大な意味があるのだと思うんですけど、その辺、ちょっと先輩委員のお話をお聞きしたい。やはり、しようがないんじゃないかなというふうに昨今思うんですけど、ちょっとご意見を後輩に一言言っていただければありがたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"原委員","kind":"確認","question":"それから、確認の時期は、各定例会中の２日目の委員会。これは建主との話ですから、我々が入る余地は全然ないわけですから、なるべく話をしていけばいいと思うんですよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回大崎小中一貫校を住民の要望で一部カットしたんですよね、品川区教育委員会は、最上階を。何かその辺の矛盾というんですか、一貫性というんですか、その辺でちょっと自分も非常に悩んでいるところなんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"井上委員","kind":"質問・要望","question":"前回ちょっと、時期を逸した感があるんですが、西品川の家屋崩壊のことで、どこまでどうなっているのか、情報提供ということで教えていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"井上委員","kind":"意見","question":"じゃあ、避難されていた方々は今どうなっているのかということと、そのことに対して区がサポートできることで、どういったことをされているのかとの意見を述べました。","respondent":"片田建築課長","answer":"補償の問題等がありますので、まだ別な場所でのホテルとか、そういうところで対応されているという話です。業者のほうが用意したホテルとかじゃなくて、自分が探したいということで、一部補償を業者のほうがして対応されているという話も聞いてあります。","id":"exchange-051"},{"speaker":"井上委員","kind":"意見","question":"本当に自分からアプローチしていろいろ解決できる方はいいでしょうけれども、そうじゃない方も中にはいらっしゃると思います。そういう方にはほんとうにご相談に乗っていただいて、フォローしてほしいと求めました。","respondent":"林（和）委員長","answer":"以上で、本日の予定はすべて終了いたしました。なお、次回の委員会につきましては、５月２５日に河川大会への参加を予定いたしております。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/107143?Template=document&Id=3780#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":27457,"voices":135}},{"id":"h16-20040511-9","meetingId":"h16-cm05","date":"2004年5月11日","dateIso":"2004-05-11","committee":"文教委員会","time":"午後１時０４分～午後３時４５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"を議案に供します。 教科書採択事務","agenda":"を議案に供します。 教科書採択事務","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"教科書調査研究会というのは、常に置いているものなんですかということ、それとも４年に一度につくられていくのか。それから、皆様方に対する報酬がどのような形で支払われているのでしょうかということを、まず説明を求めました。","respondent":"中島指導課長","answer":"それから、２点目ですけれども、検討委員会、そして、研究会のほうは採択の年の設置という形になります。３点目の報酬ですけれども、基本的にそれぞれの検討には時間が非常に多くかかります。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"教科用図書調査検討委員会と、教科書調査研究会は、例えば常任委員会のようなものではなくて、４年に一度、教科書の改訂があったときに編成されているということでよろしいんか尋ねました。","respondent":"中島指導課長","answer":"教科書の採択替えがある年につくられていくという形になります。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"当初、例えば４月の上旬ぐらいに検討された教員が人事異動になる可能性はあるわけですね。そういうときに、教科書採択の事務の引き継ぎ、そんなことには十二分に対処しているんでしょうかということをお伺いします。","respondent":"中島指導課長","answer":"４年に一度の採択におきましては、こういった方々にお願いをして、この組織をつくっていただいているという状況があります。基本的に６年間、プラスマイナス多少ありますが、４年という間の中で継続してこの委員になっているという教員も数多くあります。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"品川区の教育委員会の掲げる教育の方針に沿って教科書を採択すべきだと思います。精神が、対策といいましょうか、それはできているんでしょうかという確認を最後にお伺いしたいんです。","respondent":"中島指導課長","answer":"先ほどの予定表にもございましたが、全体の会を開催する前に、まず検討委員会のほうを先に開かせていただいております。こういったようなものの中で全員に説明をした後に、分科会でそれぞれのチーフの校長から再度考え方についての説明をするというようなやり方をとって。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"詳しく内容を教えていただきたいのは、今回で３回目ということですけれども、その辺の関係が僕にはよくわからないんです。別の教材を取り入れるのか、その辺のところを説明してほしいと思います。","respondent":"中島指導課長","answer":"したがいまして、それぞれの教科で学ぶためには、それぞれの教科書を使っていくことができるわけです。６、７年生あたりでは一貫教育ならではの特色を出していきたいと考えていますので、このように考えているところです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"副読本を使うというお話ですけれども、具体的に聞きたいのは、小学校は１年生から４年生になると、算数と国語の授業時数が増えますよね。教科書は教科書として読みながら、副読本を使っていくのか、その辺の関係をもう少し教えてほしいと思います。","respondent":"中島指導課長","answer":"ここのカリキュラムの内容を具体的にどういう形で指導をしていくか、これはまさに今私どもの検討委員会のほうで検討をしています。新たに問題を作成したり、ワークシートをつくったりというような取り組みが考えていけるところかなと、こんなふうに思ってあります。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"市民科が新しく形成されますけれども、区として教科書をつくるのか、その辺のところが私はよくわからないので、教えてほしいと求めました。","respondent":"中島指導課長","answer":"基本的には市民課でもいろいろな場面で使う、副教材となるようなものをつくっていきたいなと考えておりますが、すでに実施している状況もあります。全体の計画ができた段階で、そういったものをどういう形でまとめていくか、これを今検討している状況です。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"教育委員会の中で何か採択というんですか、検討というんですか、そういうことが行われるんでしょうか。プリントというのはあれですけれども、副読本などは教育委員会でどんなふうに検討をされていくのか、ここだけ最後に説明を求めました。","respondent":"中島指導課長","answer":"通常のこれまでの学習指導要領では見られないような内容、また、取り組みがあります。一つのまとまりのある指導ができませんので、現在検討委員会の中で、それに最も適したものを検討していこうという形で取り組んでいるところです。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"その間の教科書を選定する業者というのは１社という意味なのか、その時々で、そこら辺はどういう仕組みになっているのかというのが一つ。８月１５日まで非公開とするということですが、８月３日に教育委員会をやった後から公表するという意味なのか、内容もご説明をお願いしたいんです。","respondent":"中島指導課長","answer":"８月１５日まで非公開という部分ですが、実際の採択におきましては８月３日に終了する予定です。これはあくまでも予定ということでございまして、さまざまな状況が考えられますので、都へ提出する８月１５日までの間に少し余裕を見てあります。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"８月１５日に都のほうに提出した後は、公表されていくのか、公表の仕方というのはどういう仕方が考えられているのか。そこだけ最後にお聞きしたいと思います。","respondent":"中島指導課長","answer":"検討委員会の中に保護者の代表の方に入っていただいておりますので、保護者の方の目から見たご意見が頂戴できるものと、こんなふうに考えております。８月１５日以降に、基本的には情報公開請求をいただいて、お答えしていくという形になろうかなと思います。","id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"教えてほしいんですが、検定は４年ごとのスパンでやられていると思うんですけれども、そこの関連はどうなっているのかということ。そんな話があったという、実際に修正された例があれば教えてほしいと思いますが、いかがか尋ねました。","respondent":"中島指導課長","answer":"１年間経って、４年間使う教科書ではありますが、教科書会社の基本的な姿勢です。各学校での使用において、シールを貼って、それを各学校に送付するというような状況が一例としてございました。","id":"exchange-011"},{"speaker":"沢田委員","kind":"質問","question":"今度は小学校ですから、実態はどうだったのか、もしあったら教えてほしい。相当な歴史の史実の書き替えが必要なんじゃないかと思うんですが、あの問題では何かあったか、もしあったら教えてほしいんです。","respondent":"中島指導課長","answer":"そういったものは私どもの採択の対象からは外すというか、採択のしようがない、物がないので、こちらのほうで研究調査できないという形になります。そのときに、教科書会社のほうからそういった形での通知がきていたように思いますが…","id":"exchange-012"},{"speaker":"沢田委員","kind":"意見","question":"実際的に校長先生が入ったり、現場の担当教師が入っているということで、その意見はどこかに反映されるのかどうなのか。私は、ある程度現場の教師の意見というのは尊重したほうがいいんじゃないかなというふうに思うんですが、そのことだけ聞かせてもらいたいと思いますとの意見を述べました。","respondent":"中島指導課長","answer":"こちらの研究会が校長と教員で構成されているのも、教員の専門性をここで生かすしか調査研究はできないという判断であろうと考えます。教科書としての特徴としては、調査研究ができるというところで、現場に即した形でのここでの調査が可能になっていくものと考えております。","id":"exchange-013"},{"speaker":"石田副委員長","kind":"意見","question":"そうなってくると、残った３年間は毎年同じものを採択しているわけですね。これは矛盾しているだろうと、上申しているのか、そこら辺の考えをお聞かせ願いたいと思いますとの意見を述べました。","respondent":"中島指導課長","answer":"その４年間の中では、法的にもこの４年間の中はその会社は変えてはいけないというところで、認識をしています。４年が法律上決まっていることに対して、一応この４年というスパンの中で検討をしていく形で進めてまいりたいと考えているところです。","id":"exchange-014"},{"speaker":"石田副委員長","kind":"意見","question":"の３年間は同じ教科書を、４年間その後やればいいわけで、上申すべきだろうと私は思うんですとの意見を述べました。","respondent":"谷田部学務課長","answer":"私のほうで教科書の無償給付の事務をやっておりますので、私のほうの立場でご説明をします。そういうような手続きになってございまして、一教育委員会のほうで教科書を毎年替えるとか、そういうことというのはなかなか難しい。","id":"exchange-015"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"学力テストの集計を業者に今回初めて委託をしておりますが、委託の内容と、業者名を教えてほしいと求めました。","respondent":"中島指導課長","answer":"その学校で実施しました回答用紙、結果、こういったようなものをすべて委託という形で担当していただいております。委託業者ですけれども、これはＮＴＳという業者に委託をさせていただいてあります。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"お伺いしたいのは、日本の教育制度の何が問題だったと国連の子どもの権利委員会が指摘しているのかということを教えていただきたいのと、子どもが。日本の教育はこうでしたというような、自分の体験を通じての発言をもうちょっと教えてほしいと求めました。","respondent":"中島指導課長","answer":"ＮＴＳというのは、教育系の総合研究団体の研究組織という形の位置づけであろうと思います。そういったものにつきましては、私は今こちらのほうに持ってございませんので、また調べてお答えしたいと思います。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"今知らないとおっしゃいましたけれども、品川区は教育改革をこれまで６・３制は問題が生じていると。ぜひ教育長や教育次長に伺いたいんですけれども、どういう勧告がこの間政府に出ているのか、認識を教えてほしいと求めました。","respondent":"中島指導課長","answer":"各メディア等の情報を収集しておりますけれども、これは私ども大変力のないところでございまして、そういった情報収集が十分できておりませんでした。これにつきまして、私のほうでまた調べて委員にお答えできるような態勢をつくりたいと考えています。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"区は独自にプラン２１を進めていますけれども、今後のプラン２１、改善すべき点は改善してほしいと求めました。これは要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"その経過報告といいますか、１年間こういう取り組みをして、こういう結果でしたというところまで踏み込んで言えるのかどうかということです。学校として評価を今後どういうふうにしていくのかとか、今年はどういう形で評価をして、公表していくとかという点をお聞きしたいと思います。","respondent":"中島指導課長","answer":"プラン２１全体の進行状況の情報収集等を含めまして、この学力定着度調査から学校が取り組んでいく状況について、個別に学校に支援をしています。大きなところでは、今言ったような、外部評価、また、分析評価、こういったものを継続していきたいと考えております。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"品川区の中の学校の教員たちが知ることで、均等が得られるというんですか、そういうような形になれたらいいなというふうに思っております。学校教育に目を向けてほしいという気持ちもあるんですが、校長先生等々の方針の中で変化があったのか、そこら辺をお聞きしたいんです。","respondent":"中島指導課長","answer":"保護者の感想等については、こういうふうにアンケートで答えていただいた方、小学校におきましては約８０％になっているという状況があります。これは、保護者の方がそういったところで学校の取り組みを評価してくださっているのかなというふうに判断しています。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問・要望","question":"競争をあおるというやり方はやっていないと思いますけれども、楽しく学習できるような、そういう一つの方向として使っていただきたいなと。いろいろな方法を、情報共有化をこれからも続けてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問・要望","question":"正副委員長に確認をさせていただきたいんですが、何をどういう形で視察に行くのかということとか、視察に行くことを考えると思います。たまたま今日は最後の委員会なものですから、こうした目的と言いましょうか、正副委員長の考え方を改めてお聞かせいただきたいんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それはやっていただきたいと思うんですが、そういう意見をあえて述べさせていただきまして、終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/544596?Template=document&Id=4502#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":23576,"voices":65}},{"id":"h16-20040511-5","meetingId":"h16-cm05","date":"2004年5月11日","dateIso":"2004-05-11","committee":"総務委員会","time":"午後１時０４分～午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"の品川区の政策評価について（政策評価のしくみと試行結果）","agenda":"の品川区の政策評価について（政策評価のしくみと試行結果）","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"カラー刷りのほうからお聞きします。内容はともかくとして、このブルーの線の意味するところを、議会に説明してくれますか。","respondent":"榎本行財政改革担当課長","answer":"こういうしくみづくりをして、それの進捗状況については、適宜報告を行うという形だと思います。この意見の部分につきましては、この中の質疑での部分も入るとは思うんですけれども、第一義的にはこの委員会でのいろんな質疑の中を想定しています。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"意見","question":"どの場所でというのは、いろいろお考えになっていらっしゃる。いい悪いという評価をするんじゃなくて、こういう評価をいただきましたよという報告は、その辺の委員会はお考えになっていらっしゃいますかとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"今のところ想定していなかったんですけれども、やはり中身の部分で、こういう報告書の中で具体的なやり取りというか、その部分を伝えるということであれば、それぞれの委員会の場で説明するつもりです。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"例えばなぜこういうところがこういう評価に値するのか、そういうような議論あるいは聞くという場所は、榎本課長が例えば文教委員会に出てということになるわけか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"その辺はいろいろあろうかと思いますけれども、具体的な質疑になれば、私がそちらに出向いてご説明をする場があるのであれば、そういう形にしたいと思います。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"そういうふうに理解していいんですか。教育委員会あるいは保育課とか児童課とか、いわゆる所管の職員というか、どういう形で区側に具体的にこの評価が伝わっていくんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"これはあくまでも外部評価委員会の評価だという形での説明をして、そういう意見についても十分説明できるかどうかとか、そういうものを踏まえてきちんと対応していきたいと考えています。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"外部評価委員会がこういうふうに結果を出された後、活用の仕方というのは結構なお金をかけていると思うんですね。その課なり係なりに伝えていって、これが活かされていくというパターンなのかな、そういうふうになるんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"お伝えしてありまして、私のほうが特に説明をしないと、その辺はきちんと伝えていくというふうに考えています。中身的には、事業部のほうでも十分これに対してのいろんな意見というのは認識ができますし、対応もそれぞれ考えられるというふうに思っております。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"その辺については、だれがどこでどういう形で議論をするんですか。これに沿って自分たちの自己評価、事務事業評価と照らし合わせてどこが違うのかとか、細かく検討を加えていくという作業はなさるんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"そういう意見もあるとすると、それに対して今度はどう事務改善をしていくのか、事務事業の見直しをしていくのかという形での受け止めは十分できるように考えております。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"意見","question":"他人の目というのか、そういうところをきちんと受け止めて、次のステップにするというようなことは伝わっているんですよねとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"伝えたいと考えていますし、伝わっているとも考えていますけれども、いろんな場でそういうものを伝えていきたいと考えています。例えば、私のほうでもいろんな実施計画等の研修会をやっていますけれども、こういうところがこういう意見をもらっているとかという説明を加えながら。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"最後に要望だけ。どこに活かされたということがわかれば、その辺はできる範囲で議会のほうへお願いをしたいと思うので、要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"川西委員","kind":"意見","question":"もう一つは、２年に一遍やられる世論調査というのが、この辺では区の各所管課の人たちは残念に思うかどうか。今まで、こういう評価をしないときのイメージで言っている世論調査のデータというのは、遡って調査してみたことはありますかとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"聞き方が３ランクで聞いているということもありまして、答えづらいんじゃないかという部分と、そういうご意見を十分いただいています。大体ベスト３がありまして、やはりそういうところが重要だという話が出てしまうので、それとは違う形での聞き方をこの中ではしたです。","id":"exchange-009"},{"speaker":"川西委員","kind":"質問","question":"今、品川区がこのような方法でいろんな施策を実施しているということを、質問の中に入れながら答えを出させようとしている。これまで実施してきた中身を説明しながら質問をしているかどうかということだけ伺います。","respondent":"榎本行財政改革担当課長","answer":"子どもを育てるための施設整備やさまざまなケースに対応できる保育所等の充実など、ご意見がいただけないというところもいただいております。魅力ある教育環境づくりの推進」という設問に対して、よくなったか、悪くなったかという形を聞いてあります。","id":"exchange-010"},{"speaker":"土井委員","kind":"質問・要望","question":"いろいろご報告をいただいているわけですから、それとの関連で、外から見たらどうもあんまり評価されていないよとか、評価されているよと。外部評価委員会ではこう出ましたよという説明も含めた理解を求めて、何かちょっと不足しているように思えてならないものですから、もう一度。","respondent":"中尾根企画部長","answer":"そのような部分がありますので、先ほど榎本課長が言った部分で不明瞭だという意味は、そういう意味です。今後委員会の中で十分材料としてやっていただきたいと、こういう願いがありますので、その辺のところのご理解はお願いしたいと思います。","id":"exchange-011"},{"speaker":"土井委員","kind":"確認","question":"今、いろんな意味での識者あるいは区民の皆さんからご意見をいただくわけですから、これを反映していかなきゃならないということでは。も伺えるわけですし、そのことこそが反映をしていく大もとになるんだというふうに思いますので、よろしくお願いだけして終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"本田委員","kind":"質問","question":"例えば今回子育てと教育ですか、内部評価等々を含めて事業の進行と現況をどういうふうにしたのか、つまりそのことが今度は区民にわかる。より行政を透明的にして、コスト面から、そこのところを具体的にどういう具合になるんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"例えば今回子育てのところで、就学前児童の多くの世帯を対象にした事業の展開を図っていくことが必要であるという形で、ご意見をいただいております。それぞれの具体的な施策を、さらにレベルアップする中の一つの要素として入ってくるのかなというふうに、私は考えております。","id":"exchange-013"},{"speaker":"本田委員","kind":"意見","question":"ここのところでは反映して、反映の結果がどういう内容だったのか、しかもそれが新たに区民に公表と言いますかわかるふうになる。よりよいものに大きくなっていくというつながりがどういうふうに進んでいくのかなというのが、その辺をもう一度お尋ねしておきたいと思いますとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"委員のご指摘にあった部分が、そういうものを踏まえてさらにステップアップしていこうという形での流れが、ここの議論の中では出てきております。と同時に、社会情勢にきちんと合った形の状況を説明した上で…","id":"exchange-014"},{"speaker":"本田委員","kind":"質問・要望","question":"より開かれた行政執行を図っていくという点で、外部評価委員会の客観性なり信頼性なりを一層高めていくことにもつながっていくと思います。その反映の内容とか、そういうものをできるだけわかりやすく区民に公にしていくという努力をしていただきたいということを要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"確認","question":"１点伺いたいんですけれども、外部評価委員会で評価の主体になっていくんだとのことなんですが、ちょっと確認しておきたいんです。「評価の客観性、信頼性の向上」というのは、文章的に外部評価委員会の評価の客観性ということなのか。","respondent":"榎本行財政改革担当課長","answer":"外部評価委員会そのものが区の施策に対しての評価をしていくという形の意味で、そういう形の客観性、信頼性の向上を目指しますという形での言い方をしています。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、外部評価委員会自身が主体的にどういう調査というか、そういうものをやっていくのかなというのがよくわからないんです。ここでは区民から公募された方を含めて、外部評価委員会自身で調査する、アンケートするということは実際にやるんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"外部評価委員会の中では、そこまで想定しておりません。そういう材料は全部区のほうで、今の段階では考えておりませんし、そこまでは手が回らないのではないかと考えています。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問","question":"さっき評価の客観性、信頼性の向上というふうに言うんだけれども、それはどういうふうに担保するのかということになってくるんですよね。そこのところはどうか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"外部評価委員会がいろんな分野のデータを知りたいということであれば、そのデータについて区が全部集めてきて、こういうデータでどうかという形で示しますので、あえて外部評価委員会が調査する必要はないというふうに考えております。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"そこのところは指摘しておきたいと思います。１、２、具体的にこういうところで今度はどういうふうに改善した調査なりをやっていくんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"この満足度につきましては、各自治体にいろんな取り組みがありまして、その辺も外部評価委員会の中でも議論しました。４段階、５段階、世論調査の中には改善した形でのやり方をしていきたいと思います。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"どういうふうに住民の声を把握していくかということをもっと工夫していかないと、全体が見えない評価になっていきやしないかという心配があります。最後にお伺いしたいんですけれども、外部評価委員会のあり方自体は、外部評価委員会で議論するんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"十分認識をしておりますし、そういった意味でも、これからの充実も図っていきたいということです。外部評価委員会が区民に対して、区の現状について説明をすると同時に評価もいただくという形になりますので、一つの役割というふうに考えております。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"意見","question":"ちょっと読んでいなかったんだけれども、外部評価委員会の役割でかなり意見が出ているようですので、機能を評価することも含めてやったほうがいいのかなという意見を述べておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"武内委員","kind":"質問","question":"先ほど、ホームページに載せて、区民の方から幾つかご意見をいただいたとおっしゃっていたんですけれども、どれぐらい意見が来たんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"これが出たということを出しておりませんので件数自体は少なくて、他自治体からの問い合わせが今のところ一番多いという形です。今現在まだ事務事業評価に比べると大分少ないですので、どんな形で政策評価を行っていくのかという問い合わせがございました。","id":"exchange-022"},{"speaker":"築舘委員","kind":"意見","question":"今回、子育てと学校教育という２分野を世論調査によって、満足度、重要度という観点で選択したということで、今後の方向性としては、どういうふうにしていくのかということの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"３４ページに重要度・満足度・コストという形で図が入っておりますけれども、今回、子育てのほうは重要度・満足度が総体的に低い位置を占めている。この辺の動きを見て、今後もこういう形でのデータは常に出しつつ…","id":"exchange-023"},{"speaker":"築舘委員","kind":"意見","question":"それを参考にしていくわけですけれども、そのときに重要度・満足度が低いという場合には、どういう対策を取っていくのか。これに関することを参考にして、今回の子育てとか学校教育に関しては、どういうふうに対処していくのかということの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"子育て、具体的な部分の対応というのはなかなか難しいんですけれども、今回の外部評価委員会の中で全体を通してのご意見をいただいております。実施計画も含め、こういう評価も含めて、さらなるＰＲをしていかなければいけないというふうに考えております。","id":"exchange-024"}]},{"id":"topic-02","title":"の平成１６年度区政モニターの委嘱","agenda":"の平成１６年度区政モニターの委嘱","exchanges":[{"speaker":"武内委員","kind":"質問","question":"単純なことであれなんですけれども、人口割に対して委嘱数が少ないところ、多いところがありますけれども、これは必ずしも人口割の数を委嘱するというふうになっているわけじゃないという考え方でよろしいか尋ねました。","respondent":"中川原広報広聴課長","answer":"人口割はあくまでベースにするんですが、応募者数がそれに比して多い場合は、それも勘案しています。","id":"exchange-025"},{"speaker":"武内委員","kind":"質問","question":"例えば、一番最初の品川地区を見ると、応募者が２４名いらっしゃって、人口割が１３名なんですけれども、１２名委嘱されて、残りの１２名の方があまり適さないというか、そういうことで１３名の人口割に対して１名が減っているという考え方になるんか尋ねました。","respondent":"中川原広報広聴課長","answer":"適さないということなんですが、人口割の１３名の数と応募者数のパーセンテージを割ってみまして、そこの中で微調整が入っています。適さないということでは、必ずしもないということです。","id":"exchange-026"}]},{"id":"topic-03","title":"の２番目の所管事務調査を行います。 都区財調に係る都区検討会の平成１５年度検討結果","agenda":"の２番目の所管事務調査を行います。 都区財調に係る都区検討会の平成１５年度検討結果","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"平成１８年度というのを、やっぱり特別な年だというふうに考えていらっしゃるんですかね、いわゆるお金を扱う方々は。","respondent":"市岡企画財政課長","answer":"現在の状況はそうではないわけですが、ただ財調の算定という側面から考えても、この６年間が派遣職員の身分の切り替えの期限である。１５年と４年間の実績が出まいりましたので、そういう認識は変わっておりませんし、内容は別にして認識は同じだということです。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"意見","question":"それとも６年というのは意味があって、もろもろあって６年という具体的な６という数字が出てきたというふうに、財調のほうでいいです。この６という数字の根拠というか、考え方をちょっと聞かせてくださいとの意見を述べました。","respondent":"市岡企画財政課長","answer":"この６という数字には、清掃以外必然的な理由はありません。６という数字は清掃以外、何の必然性もありませんので、それは間違いないです。","id":"exchange-028"},{"speaker":"林（宏）委員","kind":"質問","question":"都と区の間で従来からあった４７％の５３％ですか、それを見直していくという、それから清掃事業そのものの移管ということで上乗せをされたという。首都といえども、正々堂々と区の財源として都と区と分け合っていくべきだということを言っている５７％という数字は、その辺を聞かせてください。","respondent":"市岡企画財政課長","answer":"しかも、７４５億円というのは、当時内訳の説明があって積み上げた数字です。もし、当時と都区関係ないしは改革後の大都市行政のあり方について、状況と認識が東京都は少し変わってきているということに尽きるだろうと思います。","id":"exchange-029"},{"speaker":"林（宏）委員","kind":"意見","question":"もう一つ加えれば、都の財政状況が依然としてよくならないというか、前ほど下ってはいないんだけれども、上がっていないということなんです。調整ができていくのか、その見通しというか、その辺を聞かせてくださいとの意見を述べました。","respondent":"市岡企画財政課長","answer":"それこそ日々の区民生活に直結した財源の問題ですから、毎年度この委員会でもご報告しているとおり、具体的な各年度の財調協議をやってあります。都区検討会でやっている議論ですけれども、５７％だ、いろんな意味があります。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問","question":"戦線と言えるかどうか、２３区の先頭に立ってもらっているわけだけれども、足並みが乱れるとかいろんなのがある。２３区で、そういったことを話されることがあるんか尋ねました。","respondent":"濱野助役","answer":"ただ、これは状況の説明になってしまうかもしれませんけれども、財調の問題で今までとは違った都の姿勢というのは非常に強く感じます。それを国に発信していくような方向づけを２３区からできないかというようなことを話したんですが、東京都から国に示したらどうだ。","id":"exchange-031"},{"speaker":"本田委員","kind":"質問・要望","question":"この法律の制定にあたって、平成１０年ですか国会の答弁等からも、都はそれと違った全面否定という立場を取るわけです。平成１５年度にいろんな議論をやってきて、なぜこうも解釈が違うのか、もう一度そこのところをお話しいただきたいと思うんです。","respondent":"市岡企画財政課長","answer":"全体として、この１年間の協議を経過してみると、東京都はある意味では意識的に突っ張っているような姿勢を見せているところがあります。いろんな議論によくあることですけれども、少し突っ張った強弁をして協議の土俵づくりをしているというような…","id":"exchange-032"},{"speaker":"本田委員","kind":"質問","question":"都の言っていることと２３区が言っていることと、今後の平成１６年度にいろいろな行動をしていくという中には、役割分担を明確にしていく。法改正の中で明らかになっているわけですから、もっとインパクトの強い２３区が連携をして、もう一度意気込みを。","respondent":"市岡企画財政課長","answer":"これまで積み上げてきた議論をもう一つ違うレベルで突破するような、何か具体的な行動計画みたいなことが図られるような予定になってあります。今まだこの段階では私どもははっきり見えておりませんが…","id":"exchange-033"},{"speaker":"本田委員","kind":"質問・要望","question":"構築が今進められておりますけれども、そういう明解な立場等も大いに活用しながら、それが品川区の自治権拡充だと思っているんですね。そういうことを平成１６年度は強力に展開していくようにお願いをしたいと、要望をしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"土井委員","kind":"質問・要望","question":"ということは、一致団結してこの問題については５７％がベストから始まっているんですよということで、その辺についてお聞かせいただきたいのが一つ。例えば今年はそれはどうだったんでしょうかというのと、それによって都はどういうふうに考えているのか、その辺を確認の意味で聞かせてください。","respondent":"市岡企画財政課長","answer":"東京都は、そんなに言うなら区がやってみたらできますかというふうな認識が袖の下に見え隠れはしますけれども、ここは原則論を。この数字は東京都も認識しておりますので、平成１７年度までは、このラインというのはほぼルールと実際の経費が一致している状況になっています。","id":"exchange-035"},{"speaker":"土井委員","kind":"質問・要望","question":"区が当然やるべき事務という形になってくるでしょうから、小中学校で同じような議論をやっているわけですから。そういうものを求めてもやっていただけることが必要なのではないかなと思いますので、よろしくお願いしたいということでお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"意見","question":"今までのそういう運動をやってきた経過からいけば、またそういう角度の取り組みも必要になってきているのかなというふうに感じました。ちょっと感想だけとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"林（宏）委員","kind":"確認","question":"一つだけ確認を。清掃事業のことじゃなくて、財政上というか、その辺のところ。","respondent":"市岡企画財政課長","answer":"もともとこの５項目を別な検討会でやる必要があるというふうに考えたのは、これだけ大きな問題は協議できないだろうということかありました。例えば、私は十分あるというふうに考えておりますし…","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/406359?Template=document&Id=1650#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":39698,"voices":90}},{"id":"h16-20040517-12","meetingId":"h16-cm05","date":"2004年5月17日","dateIso":"2004-05-17","committee":"清掃制度特別委員会","time":"午後１時０５分～午後２時０１分","status":"正式会議録","sourceType":"formal","overview":"清掃制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"意見","question":"字句の問題ですけれども、１の２行目「するべき」を「すべき」では、いみじくも書記は「すべき」と読みましたけれども。４の一番下の行で「検討すべき」と書いてあるんですねとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"石田委員","kind":"意見","question":"共同処理を継続する方針をもう１回改めて再考してほしいというのと、今度は当分の間というのは、明確な期日を必ず出してくださいということで。共同処理を継続する方針自体を再考することも検討してほしい」というぐらいを残していただければありがたいかなと思っておりましてとの意見を述べました。","respondent":"山路委員長","answer":"ただいまご意見がありました「共同処理を継続する方針を再考することも検討されたい」と、「抜本的な改革」……。","id":"exchange-002"},{"speaker":"石田委員","kind":"意見","question":"それは「明確にするべきであり、同組合の抜本的な改革を行うべきである」との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"土井副委員長","kind":"質問","question":"この委員会自体がどういう方向で行くのかということで、当初からいろいろ議論があって、こういう思いを込めながら運営をしてきたつもりです。極めて限定されちゃうものですから、こんなふうにさせていただいたということの意味も込めて、皆さんのご理解をいただければと思っているところです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"本田委員","kind":"提案","question":"決断を出して、５項目の改革案の説明を受けたわけですが、そういうことは断固として確保してほしいというふうに思うんです。だから、私としては、この提案されている文章でいいんじゃないかというふうに、今受け止めておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"堺委員","kind":"意見","question":"さらに、今自民党からお話が出ておりました件につきましても、１の中に表現として要約されているような気がするんです。そういう意味で、私としてはこの４点の案でいいのではないかなと、こういうふうに思っておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"２番の「自区内処理の原則を視野に入れつつ」というところなんですけれども、「原則論として持っていなければいけない」「堅持していなければいけない」というふうに考えますけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"土井副委員長","kind":"質問","question":"今の状況等になりますと、持たないところは合併でもしない限り、自区内処理というスタイルになっていかないわけですね。今の状況では土地を買うのも「ノー」と言ったわけですから、言葉上の論議はあまりやりたくなかったものですから、思いだけを説明します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"頭にたたき込んで要望・要求、そういうような意味合いかと思うんだけれども、「検討の課題とするよう」という文言がどうなのかなと。向こう側の受け取り方を確認しておきたいんだけれども、検討の課題にするようにと言われたときに、どんな受け止め方をされますか。","respondent":"中尾根企画部長","answer":"そういう意味からしますと、正直言いますと、ねばならないというほどではないのではないかと。私どもも何を言っているかわからないということには、どちらもなりませんので、その辺のところをお読みいただければと思います。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"確認","question":"要するに清掃工場を区に移管すべきだと、最終的に平成１２年の移管の際に東京二十三区清掃一部事務組合に工場は渡すというふうになったわけだよね。平成６年のまとめの中には、はっきり所在区に移管すると書かれているんですよね、先にそれを確認しておきます。","respondent":"中山清掃リサイクル課長","answer":"平成６年の協議案の際には、財産の扱いの答えの中で、財産は清掃工場に移管する。財産は東京二十三区清掃一部事務組合で引き続き管理するというふうになってあります。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"意見","question":"だから、平成６年にうたっているわけですよね、３の前半の部分で。もし東京二十三区清掃一部事務組合解散とか編成替えということになってくると、必ず、この問題は出てくるわけですよとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"土井副委員長","kind":"提案","question":"当初ご提案をいただいたときも、東京二十三区清掃一部事務組合は我々としては解散をすべきなんだと、今ここでもう既に。平成６年のものもちゃんとやるんですよということを、こんな思いがあったものですから、そのままいただいた中身なんですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"清掃工場は品川区のものとするように図っていけということですから、「清掃工場等は所在区へ移管されるべきである」と訴えていいと思うんです。要らないものは黙っていて、要るもの……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"本田委員","kind":"意見","question":"それから平成１１年に覚書で書いてある３項目の１項目が「財産取扱い」という公式用語を使っているので、今おっしゃられるように具体的にということであるなら、それならそれで別に構わないと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"大西委員","kind":"意見","question":"中心的にリードをしてきたのが自民党会派の委員の方々が多くて、このことに対する思い入れというのは非常に深いものがあると。ついては、私としては、今までリードしてきた自民党の案を尊重すべきだと考えますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"大西委員","kind":"意見","question":"そうですね。もう１点が、「今後執行機関が行うべき検討の課題」と言われましたけれども、あまり重要かどうかわかりませんけれどもとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"石田委員","kind":"意見","question":"最初のところで言ったように、さっきの「所在区ヘ移管されるべきである」みたいに決めつけていくときに、先ほどそういう話をさせていただきました。「については」というのだけはお考えほしいと求めましたけれども、訴えたいところは訴えたいというところなので…","respondent":"山路委員長","answer":"今、焦点がぼけないということのもとに、正副で文章をまとめするということでよろしいでしょうか。何か、ご意見がございましたら。","id":"exchange-017"},{"speaker":"林（宏）委員","kind":"意見","question":"さっき大西委員からもあったように、「執行機関が行うべき指針とするように」と、ちょっときついように、「指標」とか「指針」とか、強すぎますか、「指針」はちょっと言い過ぎかなとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"いろいろ出てくる場面もあるわけだし、やっぱり工場をどうしていくのかと、非常に重要なことだろうというふうに思うんですよね。この委員会の提言がありますので、指標としてこれから一生懸命東京二十三区清掃一部事務組合に向かっていっていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"井上委員","kind":"質問","question":"細かい質問で申し訳ないんですが、１番のところの高齢者世帯への戸別訪問収集で、全体でどのぐらいの方が対象になっているのかということ。先日お伺いしていますけれども、そういった対応はどうされているのか教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"あまり細かいご説明はと思いますけれども、各戸収集のエリアで説明したものについては、職員が取りにまいります。限られておりまして、現在約２００世帯は上回ってきているという、品川区の関係です。","id":"exchange-020"},{"speaker":"菊地副委員長","kind":"意見","question":"委員会の前に必ず正副の打ち合わせをするなど、非常に充実した運営ができたと思います。本当に１年間ご苦労さまでしたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/987464?Template=document&Id=5636#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=12&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":13722,"voices":76}},{"id":"h16-20040517-16","meetingId":"h16-cm05","date":"2004年5月17日","dateIso":"2004-05-17","committee":"街づくり特別委員会","time":"午後１時０５分～午後３時００分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"藤田委員","kind":"質問","question":"今後、やはり今溢水箇所が品川区内でいつも、何度も起こっているというところがありますよね。タイアップして、より一層地域で実践できるこういう訓練ができないのかなというふうに昨日感じたんですけれども、その辺はどのようにお考えか尋ねました。","respondent":"矢部下水道河川課長","answer":"例えば今言ったような西品川一・二丁目でほんとうの演習はできないかという形も考えたんですが、実は消防署としましては、それらの演習をしたいと。水防演習としますと、やはり…","id":"exchange-001"},{"speaker":"藤田委員","kind":"質問","question":"そこからどういう体制で皆さんは持ってきて、いつも溢水する箇所は大体想定されるわけですから、これをちょっと検討できないかということなんです。","respondent":"矢部下水道河川課長","answer":"今委員ご指摘のことにつきましては、今後、消防署、町会等とも協議しながら、どういう形でできるか検討します。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"何点かお伺いしたいんですが、だれが、どういう形で区民の皆さんに触れる形をとるのかということをもう少しお伺いしたいんです。その情報の出し方ですね、それをどういうふうに考えているか、まずお伺いしたい。","respondent":"矢部下水道河川課長","answer":"プレス発表という形で５月２６日に行いますけれども、東京都担当の記者室がありますので、そこへの投げ込みになるかと思います。それから、都庁の第一本庁舎３階の都民情報ルームでもわかるようにしますというようなことです。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"２万５,０００分の１の地図ですから、でも、品川区の場合には立会川にお住まいの皆さんのところと照らし合わせてみればわかってくるわけですね。補正をかけていけばですよ、具体的な品川区の持っているデータに補正をかけて地図をつくれませんか、いかがでしょうかということをお伺いしました。","respondent":"矢部下水道河川課長","answer":"このハザードマップをつくっていこうというのが国の方針というんですか、その中で、こういうのがつくられるようになったと思います。これ以上詳細なものをつくるべきかどうか、そういうことも含めて、ちょっと検討させていただきたい。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"だから、ある程度予想されることについては、あそこはたしか国とかいろんな関係機関が協力し合って対策をつくったんですよね。私たちは品川区民ですから、品川区民の不安をある程度目安の部分で押さえることができないような気がするんですが、いかがか尋ねました。","respondent":"矢部下水道河川課長","answer":"そういうことが起こらないために今これだけ皆さんにご迷惑をかけながら工事をやっているんですよというような形での説明になっていくのかなと思いま…そんな形で対応していきたいと考えています。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"でも、それだけでいいんですか、それに対して、今おっしゃったことは確かにそれはわかります、今言っていること。多少は色づけされるとか、心配事を和らげる地図をつくったらどうかということをお伺いしていますので、その辺のことについてお答えください。","respondent":"矢部下水道河川課長","answer":"各区が対応する洪水ハザードマップの作成というのがございまして、デメリット等含めまして今後検討していくことになっているんですが、そういうものについては検討していきたいというふうに思います。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"意見","question":"どうしようもないのかなということを含めて、そこに住んでいる方自体は、何も責任がない場所ですよね。もう一回、ちょっとそこら辺のところを兼ねてとの意見を述べました。","respondent":"矢部下水道河川課長","answer":"ただ、名称につきましては、東京都のほうでずっとやっておりますので、ちょっと固有名詞としては変えられません。その辺を十分にフォローしながら、もし公表とかＰＲする段階になりましら、その辺は十分考慮していきたいと考えています。","id":"exchange-007"},{"speaker":"藤田委員","kind":"質問","question":"どうしてもやっぱり限られた土地の中で、建主は車庫等をつくりたいために半地下にいってしまうというのは、これが現状じゃないかと思うんですよね。ですから、ちょっと引っかかっていますので、この辺は十分やっぱり建築課と話し合っていくというような形をぜひとってもらいたいと思います。","respondent":"矢部下水道河川課長","answer":"防水板を設置したり、そういうことを今までも指導しておりますけれども、さらに指導を強化していきたいというふうに考えています。ですから、そういう意味で、こういう図面を基にして指導を強化していきたいというふうに考えております。","id":"exchange-008"},{"speaker":"藤田委員","kind":"質問・要望","question":"まさかうちがというところが、入ってきたわけですから、ぜひ検討していただきたい。助成については、もう一度その辺も含めて検討をお願いしたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"木下委員","kind":"意見","question":"一昨年末に東海大震災みたいなことが起こったら、町会単位で、危険度はあなたのところは何々というような発表がありましたよね。かなりどうするんだということで、町会なり何なりの方々に、少しでも不安要因というものが解けるかなと思うんですけどとの意見を述べました。","respondent":"矢部下水道河川課長","answer":"昨今の浸水被害の中でも何回かご説明したり、その地域の方については、ある程度周知されているのかなという感じはいたします。これはこういう条件の中でやっているので、どういう機会をもって説明していくか、それはちょっと検討させていただきたいなと考えています。","id":"exchange-010"},{"speaker":"木下委員","kind":"質問・要望","question":"検討していただければ。そういうのに対しては、やっぱりご検討いただければと思いまして、要望でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"西本委員","kind":"意見","question":"一つ気になる部分なんですが、この浸水予想区域図が発表された後、土地の財産価値といいますか、それにかなり左右されるんじゃないかと。ということもかなり出てくるんではないかなと思うんですが、その辺の対応はどういうふうに考えられているのかなというふうに思うんですがとの意見を述べました。","respondent":"矢部下水道河川課長","answer":"これは既に公表された地域、他区なんですが、そこに対して、東京都のほうでアンケート調査をしているらしいです。そういうようなアンケートをしたところ、ほとんど影響がないというような回答が東京都のほうからですけれども、ありました。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"ですから、１００％安心してくださいとはなかなか言えないとは思いますが、ＰＲも含めてしていったほうがいいんじゃないかなというふうに思います。その辺はいかがか尋ねました。","respondent":"矢部下水道河川課長","answer":"例えば、あるいは区民としてこういうことをやってほしいとか、そういうふうになるべく周知するようにやっております。そうなった場合は、そういうような形で、そういう不安が取り除かれるような形の説明の方法を検討していきたいというふうに思っております。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先ほどの防水板の関係、半地下の関係で出たときに、建築のほうの指導は、ちょっとはっきりわからなかったんだけど、もう一回確認なんですけど、区としてはそこに指導をとれる形になっているんですか、その辺もう一回。","respondent":"中谷まちづくり事業部長","answer":"開発指導要綱の５戸以上とか、そういうものについては、その辺をかなりきめ細かくやっています。その辺、職員は十分にその辺は周知しているということがありますので、連携をとってやらせていただいております。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"確認","question":"建築確認については、例えば、今区じゃなくても、民間でできてしまいますよね。対象地域であるということは、この調整をしないで建築確認をおろすということが認められるのかどうか、そこら辺をもう一回ちょっと。","respondent":"中谷まちづくり事業部長","answer":"そして、また民間の建築確認機関とは連絡調整会を持っておりまして、そういうことにつきましても、区のほうでその際にはお知らせしております。しておりますが、先ほど言いましたとおり、全般的には法的規制力がないので、協力要請の中で行っているです。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"意見","question":"このマップの中では、それ以上答えようもないのかもしれませんけど、今品川にいないんだからわからないという方が買うケースが多いと思うんですよね。その辺どう考えたらいいのかなと、お答えがあればとの意見を述べました。","respondent":"中谷まちづくり事業部長","answer":"これまではその連携は正直言って５年前、そういう連携をかなり密にやっておりますので、一定の効果は出ております。その辺のところについては十分購入者側にその辺を説明するようにというお話もしていますので、今後の課題とさせていただきたいと存じます。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところで、今までもちょっと出ていましたけれども、対策がとられると、この浸水予想区域は大幅に変わってくるわけですよね。そういう予想区域図というふうなものを改めて書きかえて出るというふうなことにもなるのかどうか、そのところもお聞きしたい。","respondent":"矢部下水道河川課長、中谷まちづくり事業部長","answer":"修正につきましては、東京都のほうではある程度の時期が来たら、見直しを考えるというふうに言っております。まだ５５％程度ですから、確かに区のほうで… 国の方針に基づいて東京都が作成しているということで、これは一つには、現時点における説明責任という形でつくっております。先般なりご説明しているとおり、現時点でまずわかっていることを説明していくと…","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。地域の人はもちろん知りたいというふうな思いもあるわけですから、同時に、そういうところまでやっていっていただきたいなというふうに思います。","respondent":"矢部下水道河川課長","answer":"それにつきましては、今申し上げましたとおり、区民の方の反応を見ながら検討していきたいと思います。広報の６月１日号なんですけれども、こういう形で対応をお願いしますとか、そういうようなものをちょっとつくってあります。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"簡単にお伺いします。あわせて、そういう姿勢でいったほうがいいんじゃないでしょうかということをぜひ答弁としてお伺いしたいんですが、いかがか尋ねました。","respondent":"矢部下水道河川課長","answer":"引き続きハザードマップというものを区の分担としてつくることも予定しておりますので、そういうような形で考えていきたいと思います。それにつきましては、こういうものが出たことを契機に、さらにそういう要望活動を強めていきたいというふうに思っております。","id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問・要望","question":"要望しておきます。やっていただきたいんですが、対応方、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/408110?Template=document&Id=6274#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":20489,"voices":59}},{"id":"h16-20040518-14","meetingId":"h16-cm05","date":"2004年5月18日","dateIso":"2004-05-18","committee":"行財政改革特別委員会","time":"午後１時０３分～午後２時４２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"例えば０.１秒のスピードで通過した場合、例えば、投げてそちらへ放り出したとか、何秒でカードが認証するのか。その辺、参考にお聞かせ願えればありがたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"高星委員","kind":"質問","question":"委員会は議会サイドのことですから、議論する中身的も、システム的にまだやらなきゃならないところがたくさんあるのかなという感じはしているんです。これは議会サイドでも議論してほしいというようなことがあったら、そういったものをどこでどういうふうに執行部側は話をもっていくのか。","respondent":"田中情報システム課長","answer":"例えば、きょう、８階に行きましたけれども、例えば、一つの例ですか、どういう部屋なのか、外に表示はしないようにというガイドラインがある。いわば、これを許容していただかないと答弁できなくなっちゃうことになりますので、ぜひその辺はご理解いただきたいと思います。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"あのうち、いわゆる区の職員と民間から入っている職員が、大体何名ずつぐらいなのか。きょうの時点で、おおよそわかったら教えていただけますか。","respondent":"田中情報システム課長","answer":"今、開発で情報システム課のほうに８名から９名ぐらい上がってきていますので、それを入れてちょっと人数が多かったかなという感じです。民間の方は、大体１０名前後ぐらいは、いつもいるという形です。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"きょう、最初に入った部屋の奥で、ものすごい勢いで入力していた、あれが先ほど行ったキーパンチャーの３人なんですか。これは私の気持ち、意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"}]},{"id":"topic-02","title":"続きまして、特定事件調査を行います。 行財政改革に関することのうち、「議員定数に関すること」","agenda":"続きまして、特定事件調査を行います。 行財政改革に関することのうち、「議員定数に関すること」","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"その辺、どのような見解、また考えでいられるのか。ちょっとその辺、お聞かせ願いたいとの意見を述べました。","respondent":"田中情報システム課長","answer":"生のままの、例えば数字ですとか、暗証番号がそのまま出るとはちょっと考えにくいんですね。今のところ、私は聞いてはいないんですが、ちょっと調べてみます。","id":"exchange-005"},{"speaker":"高星委員","kind":"質問","question":"磁気のカードになっているものですから、テレビのそばに長期間置いてしまったという方がいて、磁気も壊れちゃうこともあるかと思うんです。そこだけちょっと説明を求めました。","respondent":"田中情報システム課長","answer":"住基カード等も、小さな入力や出力の機能を持ったＯＳとか、その上のいろいろ処理をするプログラムが乗っている形になっています。磁性が飛んでしまったりすることはあると思いますが、薄い板は小さなコンピュータというところで、ちょっと違うということです。","id":"exchange-006"},{"speaker":"山村委員","kind":"確認","question":"私も質問したと思うんですけれども、確認されているのと、それを読み取ると暗証番号も盗むことができる。私は理解しておりますが、そこら辺はどのように考えているのか、もう一度よろしいか尋ねました。","respondent":"田中情報システム課長","answer":"より高いレベルで、来月あたりから変えていくつもりで、それの展開を予定しております。その点では、セキュリティを考えたネットワーク管理をきちんとやっていくことが大切だと考えています。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/892144?Template=document&Id=5750#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":6920,"voices":30}},{"id":"h16-20040525-8","meetingId":"h16-cm05","date":"2004年5月25日","dateIso":"2004-05-25","committee":"建設委員会","time":"午前１０時０３分～午後３時４８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/107143?Template=document&Id=3782#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":1728,"voices":8}},{"id":"h16-20040527-6","meetingId":"h16-cm05","date":"2004年5月27日","dateIso":"2004-05-27","committee":"区民委員会","time":"午後１時３５分～午後１時５０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/663620?Template=document&Id=2392#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":482,"voices":5}},{"id":"h16-20040527-7","meetingId":"h16-cm05","date":"2004年5月27日","dateIso":"2004-05-27","committee":"厚生委員会","time":"午後１時３６分～午後１時５０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/256749?Template=document&Id=3078#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":476,"voices":5}},{"id":"h16-20040527-8","meetingId":"h16-cm05","date":"2004年5月27日","dateIso":"2004-05-27","committee":"建設委員会","time":"午後１時３５分～午後１時５１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/107143?Template=document&Id=3784#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":483,"voices":5}},{"id":"h16-20040527-9","meetingId":"h16-cm05","date":"2004年5月27日","dateIso":"2004-05-27","committee":"文教委員会","time":"午後１時３６分～午後１時５０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/544596?Template=document&Id=4504#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":472,"voices":5}},{"id":"h16-20040527-5","meetingId":"h16-cm05","date":"2004年5月27日","dateIso":"2004-05-27","committee":"総務委員会","time":"午後１時３７分～午後１時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/406359?Template=document&Id=1652#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":481,"voices":5}},{"id":"h16-20040527-11","meetingId":"h16-cm05","date":"2004年5月27日","dateIso":"2004-05-27","committee":"自治制度特別委員会","time":"午後２時０５分～午後２時２１分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/905389?Template=document&Id=5544#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":570,"voices":7}},{"id":"h16-20040527-14","meetingId":"h16-cm05","date":"2004年5月27日","dateIso":"2004-05-27","committee":"行財政改革特別委員会","time":"午後２時０７分～午後２時２３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/892144?Template=document&Id=5752#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":572,"voices":7}},{"id":"h16-20040527-16","meetingId":"h16-cm05","date":"2004年5月27日","dateIso":"2004-05-27","committee":"街づくり特別委員会","time":"午後２時１５分～午後２時３３分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/408110?Template=document&Id=6276#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":574,"voices":7}},{"id":"h16-20040604-6","meetingId":"h16-cm06","date":"2004年6月4日","dateIso":"2004-06-04","committee":"区民委員会","time":"午後１時０４分～午後３時５１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件整理しています。","topics":[{"id":"topic-01","title":"の１番目でございますが、幹部職員紹介","agenda":"の１番目でございますが、幹部職員紹介","exchanges":[{"speaker":"山路委員","kind":"意見","question":"公明党の山路です。１年間、どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"塚本副委員長","kind":"意見","question":"両事業部の概要を説明いただきました。今までなかったことだと思うんですけれども、せっかくなら、両事業部とも入ったほうがとの意見を述べました。","respondent":"山田区民生活事業部長、金井環境課長","answer":"トータルにご説明したいということで、総括表をつくり、各課のところにも予算を入れた。区民委員会でちょっとまだ連携が取れませんで、お互いにすり合わせをさせていただきたいということで、よろしいでしょうか。 ご意見はもっともだと思うんですけれども、こういう事業がきちっと分かれているものは費用が非常に出やすいんですが、環境の場合はなかなか難しい。その辺もできるだけわかりやすくしたいと思いますが、こんなにきれいにできるかどうか…","id":"exchange-002"}]},{"id":"topic-02","title":"の羽田空港再拡張後の飛行ルート（修正案）","agenda":"の羽田空港再拡張後の飛行ルート（修正案）","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"細かい図面じゃないので、よくわからないんですけれども、守谷方面から入ってくるのは影響がないものなのか。ちょっとそこだけ教えていただけますか。","respondent":"金井環境課長","answer":"今度は、１時間当たり１２便ですので、３便増える。高い異常のある騒音というものは出ておりませんし、苦情も全く来ておりませんので、ほとんど問題ないだろうと判断しております。","id":"exchange-003"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっと確認をさせていただきたいんですが、先ほど、お話の中で、ブルーとレッドのところは、着陸と離陸。そこのところの考え方は、どういうふうに。","respondent":"金井環境課長","answer":"若干説明が不足しておりましたけれども、それ以上で点線になってまいりますので、騒音はほとんど影響はないという形になります。これについては、点線がありますけれども、品川区にはほとんど影響がないということになります。","id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"ということは、飛行ルートにはなっていると。飛行ルートになっていて、少しは飛ぶけれども、品川区に影響がないぐらいの高さだから、別に問題ないというふうにとらえていいんか尋ねました。","respondent":"金井環境課長","answer":"緑色の部分ですと、位置的にも品川区の上空とかなりずれております。それと、高いということで、ほとんど問題がない。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/663620?Template=document&Id=2394#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":46791,"voices":69}},{"id":"h16-20040604-7","meetingId":"h16-cm06","date":"2004年6月4日","dateIso":"2004-06-04","committee":"厚生委員会","time":"午後１時０５分～午後３時３５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"１点だけちょっと確認したいんですが、たまたまやっていない休日なんか、電話のテープが出るわけですね。そのテープとか、もう一歩周知をしてほしいという声がかなり寄せられていますので、そのことをちょっとお聞かせいただきたい。","respondent":"田中健康課長","answer":"今消防署のほうを、それも案内の窓口になれますよというお話をいただいて、それを私どもの広報関係にも載せていこうというような調整をしています。今、委員からご指摘のあった部分を調査いたしまして、できる範囲内で対応させていただきたいと思います。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３点お伺いしたいと思いますが、その辺を教えてほしいのと、精神衛生の部分が大変多いですよね。幼保一元化の絡みもあると思うんですが、なぜ保育課に私立の幼稚園の業務が移ってきたのか、そこを教えてほしいと求めました。","respondent":"田中健康課長、辻田児童課長、金子保育課長","answer":"１６４から１６５ページは、かもめ工房との支援関係、それからホームヘルプ事業を行っておりました。それから、予算関係は… それから、権限を発揮して、いろんな対応をされるです。向こうは信頼関係を持って、あまり露骨に学校に対してすぐ連絡をして対応をとると… 各区市町村でも検討しておりますが、これを今後保育園と幼稚園、どういうふうに展開していくのかということが検討されているところです。その第一歩として…","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"精神保健のところなんですが、先ほどのご説明からすると、障害者のほうに行く部分の予算とのすみ分けという受けとめ方でよろしいんでしょうか。その辺の保健師の担当の部分に変化があるのか、定期的な異動なのか、ちょっとその辺を含めてお答えいただきたいんですが。","respondent":"田中健康課長、寺西品川区保健所保健サービス課長","answer":"昨年度、実は共同作業所、グループホームの運営費補助等々ございましたので、ここの部分は１億６７０万円ほどでございました。ですから… 保健師が受け持ちます事業というのは、必ずしも精神保健業務だけにかかわらず、結核でありますとか大変多岐にわたります。あるいはそういうことによって長年、例えば精神であれば…","id":"exchange-003"},{"speaker":"飯沼委員","kind":"意見","question":"当然いろんなお仕事をされるので担当は変わると思います。くれぐれも引き継ぎのところをよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"武内委員","kind":"意見","question":"２点お願いしたいんですが、６月１日から、まだ始まっていないので載せなかったのか。やる内容に違いがあるのかどうか、この２点、お願いしたいと思いますとの意見を述べました。","respondent":"田中健康課長、辻田児童課長","answer":"そういう部分を考慮いたしまして、担当の方も連絡し合い、４月の時点を中心に今回は編集をさせていただきました。今年度内にもう一度必要な部分の見直しを図り… 基本的には国の事業として正式な名称は、地域子育て支援センター事業です。ついつい子育て支援センターという形でお話ししてしまいますけど、地域子育て支援センターというのが正しいということで、聞かれたほうは。","id":"exchange-005"},{"speaker":"武内委員","kind":"意見","question":"子育てガイドのほうはわかりました。あえてつけたのかなと思ったんですけど、意味はよくわかりましたので、しっかり勉強していきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"築舘委員","kind":"意見","question":"５８ページの女性福祉のところで、ちょっとその辺、婦人というのがまだ言葉として使われるのがいいのかどうかということが一つ。がんというのは、生活習慣病になるのかなという感じで、ちょっと疑問があったので、その２点、すみません、お願いしますとの意見を述べました。","respondent":"寺西品川区保健所保健サービス課長、辻田児童課長","answer":"大腸がん、前立腺がん等の上昇というのは、脂肪摂取の上昇によるものと言われています。やはり、今だんだん食生活の中での脂肪量が増えていることと関連のある疾患ですので、がんも生活習慣病の位置づけとして間違いはないと存じます。 基本的には女性であるとか、どうしてもまだ婦人という言葉が残っているということで、あえてこういう形で使っているものが幾つかまだ残っております。それから正しい使い方をということで、私どものほうは要望…","id":"exchange-007"},{"speaker":"嶋委員","kind":"質問・要望","question":"この１３地域がそれぞれ地域によって環境地域、どういう形でこれから今後やっていくのか、もしわかる範囲がありましたら教えてほしいと求めました。","respondent":"田中健康課長","answer":"従来、各町会の皆さんから１名ずつ推薦いただいて、品川地区と荏原地区という形で進めてまいりました。やはり現在１３の地域センター等の連携を図りながら、１３の単位で、あるいは立ち上げを図っているです。","id":"exchange-008"},{"speaker":"本間委員","kind":"質問・要望","question":"もう少し詳しく説明していただきたいというのが１点。４１ページにあります私立幼稚園預かり保育モデル事業、あるいは教育についての触れる部分はどのようになっているのか、その辺をお願いします。","respondent":"金子保育課長","answer":"５園でということですが、品川、大井、大崎、荏原の各地区１園ずつと、荏原についてはさらに１園を加えて５園で実施しております。現在私立幼稚園はそこにありますとおり２１園がありますが、預かり保育については、７園で実施しています。","id":"exchange-009"},{"speaker":"本間委員","kind":"意見","question":"いかがされるのかなという部分もございましたので、教育に触れる部分があるのかないのかも含めて、その辺の部分を一言お願いしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"本間委員","kind":"質問","question":"もし、その部分について、私あまり細かいことを聞いているつもりはございませんが、差し支えない範囲で結構です。もし、あまりあれでしたら、この部分はやめにいたしますけども、よろしいか尋ねました。","respondent":"金子保育課長","answer":"受けている側の資格ということですけれども、これは基本的には日中で対応している幼稚園教諭、これが中心に対応しているというふうに聞いております。サポートで何名かつくということも例としてあるとは思いますが、主たる受ける側としては、幼稚園教諭というふうに把握していま…","id":"exchange-011"},{"speaker":"南副委員長","kind":"質問","question":"１点だけ伺いたいと思います。２０ページに保育園の在籍状況というのが書いてあって、入園希望を出しても入れなかった子どもさんの状況をちょっと伺いたいと思います。","respondent":"金子保育課長","answer":"保育園入園の待機児に関してのご質問ですが、今年度４月１日現在ですが、品川区では１８４名がいわゆる入園待機児というふうな数になってあります。","id":"exchange-012"},{"speaker":"南副委員長","kind":"質問・要望","question":"１８４名というのは、できたら乳児、幼児、あるいは年齢ごとにもしわかれば、ちょっと教えてほしいと求めました。それで終わります。","respondent":"金子保育課長","answer":"待機児の年齢別の数ですが、０歳児が２８人、１歳児が３６人、２歳児が８６人、３歳児が２７人、４歳児が６人、５歳児が１人、計１８４人となっています。","id":"exchange-013"},{"speaker":"築舘委員","kind":"質問","question":"だけど、中程度以上、もっといくと重度というんですか、それがあるのかどうか。その辺がやっていてどうなのかなという感じ、現場として、その辺をお聞きしたい。","respondent":"早津高齢福祉課長","answer":"現在の段階では、私の認識では、治るのは難しいと言われているというふうに認識しています。大体私の認識はそういう感じです。","id":"exchange-014"},{"speaker":"築舘委員","kind":"質問","question":"もう一点は、３８ページの品川福祉カレッジのところで、ケアマネージメントコースというのがあるんですよね。ケアマネージャーになるためには１年に１回試験があるということで、試験が通って、そこがちょっとわからなかったので説明を求めました。","respondent":"山岡福祉高齢事業部副参事","answer":"つまり、ケアマネージャーの資格を取得した後、その仕事を始められた方を対象に実施しているものです。要するに、ケアマネージャーになってから受講するコースで、試験は通っている方で、ケアマネージャーとしての業務を開始している方です。","id":"exchange-015"},{"speaker":"築舘委員","kind":"意見","question":"どっちだかわからなくなっちゃった。その人たちに限られるということだけれども、現状としては、ケアマネージャーを取りたい人も入っているということの意見を述べました。","respondent":"山岡福祉高齢事業部副参事","answer":"既にケアマネージャーとしての業務をやっていらっしゃる方ということで、資格を取得された後の方ということでお考えいただければと思います。よろしくお願いします。","id":"exchange-016"},{"speaker":"嶋委員","kind":"質問","question":"プラス１６人で３２２名にこれからしていくということで、どういう形で、基本的なところを教えてください。どのように配置をされていらっしゃるのかお教えください。","respondent":"早津高齢福祉課長","answer":"基本的には世帯数をもとに行っておりますが、あるいは担当する町会の区域とかというようなことを勘案して配置しております。１,０００世帯を超えるであろうというようなところについて増員という形で分割するというような形での増員を図ったところです。","id":"exchange-017"},{"speaker":"嶋委員","kind":"質問","question":"そうしますと、１６名の方の配置はもう決まっていらっしゃるのか尋ねました。","respondent":"早津高齢福祉課長","answer":"地域としては決まってございまして、今具体的などなたかというのは、事務作業を進めている最中です。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３点目、平成１２年から始まっていますけど、そこを年度ごとの限度額に対する利用率の推移を教えてほしいと求めました。","respondent":"早津高齢福祉課長、新美福祉高齢事業部長","answer":"冊子にする段階で国民健康保険等について入れする予定になってあります。７月の委員会を目指して、そのときに介護保険の状況報告をいたしますので、その段階でご報告できるかというふうに思います。 そういった連絡もあり、現時点では、当初の予定どおりの整備はなかなか難しいという現状認識です。この点につきましても、今後もう少し今そのご答弁だけということになりますので…","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺も含めて、まだその辺は数字化されていないということなんでしょうか。平成１５年度分はわかるんですね、わかっていたらお知らせいただきたいのと、ぜひご報告をまたはっきりしてほしいと求めました。","respondent":"早津高齢福祉課長","answer":"その段階でご報告をします。今、ちょっと手持ちの資料がございませんで、申しわけございません。","id":"exchange-020"},{"speaker":"本間委員","kind":"質問","question":"どうしても自分が先々のことを考えて、一方では、先ほど高齢者いきがいづくり事業というものを幾つか説明していただきました。要介護１クラスの人たちに対します、今回のこの中に含まれているのかどうか、もしあれでしたら説明を求めました。","respondent":"早津高齢福祉課長","answer":"いきいき脳の健康教室への対象としては、身体状況からいいますと、基本的には自立の方ということになりますけれども、この要支援の方ぐらいですと、通うことは可能だと思いますし、対象とすることができるんではないかというふうに考えてあります。","id":"exchange-021"},{"speaker":"本間委員","kind":"質問・要望","question":"そういう受け皿の中に引っ張り出していく、そういうことも大変必要なのではないかなという気づきがあったものですから、今お尋ねいたしました。どうかそういう人たちは、できるだけやっぱり後ろ向きにさせないような対応を今後ともご配慮していただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"１点なんですけど、今介護予防ということで、これからほんとうに介護にならない、要介護にならないようないろんな予防が大事だと思うんですけども、区として具体的な数値目標みたいなものを、もしかしたら立っているのかもしれないんですけど、それは立てていらっしゃるんか尋ねました。","respondent":"早津高齢福祉課長","answer":"要介護の認定の率というものを介護保険の事業計画に書いてあります。その発生率を下回るような形になれれば、介護予防事業としてかなり効果的かなと、私は数値としては思ってあります。","id":"exchange-023"},{"speaker":"武内委員","kind":"意見","question":"７人に１人にしようとか、そういうような流れがどうも出ているみたいなとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"南副委員長","kind":"質問","question":"簡単に１点だけ質問します。３カ所ですからね、始まったばっかりですから、この辺の考え方をちょっと改めて伺いたいと思います。","respondent":"早津高齢福祉課長","answer":"これが１カ所、新規で始めますこのマシーンを使った筋力向上トレーニングというのが３カ所で実施するということで、全体で７カ所を予定しております。比較的他の自治体は１点豪華主義というんでしょうか、品川区はこういう地域のバランスを考えて…","id":"exchange-025"},{"speaker":"南副委員長","kind":"質問・要望","question":"同時に、高齢者の筋力向上トレーニングという、これもこのことをさっきおっしゃったんですかね。そういうことをやっぱり重視をしていただきたいというふうに思っておりますので、これは私の要望ということで伺っていただければいいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/256749?Template=document&Id=3080#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":48881,"voices":114}},{"id":"h16-20040604-8","meetingId":"h16-cm06","date":"2004年6月4日","dateIso":"2004-06-04","committee":"建設委員会","time":"午後１時０３分～午後３時２７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"の１番目、幹部職員紹介","agenda":"の１番目、幹部職員紹介","exchanges":[{"speaker":"林（和）委員","kind":"質問","question":"お伺いしたいんですけれども、去年ですか不動前保管所ができたわけですけれども、その他についてをお聞きしたいと思います。それと、今度新設される東中延の公衆便所は、やっぱりポットン便所式になっているのかどうか、その２点。","respondent":"山口交通安全担当課長","answer":"自転車の関係につきましては、不動前駅の個別でよろしいでしょうか。","id":"exchange-001"},{"speaker":"林（和）委員","kind":"意見","question":"八潮北保管所と新しくできた不動前保管所は立地条件が違ってくるわけですけれども、返還状況といいますか、取りに来る状況の割合と、その後の残った部分をどういうふうに処理するのかということなんですとの意見を述べました。","respondent":"山口交通安全担当課長、松代道路公園課長、岩田管理工事課長","answer":"個別の返還率は１９ページの上段の表に出ていますが、内訳については手持ちにございませんので、後ほど調査して返答させていただきたいと思います。… ご指摘のとおり、平成１６年度からすべての公園にトイレットペーパーを設置しております。ご質問は、便所の中で震災対策用のポットン便所というか… 今年度予定しております東中延児童遊園のトイレにつきましては、震災対策用の耐用型の便所よりは規模が小さくなるかもしれませんので、現在検討中です。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"１２０ページを見て初めてわかったんですが、それを我々がたやすく見られるような小冊子といいますか、そういうものはあるのか。それと、また要綱、指針というのは、今、建設・土木においてどれぐらいあるものなのかお伺いしたいと思います。","respondent":"浜脇住環境整備課長、岩田管理工事課長","answer":"そんなに支障なく来ているものですから、これを条例化というところまで考えておりませんけれども、そういった状況でいます。あるいはこういうワンルームの指針がありますよ、葬祭場の環境指導がありますよということは言って… 細かい要綱、基準等につきましては、事業部のホームページに載せるようにしております。手づくりでやっておりますので、順次、部全体のものについてはすべてホームページでどなたでも見られるように整備してまいる予定です。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"例えば建築紛争に関して問題があったときに、私たちがもうちょっと手身近に調べられるような資料のつくり方というのはいかがなものでしょうか。一つの例ですけれども、あいうえお順に並べてみる、ジャンル別に並べてみるようなつくり方というのはお考えか尋ねました。","respondent":"岩田管理工事課長、松代道路公園課長","answer":"基準、条例等についての並び替えについては、それぞれの項目ごとに集約しています。例えば、開発に関するような条例のもの、それにぶら下がっている要綱、これが並んでわかるようになっております。 公衆便所が２カ所、公園便所が７カ所です。その際に、そういった対応をしているものです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこも含めた説明を義務づけるような条例を検討するというようなことが、決算特別委員会か何かで答弁であったような記憶をしているんですけれども、その辺はどういうふうな状況になっているのか説明を求めました。","respondent":"浜脇住環境整備課長","answer":"要するに壊した後に中高層建築物を建てる場合には、併せて解体の方法や工期といったものを一緒に説明しなさいということを規則で定めました。７月１日に予定しています。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、７月１日からは説明の中で、解体のことも説明が義務づけられるというふうに考えてよろしいんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"中高層建築物を建てる予定の方は、併せてやってくださいと。併せてやってくださいということで明記して、それはちゃんと条例の規則ですので、やらなければいけないというふうになりました。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"今の質問に対して、更地をどなたか業者がとりあえず買いましたと。今度、建築主は別の方に更地を売るというふうになると、今のは全く効果がないというふうな考え方になりますか。","respondent":"浜脇住環境整備課長","answer":"委員のおっしゃるとおり、更地でおいて、だれに売るかわからないという方については、私どものほうにはこういう相談には来ない。当然、私どものほうは開発指導と一緒になって指導するというふうになります。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"今日は大雑把な質問なので、今後も出るかと思うんですけれども、できればその辺を何とか改善していただくと、指導もそうなんですけれども、壊す場合に指導を徹底していただくような規則があるといいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"三上委員","kind":"質問","question":"4)の部分について、現状はどんな感じなんでしょうか、地元は全く知らない状況にあると思っているんです。1)と3)というのは身近なところにあるものですから、それがもうすぐいろんな形で、状況がおわかりだったら説明を求めました。","respondent":"藤田都市計画課長","answer":"１点目の情報をつかみ報告してほしいという件ですけれども、機会をとらえながらきちんと報告してまいりたいと思ってあります。そういった中で、まだ決まっていないというふうに聞いてありますので、今後情報を取りながらご報告してまいりたいというふうに考えてあります。","id":"exchange-009"},{"speaker":"三上委員","kind":"質問・要望","question":"計画路線としてはこういうふうにあるんだと、住民の皆さんにお知らせするということをきめ細かくやっていただきたいということを東京都に強く。仮にそういうようなことがあれば、何かいろいろな機会を通して、住民の皆さんにお伝えしていただくということをお願いしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"高星委員","kind":"質問","question":"ここでは事務事業概要だから、環境問題も含めて加筆する必要があるんじゃないかなというふうに思ったので、そのことを一つお聞きしたいということ。都市形成の軸の品川区にとって都合がいい仕事を進めていくのか、基本的な考え方をちょっとお聞きしたいなというふうに思ったのでお願いします。","respondent":"上野都市開発課長、藤田都市計画課長、中谷まちづくり事業部長","answer":"私から１点目の、９０ページの旧国鉄大井工場地区整備構想に関することについてお答えいたします。今のところは、これまでの経緯等を踏まえて… 東京都が進めている事業ということで、東京都の見解をそのまま書かせていただいた関係で、このような記載になっております。… 私どもの姿勢としては、都の事業であるけれども、区としては都は十分に住民に対して説明を行うべきだと。これは区民委員会の所管ですが…","id":"exchange-011"},{"speaker":"高星委員","kind":"質問","question":"品川区長、地元自治体の長として、最大限あそこに書き表しているんだろうというふうに思います。環境とか、配慮とか一言欲しかったというふうに思ったものですから、ちょっと言わせてもらいました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"}]},{"id":"topic-02","title":"の羽田空港再拡張後の飛行ルート（修正案）","agenda":"の羽田空港再拡張後の飛行ルート（修正案）","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"１フィートは地上からすると何kmぐらいですか。それと、役所の窓から見える飛行ルートというのは、大体何フィートぐらいというか何kmなのか。","respondent":"藤田都市計画課長","answer":"おおむね１フィート３３cmぐらいだったかと思います。正確な数値を確認しまして、お知らせしたいと思います。","id":"exchange-013"},{"speaker":"大沢委員","kind":"質問","question":"直接これとは関係ないんですが、この階から窓に向かって、先のほうによく見える飛行機が見えるんですけれども、飛行の専門家の方ではないので、こんなことも言っていると申し訳ないんですけれども、大体あれはどれぐらいの高さか尋ねました。","respondent":"藤田都市計画課長","answer":"今、八潮の上空ではないんですけれども、八潮方面に見えるやつですけれども、おおむね２,０００から３,０００フィートで入っていく。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"現在の状況がそうだということなんですか、それとも初めの案がそうだということなんですか、そこのところを教えていただきたい。２８.５万回が４０.７万回ということで１２.２万回増えるわけですけれども、Ｂ、その辺のところも教えてほしいと求めました。","respondent":"藤田都市計画課長","answer":"それが今回の修正案では、５,０００フィートの３％という形での提示になってあります。それと、増えた分は必ずしも全部新たな滑走路で運行するということではなくて、全体の振り分けの中でそれだけ増えてくるということになってあります。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その関係する地域に対しては、今まではなかったところが３％５,０００フィートが新たに出てくるというふうなことで考えられるでしょうか。そういうことからすると、現在は騒音だとかそういうことは多少とも増えてしまうということになるのか、その辺について教えてほしいと求めました。","respondent":"藤田都市計画課長","answer":"ただ、環境基準等もありますけれども、そういった中では数値としては全くあらわれてこないような形になります。騒音がゼロかと言われれば、そうではございませんけれども、環境基準についてはクリアした形のものになってあります。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこに住んでいる人にとってどうなのかというのは、どの程度なのか、その辺の環境基準というのがどのぐらいなのか。それと、実際にここに生活している人にとって、どれぐらいの影響になるのかというあたりがよくわからないので教えていただきたいんですけれども。","respondent":"藤田都市計画課長","answer":"４,０００フィートで飛んでいる場合については、それが今回、５,０００フィートに上がることで６６デシベル程度になるというふうに聞いてあります。騒音にすれば大分違うというような形で聞いてあります。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それが今度新たにプラスになるということで、６６デシベルというのがどの程度なのかというのが、具体的なところがここにはないんですね。７０だと「騒々しい事務所の中、６０だと「普通の会話の声、そういうのはどういう状況になるのか説明を求めました。","respondent":"藤田都市計画課長","answer":"今回、今後の騒音の低減についてはいろいろ考えながら進めていくというふうに聞いておりますけれども、そういった作業を進める中で。最新の技術あるいは最新の管制システムといったものを使いながら…","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"騒音というのは、本当に日常生活の中で大変気になることですので、品川区としてもそういう方向で頑張ってほしいと求めましたけれども、今後も引き続き。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"三村委員","kind":"質問","question":"今の質問に関連してなんですけれども、６０デシベル程度ですと、時間帯によって感じ方が違うと思うんですね。３％というのが時間帯の縛りがあるのか、その辺についてお願いします。","respondent":"藤田都市計画課長","answer":"資料の７ページのところですけれども、細かい説明をしなかったので、申し訳ないと思います。そういった形で、１時間に１５機以内ということで、早朝の７時、８時台の時間帯に、この辺については運用したいという形で聞いてあります。","id":"exchange-020"},{"speaker":"三村委員","kind":"意見","question":"この時間帯ですと、日中でしたら気にならない程度の騒音でも、大分気になるんじゃないかということもありますので、地元への説明のときに、この辺についても対応をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"高星委員","kind":"質問","question":"平成１５年から八潮を除いて各学校に二重窓にしたときの残骸が残っていますね、かつてのボイラーが。こういった話のときに、そういう駆け引きというのはできないんですか、撤去費用を含めて、どうなんか尋ねました。","respondent":"岩野まちづくり事業部次長","answer":"そういうことを国土交通省との間で何らかの形で取り引きができないのかというご質問であると思います。今回についても、もしそういったような機会があれば、そういったような話をしていきたいというふうに考えてあります。","id":"exchange-022"},{"speaker":"高星委員","kind":"意見","question":"だから、笑い事じゃなくて、もっとちゃんとやってもらいたい。そうしないと、いつまで経ってもあの問題は解決しないとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この３％というのは、１日に何便ぐらいになるんか尋ねました。","respondent":"藤田都市計画課長","answer":"午前７時台、８時台がそういった時間帯になるであろうというふうに、単純に言うと仮に１５機であれば１５かける２と。８時台の２時間ということで、掛け算すると３０という数値が一つの目安としては出てきますけれども、あくまでも一つの目安ということでお話しします。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"まだよくわからないんですけれども、７時台、８時台に３０機、ここのルートで飛ぶということになるということなんですか。神奈川・都心北上ルートということは。","respondent":"藤田都市計画課長","answer":"そのようなことになります。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"３％とはいえ、そこのところでこんな形になると、これはかなりの影響になってくるんじゃないかなと。地域の人にとってみれば、今よりもかなり騒音が出てくるんじゃないかなと危惧がされるんですけれども、その辺のところではどうでしょうとの意見を述べました。","respondent":"藤田都市計画課長","answer":"現段階での想定のことですので、そうした中で、住民説明もきちんとする中で行ってまいりたいというふうに考えてあります。","id":"exchange-026"},{"speaker":"大沢委員","kind":"質問・要望","question":"品川区、具体的にどういうふうに対処していったらいいのか、委員会の材料にしていただければよろしいんじゃないかと思います。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"三村委員","kind":"質問・要望","question":"品川区はこんなに厳しく対応するんだということを見せるためにも、条例化を検討していただきたいなと。もとになるデータの要綱がどうなっているのか、条例がどうなっているのかというのを、ぜひ資料として私たちにも提示してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私もこの委員会は初めてなんですけれども、今日、事務事業概要の説明をいただいたばかりで、この委員会をどうしていくかというのは、自分の中でもあまり考えてきていない部分もありますので、次回にこういう機会を取っていただくということはできないかなと思うんですけれども、いかがか尋ねました。","respondent":"伊藤委員長","answer":"１３回、１４回と限られていますので、この場ではお話することはできないんですけれども。具体的については、制限がありますということで、ご理解いただければと思います。","id":"exchange-029"},{"speaker":"高星委員","kind":"意見","question":"いろいろとやってくる中で、どうも腑に落ちないというか、納得できない課題があるんだけれども、その課題を言う前に最初に知りたいんですけれども、品川区の用途地域の見直しをいつになるのか、最初に聞いておきたいとの意見を述べました。","respondent":"藤田都市計画課長","answer":"先ほどもちょっとお話しさせていただきましたが、今月末には東京都のほうで取りまとめが終わりまして告示される予定です。具体的には、６月２４日になるというふうに聞いてあります。","id":"exchange-030"},{"speaker":"高星委員","kind":"質問","question":"そうすると、もう準備立ては全部終わっているということですか。中延地域になるんでしょうか、特別に制度を引用しながら、高層をつくる中で住環境をよくしていこうというイメージの誘導型のあれもわかる。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"その辺も建設委員会で、１万m2以上に関してもある程度指導力を発揮できるような一つの見解を出せないものだろうか。その辺は何か見解を出せたらいいんじゃないかなと思うんですけれども、一応、意見として言わせていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、速やかに現地の視察なり、いろんな形で委員会を開催するということがあってもいいのかな。地べたを必ず必要とする委員会であるというところで、その都度の対応ということを正副委員長にお願いできないかと、お願いしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"林（和）委員","kind":"質問・要望","question":"今回もそれに従いまして、申し合わせをしてほしいと求めましたし、前期のときには請願・陳情が４件ありました。２件は承認をしたんですけれども、残念ながら２件は継続となって、これも近々のうちに結論を出していただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/107143?Template=document&Id=3786#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":41040,"voices":130}},{"id":"h16-20040604-9","meetingId":"h16-cm06","date":"2004年6月4日","dateIso":"2004-06-04","committee":"文教委員会","time":"午後１時０４分～午後３時３８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"の２、事務事業概要","agenda":"の２、事務事業概要","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"ちょっと聞き漏らしたというか、生涯学習課の、４９ページのところで、平成１５年度限りで外しましたとか、やめましたとかという説明があったんだけれども、事業名は何というんか尋ねました。","respondent":"上川内生涯学習課長","answer":"学校情報誌です。ＰＴＡが自分たちの視点で学校の情報誌をつくるという。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"１０ページに出てくる、プラン２１の組織ですけれども、部会があるわけですね。組織としては、上の準備委員会というのは全く違う人が組織をしていて、この図はそうやって運営するというふうに考えればいいんか尋ねました。","respondent":"富田教育改革担当課長","answer":"例えば小中一貫校の予定校となっております小学校２校、また検討部会の中でも幾つかの部会に係わるというような内容になってあります。こちらの準備委員会と、下の検討部会での組織内容が準備委員会のメンバーにもかなり分かるような内容というふうになってあります。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"平成１６年度から全区で小中一貫教育、この準備委員会というものが、内容を決めていくというふうに理解をしていいのか。素案づくりというか、そういうのがこの準備委員会でつくられるというふうに理解をしていいんか尋ねました。","respondent":"富田教育改革担当課長","answer":"それぞれの検討部会、下部組織でもって検討をした内容についての報告を受け、検討をするという役割を持っております。その内容を一部修正をしながら、プラン２１推進委員会でも検討をいただき、最終決定は教育委員会の場でということになってあります。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"意見","question":"どうもよくわからないんだけれども、上にプラン２１推進委員会というのがあって、プラン２１の全体を進めていくわけですよね。ここに書いてあるのを順番に見ていくと、ほとんど同じ人たちのように、屋上屋でないのかなとの意見を述べました。","respondent":"富田教育改革担当課長","answer":"プラン２１推進委員会と小中一貫校、小中一貫教育準備委員会のメンバーの中で重複しておりますのは教育長１人でございまして、それぞれの団体から別の方々を推薦いただいて決定をしております。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"ただ、違う人が出てきているからといって、違う委員会だというふうな位置づけにならないじゃないですか。両方とも校長会の代表なんだから。","respondent":"富田教育改革担当課長","answer":"特色ある学校づくりを含めて検討をしてまいりましたが、平成１４年度から小中一貫校の開設準備という大変大きな課題が入ってまいりました。小中一貫校の準備委員会で検討をした内容がすべてプラン２１の推進委員会にその都度かけていくということではなくて…","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"途中の準備委員会というのが、何か、小中一貫のための言い訳の場所で、小中一貫というのは、本当はプラン２１の中の大きい施策なわけじゃないですか。シティバンクのグループにやってもらうというふうに入ってくるんですか、今この組織はいろいろな組織が日本中にあるんですね。","respondent":"中島指導課長","answer":"こちらの中学校版の経済体験学習の、私ども今のコーディネートを共にやっているところは、ＪＡと申しまして、ジュニア・アチーブメントという、スチューデント・シティでプログラムを提供していただいたＮＰＯと同じものです。","id":"exchange-006"},{"speaker":"大西委員","kind":"質問","question":"支払いが１カ月でも構わない、学校の裁量に任せているんでしょうか、それとも区のほうからの指導として変わるのかどうかということ。委員長にお尋ねしたいんですけれども、こういう質問をいっぱい言っておってもいいんか尋ねました。","respondent":"中島委員長","answer":"先ほども申しましたように、今日は所管課から説明を受ける日ですので、簡潔にいきたいと思います。","id":"exchange-007"},{"speaker":"大西委員","kind":"質問","question":"給食費の件ですが、これは以前は一括があったというふうに承知しているんですけれども、その制度をなくしたということか尋ねました。","respondent":"谷田部学務課長","answer":"この件につきまして、学校によって対応がまちまちだった部分があったというふうに聞いてあります。逆にまた高低差が出てくるという観点から、１０回にそれぞれ分けて、なるべく１０回に分けて引き落としていただきたいというのが基本的な考え方です。","id":"exchange-008"},{"speaker":"大西委員","kind":"質問","question":"分かりました。２９ページの多子家庭給食費補助というのがありますが、具体的に幾らの所得の方が対象外になるかというのはお分かりになりますか尋ねました。","respondent":"谷田部学務課長","answer":"いわゆる５人世帯で、年収といたしましては大体６５０万円ぐらいの方が、所得割が１４万円以下になるというふうに計算しています。これは正確でないので、一人歩きしないように、あくまでも目安の金額というふうにご理解いただきたいと思います。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"３月末までのは、１日あたりの配置の数を教えていただきたいのと、おそらく配置基準も多少変わったのかなと思っています。４５０人生徒が増えると、６人増やしますとか、配置基準の新旧を教えてほしいと求めました。","respondent":"富田教育改革担当課長","answer":"その想定が１００名までは１日あたり５人となるように、３０人を超すごとに１人ずつ加配をしていきますよというところをお答えをしてきておりました。平日の１日あたりということで、５名から９名となるように配置をしておりまして…","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"２人増えたり、資料として出すべきじゃないのかなと考えていますけれども、今後出していく予定があるのかどうか伺いたいと思います。何度か現地を視察されたと伺っておりますけれども、去年の９月以降、対応についても報告をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜこれに載っていないのか僕は不思議なんですけれども、今ある職員の数ですから、きちんと提出を求めるべきではないのかなと思います。教育委員会が出向いて説明していると伺っていますけれども、どんな質問や要望がそこで寄せられているのかなというのを教えてほしいと求めました。","respondent":"中島指導課長","answer":"小中一貫教育に係わっての説明会ということで、今、山中小学校、原小学校の２校で５月から６月にかけまして実施をしてきております。ただ、今回説明会を開いておりまして…","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"私が出席した４月２７日の説明会の中で、手元にデータがなくて、後日ご連絡いたしますというところが幾つかあったと思うんです。例えば伊藤中学校の１人あたりの校庭数、後日どのように保護者にきちんと説明をしたのか、その経過を教えてほしいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"その場合に答えられなかった質問を後日どういう対応を行ったのか教えてほしいと思います。〔「個別なことに入らないように教えなきゃ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"中塚委員の質問中に、物によっては個別の問題に入らざるを得ないし、すべきところもあると思うんです。今の発言については、そこで一旦切って、答弁だけしてもらうということで、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"沢田委員","kind":"質問","question":"概要ですから、そこではフレキシブルに時間があるときには考えるべきだというふうに、これは私の意見としたい。せっかくの委員会なのでお尋ねしたいのは、不安を与えているわけですけれども、今日の概要説明でどこに触れるかということですが……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"沢田委員","kind":"質問","question":"では、それはその他で聞きます。要点を絞って、それだけでいいですから、教えてもらえますか。","respondent":"上川内生涯学習課長","answer":"それから、変更点につきまして、ギャラリー席が増えます。それから新しいところではヘルストレーニングルームがトレーニングルームとなりまして、お風呂とサウナがなくなります。","id":"exchange-017"},{"speaker":"沢田委員","kind":"質問","question":"６月に総合体育館の移転の問題で全体説明会をセットされているということですけれども、本体工事は始まっていますよね。なぜ手順が後になって、どうもこういうことが多過ぎるのではないのかなという気がするんですけれども、その辺はいかがか尋ねました。","respondent":"上川内生涯学習課長","answer":"６月１８日に利用者の説明会を予定しておりますが、移転をしますということと、聞かれたときにはお答えは窓口でしております。それから、バーベル等につきましては、私どものほうにも利用者の方からお話があって、お話はしています。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"体育館全体に係わる問題ですから、議会にも詳細を説明をしてほしいということと、利用者に言われて最近やったんでしょう。少なくとも地方自治であるならば前提条件にしてほしいと思うし、まして教育の分野というのは、意見だけ述べておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つか教えていただきたいんですが、それとの兼ね合いをどうするのか、それがどこに入るのか教えていただきたい。そこら辺がここに見込まれておりませんので、それをどういうふうな考え方を持って進められようとしているのか、まずその辺をお聞きしたいと思います。","respondent":"市川庶務課長、富田教育改革担当課長","answer":"昨年実施いたしました１３校のうち、補強工事に向けての実施設計ですが、実施することにいたしました。この補強設計につきましても、今後基本的には向こう３年間にわたって計画事業として随時行っていくという予定を組んです。 できる限り保護者の皆様方にも、区民の皆様方にも検討の状況、結果等々についてお知らせをしてまいりたいというふうに思っております。例えば学校選択の折ですとか…","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"ただ、どういうところを今やっているんですよというところは必要かなというふうに思いますので、ぜひそういう方向性でお願いしたいと思います。４０人ぎりぎりで配置されているという場合、どういう形で加配という、そこら辺の報告をお聞きしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"藤田委員","kind":"質問","question":"１点だけご質問いたします。これは２泊３日で行かれていると思いますけれども、この２泊３日の１コマは現状何校行っているのか、これを教えてもらいたいと思います。","respondent":"谷田部学務課長","answer":"５月から９月までの間に実施しなければいけませんので、月曜から水曜日、大体２校から３校が同時期に同宿してやるという時期があります。夏季施設のほうもやっぱり同じでして、２校から３校、地区ごとにまとまって同じ期間にという状況になってあります。","id":"exchange-022"},{"speaker":"藤田委員","kind":"質問","question":"区民の人たちが、５月から９月は非常に季節のいい時期に、これからほかの保養施設に行かなければ、どうしても日光に対しての注目が集まってくる。廃止をしていくという方向性であるわけですから、また、その辺だけちょっと伺っておきます。","respondent":"谷田部学務課長","answer":"何かと２校、３校同宿で行い、空いた期間については区民の方にご利用していただくと。多いところは３校一緒に行くということで、これまでも努力してまいりましたし、今後もそのように努力していきたいというふうに思ってあります。","id":"exchange-023"},{"speaker":"藤田委員","kind":"質問・要望","question":"児童の数が減っているわけですから、３校ないし４校でも工夫をして、そうすれば一般区民の人たちがあそこを利用できるような門戸を広げる。教育委員会として十分検討していただきたいと、要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"沢田委員","kind":"質問","question":"人権尊重教育との兼ね合いであそこで聞けると思ったんですが、その他のほうでいいと思うので、改めて聞かせてもらいたいんです。まだ全容が見えていないですから、今の段階でばたばたするのはどうかと思いますけれども、その基本的な考え方を教えてほしいんです。","respondent":"中島指導課長","answer":"メールを使う上でのマナーということで、相手のことを考えるという視点を、すでに平成１２年度にこれを作成した時点から織り込んです。直近にあります６月の教育会の情報教育部会等でも具体的に指導主事のほうから課題として投げかけていきたいというふうに考えているところです。","id":"exchange-025"},{"speaker":"沢田委員","kind":"質問・要望","question":"これはやっぱり重視をして、早速取り組んだというのはよく分かりましたけれども、ぜひ教訓を引き出していただきたいなと思います。ぜひそこらをよろしくお願いしたいと、要望して、終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"西本委員","kind":"確認","question":"関連して幾つか確認をしたいんですが、インターネットを使ったことがあるというのは１００％に近いんじゃないかなというふうに思います。先ほど平成１２年度にマニュアルができたと言いましても、教師たちはどういう実態なのか、そこら辺はいかがか尋ねました。","respondent":"中島指導課長","answer":"その中で、また、そこに入るセキュリティソフト等も更新の流れの中で新しいリース等にも対応できるような形をとってあります。学校教育で実施して育てていける部分もありますけれども、地域、関係機関が連携していくというような要素も多くあろうかと思います。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"そこら辺どういう弊害があるのかというのは、これから講習などをするときには、ぜひ指導をしていただきたいなというふうに思っています。そういうのは子どもも同じ形で指導をしていくという視点は必要じゃないかなと思いますので、そこら辺を今後の研修に役立ててほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"中島委員長","kind":"提案","question":"ないようですので、今後の委員会運営について、私のほうからご提案をさせてほしいと求めました。できる限り審査調査し、委員会の活性化を図っていきたいと考えておりますが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/544596?Template=document&Id=4506#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":46098,"voices":98}},{"id":"h16-20040604-5","meetingId":"h16-cm06","date":"2004年6月4日","dateIso":"2004-06-04","committee":"総務委員会","time":"午後１時０４分～午後２時５３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"１番目の幹部職員の紹介","agenda":"１番目の幹部職員の紹介","exchanges":[{"speaker":"堺副委員長","kind":"意見","question":"副委員長の公明党に所属をいたしております堺です。どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"土井委員","kind":"意見","question":"品川区民連合の土井です。どうぞよろしくお願い申し上げますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"}]},{"id":"topic-02","title":"番目の事務事業概要","agenda":"番目の事務事業概要","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"実際にちょっとどういう体制でどういうふうな取り組みといいますか、決めていないのか、そこら辺をちょっとお聞かせ願えればと思いますとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"では、法律相談についてでよろしゅうありますか。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"もしかしたら時間が短いのかどうかわからないんですけれども、ちょっとそういう感じが多いかなと思うんですよね。ですから、もうちょっと違うのかなというふうな感じもしているんですけれども、ちょっと工夫していただければなと。","respondent":"中川原広報広聴課長","answer":"法律内容でない相談も弁護士に相談したいという希望者の方も多うございまして、区民相談室でも予備相談という形で電話受付のときに少し整理させていただきながら、ほんとうに必要な方に法律相談を必要な時間でとれるような体制をとってまいりたいと考えています。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"意見","question":"このテーマというのはどういうふうに決めるのか、そういうアンケートのテーマというのはどういうふうに決めているとか、考えているかということをちょっとお聞かせ願えればとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"項目の内容については２種類ございまして、区民がそれについてどういうふうに考えていらっしゃるかというように、そういった役割が二つあります。集計等を皆さんで今度調査内容をきちんとわかりやすく整理するときのことも考えまして、そこら辺は調査しているものです。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今の区のやっている施策に関するそういう満足度というだけではなくて、実際に区民がどういうふうに思っているかというのをつぶさにつかむといいますか、そういうところを工夫していただきたいなというふうに思っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"意見","question":"4)の同和生活相談のところで、どういうふうな体制で処理あるいは相談をされているのか、そこのところをちょっと。実態のところを改めてうかがっておきたいと思いますとの意見を述べました。","respondent":"武内人権啓発課長","answer":"同和生活相談につきましては、年間を通して３００件ほどというように私は聞いております。は東京都の人権部と連携をとりながら、対応等の相談の中、そういうふうな東京都と連携しながら啓発を行うなどのてこ入れをやっております。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問・要望","question":"同和生活相談のほうの３００件というのは、今、相談員というのは何名なんですか。１名じゃなかったかと思うんですけれども、五年ぐらいの相談の件数を、わかったらお知らせいただきたい。","respondent":"須藤委員長、武内人権啓発課長","answer":"宮崎委員、今日は事務事業概要なので、過去云々というのはまたちょっと大変になってくると思うんで、その辺のところで、わかる範囲でお答えいただければと思います。 平成１３年度につきましては２７２件、平成１４年度につきましては２６９件、約３００件ぐらいというふうに聞いております。それで、相談員につきましては以前２名いまして、現在は１名で対応しております。","id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどの差別事象の問題というのは、今の説明の範囲ですと、ここのところでやる必要があるのかどうなのかというのが非常に疑問なんですよね。なぜここでやるのかというのが見えないんですけれども、そういうところというのは、ご説明できるんか尋ねました。","respondent":"武内人権啓発課長、本間総務部長","answer":"現実に、刑事告訴している方もいましてというふうに聞いております。 差別事象が起きているのかというご質問に対しましては、区内でこういう具体的な差別事象が起きていますというふうにお答えしたわけです。これはきちんとした対応をやっていきますし、今後…","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、これを、いわゆる行政改革ということをずっとやっている中では、これはしっかりと見直していくべき内容だと思います。例えば人権の相談というところもあるわけですから、私はこれはいつまでも置いておくべきじゃないということを指摘しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"同じく７ページなんですけれども、男女共同参画のところで、男女平等推進フォーラムハートフルしながわ２００４、１１月２７日、昨年のことでは結構物議を醸したんですけれども、今年度１１月２７日に計画されているのはどんなことを取り上げるんか尋ねました。","respondent":"武内人権啓発課長","answer":"現在、実行委員会が組織されておりまして、３回ほど実施されております。子どもの虐待等、また女性の仕事の支援などの、そういうテーマで今後検討していくという段階になっているところです。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"１点だけ教えていただきたいんですが、言葉のことで教えてください。考え方は大体の部分はわかるんですけど、言い切っちゃっている部分を、どうお考えなのかなというところを。","respondent":"本間総務部長","answer":"表現はちょっとあれですが、先ほどご説明させていただきましたとおり、総務部だけでこの側面から援助しているとは決して考えてございません。それぞれの持ち分で事業部制が円滑に推進していくように側面から援助していくという考えでおりますので、よろしくお願いいたします。","id":"exchange-012"},{"speaker":"石田委員","kind":"質問・要望","question":"このまくらの部分にぜひ書いていただきたいなと思っておりまして、そこの部分も含めて、これは要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"本田委員","kind":"質問・要望","question":"予算特別委員会でもいろんな角度から議論をされてきたものですが、同時に多様な行政展開も進められている、いかなければならない。そして新たにそういう考え方で、必要になってきているという点についてはどういう扱いになっているのか、ちょっと教えていただきたいと思うんですが。","respondent":"桑村人事課長","answer":"まさにその後検討して条例化しなければ、とても採用できないわけですけれども、それと非常勤の関係をどう整理していくのか。その補助的な業務で非常勤があるみたいな考え方をしておりますけれども、少し調査する、あるいは今年の大きな課題だというふうに検討しています。","id":"exchange-014"},{"speaker":"本田委員","kind":"意見","question":"それで、今、法律的な扱いでは、採用、雇用は地方公務員法を適用して、労働条件などについては労働基準法を適用する。扱いが進んでいるところもあれば、２３区はそうでもないようですけれども、もう一度お尋ねしておきたいと思いますとの意見を述べました。","respondent":"桑村人事課長","answer":"それについて、仕事の仕方というんでしょうか、それをこの品川区の中で考えていくというのが一つの大きな流れだというのは十分認識しています。その意味で、いわゆる地方公務員法自体を改正して短時間職員等が出てくる流れを踏まえて…","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"組織編成、行政の統合性、総務部のほうでは各事業部が円滑に職務が遂行できるようにサービススタッフ機能を果たすというふうに書いている。ちょっとそこら辺のところが、企画部と総務部のところの考え方等、少しよくわからないんですけれども。","respondent":"本間総務部長、須藤委員長","answer":"それをそれぞれ二つの部でいろいろ切り分けております。この辺はきちんともうちょっと整理して、よりわかりやすいような表現に変えさせていただきたいと考えておりますので、よろしくお願いいたします。 ほかにご質疑ありませんか。すべての事務事業概要の説明を終了いたします。","id":"exchange-016"}]},{"id":"topic-03","title":"平成１６年７月執行想定の参議院議員選挙執行要領","agenda":"平成１６年７月執行想定の参議院議員選挙執行要領","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"教えていただきたいことは、投票所のことです。第二日野小学校ですと場所が変わっているわけですから、計画はもうできていらっしゃるのでしょうか、その点を説明を求めました。","respondent":"野田口選挙管理委員会事務局長","answer":"投票所のところで説明しなくちゃいけなかったんですけれども、台場小学校につきましては、現在の体育館を使います。これは仮校舎のほうに学校が移ってありますので、その仮校舎のほうの多目的広場といいますか、その部屋を活用して行うです。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問","question":"幼稚園から校舎の廊下をずっと入って投票してもらうということなんでしょうから、それはわかりました。ここが投票所ですという看板を幾つかいろいろなところに、前の第二日野小学校のあたりから立てるとか、そういう計画はおありなのかどうかを。","respondent":"野田口選挙管理委員会事務局長","answer":"選挙人につきましては、入場整理券を配付します。案内図とか、案内人も置いて、そういった部分の投票所が隣に移ったよということについてはＰＲしていきたいと考えています。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問","question":"それで、同時に不在者投票も残す。残るというのは、要するに不在者投票でなければできない人もまだいますよという意味なのか、ちょっと教えてほしいと求めました。","respondent":"野田口選挙管理委員会事務局長","answer":"その方は大体区内で１００名ぐらいと想定していますけれども、その方だけは投票する時点で選挙権がございませんので、従前の不在者投票で行うです。極めて対象者はレアケースです。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問","question":"そうすると、そこの１００名プラス公民権云々の方は、お知らせがあるんでしょうか。当日できないんだから、不在者投票でやるしかないよという、自分はそういう人間なんだというのは、何かわかる方法があると。","respondent":"野田口選挙管理委員会事務局長","answer":"それで、本人が投票に来たときに期日前投票か不在者投票かに該当するかというのは、入場整理券ではわかりません。受け付けた時点で、そのときにそういったきめ細かな措置をさせていただきたい、そういうふうに思ってあります。","id":"exchange-020"},{"speaker":"若林委員","kind":"質問","question":"２４日公示ですから、逆に不在者投票の期間が１週間程度短くなるということで、投票の機会が短くなるというようなとらえ方はございませんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"その投票できる期間ですけれども、これにつきましては、これまでの期間と変更はございません。これは従前と同じです。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"今ので、不在者投票は今みたいなレアケースということなんですけれども、病院に入っている人だとか、あれはいわゆる期日前投票になるんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"ここでは、地域センターで行う不在者投票について説明したんですけれども、地域センターと本庁で行う不在者投票が期日前投票に変わりましたよと。そのほかは変わってございません。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"確認","question":"今のところで大分話がどうも進むんですけれども、いずれにしても、今日ちょっと初めての話なので、もうちょっと議論してからもう１回ですね、確認というか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/406359?Template=document&Id=1654#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":35722,"voices":114}},{"id":"h16-20040607-11","meetingId":"h16-cm06","date":"2004年6月7日","dateIso":"2004-06-07","committee":"自治制度特別委員会","time":"午後１時０４分～午後３時１１分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"の１番目、幹部職員の紹介","agenda":"の１番目、幹部職員の紹介","exchanges":[{"speaker":"本間副委員長","kind":"意見","question":"委員長を補佐し、スムーズな審議運営に力を尽くして頑張っていきたいと思います。どうぞとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"そのことをもって東京都のほうが逆に違う方向性なり何なりと議論付けられてくる可能性はないんでしょうかという心配がちょっとあるんだけれども。平成１８年度にできて、そのあたりは一番元の２３区の清掃一部事務組合の附則を動かしてしまうことによって、そのあたりはいかがか尋ねました。","respondent":"市岡企画財政課長、中山清掃リサイクル課長","answer":"これらも平成１７年度までには決着を付けなければなりませんので、この宿題の解決すべき締め切り期限が平成１７年度中だということは、結論を出す形で詰めていくということになろうかと思います。 先ほど規約の中でご説明を飛ばしてしまったんですが、規約の第４条の中に、本部は四谷にあるわけです。当分の間清掃一部事務組合は継続することが望ましいと考えるが、基本的な方向性が検討というふうになっておりますから…","id":"exchange-002"},{"speaker":"須藤委員","kind":"質問","question":"５２％プラス、その当時で５の数字があるから、平成１２年度までには持っていけないからというようなお話でこられたと思うんです。平成１７年度を目途というようなことは切り離して考えていかざるを得ない考え方なのかなというように思うんですけれども、いかがか尋ねました。","respondent":"市岡企画財政課長","answer":"この後の都区検討会の両者で確認した設置要綱にも明確に書いてありますので、繰り返しになりますけれども、東京都も認識している課題です。軸足の点が少し変わるかもしれませんが、宿題を出す期限と、内容の基本的なところは変わっていないということでよろしいかと思います。","id":"exchange-003"},{"speaker":"築舘委員","kind":"質問","question":"助役会のメンバーというのはどういうメンバーで、第２分科会の報告をしたときのメンバーと、検討部会のメンバーが同じなのかどうかということ。想像ができるかどうかということ、この辺をお聞きしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"５ページ以降に第２分科会の検討の方向性について基本的な考え方、中間処理のあり方について、さまざまなキーワード的なものが示されております。頻繁に検討を重ねているというふうに伺っておりますが、現在我々が認識している情報というのは…","id":"exchange-004"},{"speaker":"築舘委員","kind":"質問・要望","question":"平成１２年度の原点に戻っての、区長会、助役会も考えていただければというふうに思っています。自治会館においては変わらないということになってしまっては困るわけで、そこのところは強く要望をしていきたいというふうに思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"高星委員","kind":"質問","question":"だから、その辺のところをどういうふうに思っているのか、ちゃんと聞きたい。そうしないと、そこの中で全体で各会派から上がってきている委員の中でしっかりとした危機意識を各会派に持ち帰る必要もあるわけですから。","respondent":"市岡企画財政課長","answer":"私も実際に都区検討会にずっと出てまいりましたけれども、こういう認識でいましたし、平成１２年度以降のいろいろな状況の変化に対して。国も骨太の方針を、今のいろいろな新しい議論にきちんと対応できるような前向きの積極的な議論をする中で…","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"改めてこれについて説明を伺いたいんですが、具体的にどういうことを示して捉えればいいのかということを伺って、あと関連して伺いたいと考えています。","respondent":"中山清掃リサイクル課長","answer":"地元住民との対応、アンバランスの事例として検討をしていくべきであるというのが、この段階での事例です。これにとらわれずいろいろと検討をされているかと思いますけれども、下命する段階でこういうものが例示されているということです。","id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"ごみを燃やさないために、資源化をして、分別収集をしていくということを一緒にやっていかないといけないというふうに思うんです。確かに平成１２年当時の見解、私は、今日のこの到達を品川区としてはどういうふうに見ていられるのかなというのを伺いたいんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"清掃一部事務組合のこの問題については、そこも非常に係わるので、改めて聞かせていただきたいということで意見を言ったんですけれども、この委員会の目的の範囲の中で結構ですから、考え方をお聞かせほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"アンバランスの是正でありというのが検討をされているわけですから、これはまた別の次元で検討をされていくのかなというふうに思っております。いずれにしても、ごみの減量等というものも、効率化という中には視野には入れている一つの要因だというふうに考えております。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"基本的に何でも燃やして処理するという考え方から脱却していかない限り将来にわたって禍根を残すような結果になってしまいがちな危険があるというふ…あえて質問もさせていただいたんですが、しかるべき担当のところで、教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"しかし、分別収集も含めた清掃事業も考えて議論をしないと、全然違うというふうには私は思わないんですよ。清掃事業のところの関係の清掃一部事務組合ですから、整理はして質問はしますけれども、意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"最終的なまとめを対外的にぶつけていく相手がどこなのかという確認を含めて、いわゆる意思決定過程ということをちょっとお伺いしたいんです。区長会にそれだけの権能があるのかどうかということも踏まえて、大変大きな問題になってしまいますが、その点をまずお聞かせほしいと求めました。","respondent":"岩崎環境清掃事業部長","answer":"執行最終責任者が２３人集まって、それに基づいて助役以下それぞれの会議体で検討をしているということで、エネルギーはまだかけているわけです。私も全貌を知っているわけではございませんので、ご説明できませんが、これは凄く重いものです。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"平成１２年２月に特別区協議会の総会で自治会館の実施計画が承認されたということでお伺いしたわけですが、区長会総会で、区議会報告をやる。５０年の計画の中で、それが出たときに、このことに対する意見がどういうことがあったのかをお聞かせほしいと求めました。","respondent":"宮地総務課長","answer":"平成１２年の実施計画から始まりまして、実施設計と、了承をされたです。５０年間の計画ですが、実施計画の段階から途中で公共団体の面積の移動、例えば５０年間ずっとこのスペースを守っていくということではございません。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"要望といいますか、自治会館のことも、区長会がメインの意思決定機関であるということで、議長会に対しては報告があった。このことも含めて、ぜひ当委員会で１年間しっかり議論をしていく内容は、そちらのサイドからもお伝えいただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"本田委員","kind":"確認","question":"区側が各議会にきちっと報告するというようなことをお互いに確認し合ったと聞いて、そんなレベルにいて、責任を持って自治体を運営していくのか。その辺の東京都の壁をこの１年間どう打ち破っていくのか、その見通しというのは、ちょっとお尋ねをしておきたいと思います。","respondent":"市岡企画財政課長","answer":"いい意味でも、悪い意味でも、動かすときのクリティカルパスになっているわけです。それらを踏まえて、これからは議論から行動へという段階になってくると思いますので、ぜひまたいろいろご尽力をいただいて進めていきたいと思います。","id":"exchange-015"},{"speaker":"本田委員","kind":"質問・要望","question":"ぜひそこは積極的に取り組んでほしいと求めました。避けて通れない、解決すべき問題なんだということを積極的にいろいろな形でＰＲは進めていただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"藤田委員","kind":"質問","question":"５年前ですか、報告を受けながら、極めて感じているわけです。効率的・効果的な運営を図るべきである」というのを、この報告の要旨の３点にわたってのまとめの背景を教えていただけないかなと思います。","respondent":"中山清掃リサイクル課長","answer":"今まで可燃ごみの地域処理という部分の検討だけだったわけですが、粗大、その後アンバランスの是正となっておるわけです。現段階での検討の方向性は、先ほどし尿処理の中で、清掃一部事務組合として方針決定の中ですでに織り込んでいる部分もあります。","id":"exchange-017"},{"speaker":"藤田委員","kind":"質問・要望","question":"先ほども言いましたけれども、ちょうど今が一番大事な時期なんですよね。平成１７年度末で解散するというわけですから、議長会に対するサポートをどうすべきなのか、そういう形でぜひ取り扱っていただきたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"須藤委員","kind":"質問・要望","question":"要望なんですけれども、今後の活動方針が出されたんですけれども、この委員会としてもそういう活動をしていかざるを得ないだろうと。委員会として都知事に要望書を我々としても持っていくんだというようなことも一つの方法だろうと思うので、委員長、こんなふうな要望をしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"中島委員","kind":"質問","question":"これは２３区全体でやるようなお話を伺っていたんですが、この問題というのは分かるようで、言葉が区民の方には難しいんじゃないかなと思うんです。そのことを区民の方に理解していただけるような、区としてのＰＲも何かあったらいいんじゃないかなと思うんですが、いかがか尋ねました。","respondent":"市岡企画財政課長","answer":"２３区で共同のものをまずつくる段取りになると思うんですが、その作成方には実は私どもも入ろうと思っています。それから、やはりなかなか分かりにくいテーマですので、できるだけ身近なところに引き寄せた形でご説明をできるように努力をしたいと思います。","id":"exchange-020"},{"speaker":"中島委員","kind":"質問・要望","question":"実はと言っても、わからないというそういうものがあると思いますので、区民の生活に密着しているような分かりやすい言葉でお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"高星委員","kind":"質問","question":"こっちを知るためには、こっちも知りたいような気がしてならないので、ちょっとそれをお聞きします。ついでだから聞くけれども、平成１８年４月以降、清掃一部事務組合が当分の間続くんだよと、当分の間というのは、どのぐらいの計画になるのか。","respondent":"市岡企画財政課長、中山清掃リサイクル課長","answer":"いろいろな意味で制度が動くと、私は何区が報告していないかということは存じ上げませんが、消極的なことは言えるだろうと思います。同じ内容で報告をすることをまず行動の出発点にしようという申し合わせですので… 決して先々、この工場を建て替えるときにどうするんだというのを早めに検討をしなければいけないというのが出てくるわけです。そういう意味では、そういうことも踏まえた…","id":"exchange-022"},{"speaker":"須藤委員","kind":"意見","question":"変化というものを整理しておいてもらえば、皆さん方、議論に入っていきやすいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/905389?Template=document&Id=5546#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":40202,"voices":88}},{"id":"h16-20040607-16","meetingId":"h16-cm06","date":"2004年6月7日","dateIso":"2004-06-07","committee":"街づくり特別委員会","time":"午後１時０５分～午後２時２３分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"地区計画一覧表の備考のところに７タイプありますということで、恐れ入ります、簡単にその違いを教えていただきたい。それから、ここに１２までありますけれども、品川区内の地区計画はこれですべてなのかということ。","respondent":"藤田都市計画課長、上野都市開発課長","answer":"七つタイプがあるという説明をさせていただきましたけれども、特に特徴づけられた形ではないので、ちょっとなかなか説明ができないものです。特定街区といった地区計画ではない制度でのまちづくりは進められておりますけれども… 地区計画に係る都市開発課所管の事業についてご説明申し上げましたが、検討していますので、先ほどご説明申し上げたところです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、今まだ地区計画を定めていない地域に関しては、今特別委員会では範囲に入らないのでしょうか。今回は、この一覧表に載っているところという理解でよろしいのか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"先般、正副委員長とご協議させていただいた中での理解としては、交渉段階でまだ具体的な計画段階に至らないものにつきましては建設委員会所管ということで、具体的な計画に取りかかるものにつきましては街づくり特別委員会ということで、私ども、理解しています。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"下のように変わったというのは、どこで、どういう形で変わるのかということをちょっとお聞きしたい。権利者が８２名のうち、準備組合に入っているのは７４名ということで、どういうふうに進められていくのか。","respondent":"上野都市開発課長","answer":"都市計画の手続に入ってまいりまして、都市計画審議会といったところでのご説明をする場で、適宜ご説明を差し上げることになります。加入していない方々への対応ですけれども、計画変更の手続、まだ加入されていない方についても理解を得られるような対応をしていくです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"きょうは、事務事業概要ですので、中地区については、後でまた説明をしていただくような機会を、ぜひ持っていただきたいなと要望したいと思うんです。こういうふうに変更がされたということで提案されて、どこでどのように検討されて変わってきたのかということについて…","respondent":"上野都市開発課長","answer":"地元で計画変更に関する提案をするため、今までもいろいろ検討をしてきたところでございまして、行政としてその手続に乗せていくという段階です。そういう作業をしてきたです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いろいろな意見があると思いますので、十分、地域の意見を聞きながら進めてほしいと求めました。これに対しては、改めて後でご報告いただけたらと思います。","respondent":"菊地委員長","answer":"地区計画全般に係ることということで、これから、理事者のほうから必要な報告事項が上がってくれば、その都度、理事者、正副委員長で協議をしながら進めていきたいと思います。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"調査事項概要に係る地区計画に関することについて、１年間これで進むわけですから、確認をさせてほしいと求めました。どういう仕組みで進めていくのかというようなイメージで、どういうところを目指して進めていくのかも、そこのところを教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"ということは、今、飯沼委員がおっしゃったように、今ここにある地区計画、進められていることに対して、この委員会として意見を反映していきましょうということか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"事業を導入するに当たって、それを契機に地区計画が、戸越などではつくられてきているというような形だと思うんです。どういう働きかけを提言したらできるかということは、審査事項というか、そういうことは入ってないんか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問・要望","question":"項目として詰めていただけるのであれば、ほんとうに地区計画をどういうふうに進めていったらいいのかということが、区民の皆さんも含めて、そういったことができる仕組みも、ある程度私たち、ここの委員会でできればいいなという要望だけ、あとは、ぜひ、詰めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"西本委員","kind":"提案","question":"確認をさせていただきたいんですが、それから品川区という形の関係がどうなっているのか、お聞きしたいんです。都市開発ですから、私たちがこれから調査をしていく中で、いろいろ提案等々が入ってくると思うんですとの意見を述べました。","respondent":"藤田都市計画課長","answer":"先ほどの資料のＡ４版横ですけれども、品川区で告示するものについては、品川区が決定したものです。３haといっても、３ha以上の項目が多いことから、一応はそういった仕切りになってあります。","id":"exchange-010"},{"speaker":"西本委員","kind":"提案","question":"それから、東京都という形で書いてあるものについては、一応品川区中心に、要は指導権ですか、東京都の範囲というのはどの辺までかかわってくるのか。品川区がこうあるべきだという提案が、それとも、あくまでも品川区の中で決められたことが優先されるような関係なのかとの意見を述べました。","respondent":"藤田都市計画課長、中谷まちづくり事業部長","answer":"事業を進めている方等もいらっしゃるわけですが、東京都がありということの中での話になってくることになりますので、お話し合いを進める中で確認をしていければなと思ってあります。 再開発につきましては、一定の面積要件で都の決定であるですが、そういうことが基本です。あるいは市街地整備基本方針というものがありますので、区の基本な考えでございまして、そういうものに基づいた都市計画決定をするです。","id":"exchange-011"},{"speaker":"原委員","kind":"質問・要望","question":"今年１年、今決められている１２の地区計画一覧の中から、じゃあどういうふうに進めていくかという話にならないと思うんですよ。品川区の地区計画がどういうものであるかという審議の内容をしっかり詰めていかなければ、最後に成果として上がるものが出てこないと思うんです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"議会として知らすべきものがあるか、やはり、考え方を最初にきちっとつくっていただかないとということです。個別的なこともあるということですから、何を、見取り図が必要じゃないかというお二方の指摘は正しいんじゃないかと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"危険度調査は区の調査で、５年ごとに行われているというご報告をいただいたんですが、過去の報告で、これが、区内の安全性を高めるためにどう活用されてきたのか、ちょっとお聞かせいただきたいんですけれども。","respondent":"浜脇住環境整備課長","answer":"なおかつ、防災まちづくりの推進企画も、今は改定版ですが、改定する前の中にこれを載せて、まちづくりを進めるようにということで活用したものです。そういったことで、載せることによりまして、今後、取り組む方向性といいますか、方針といいますか、そういったものを定めまし…","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１３０ページの密集住宅市街地整備促進事業なんですが、現況調査をした後の整備計画策定のやり方というのをどういうふうにしていくのかということを教えていただきたいんです。","respondent":"浜脇住環境整備課長","answer":"任意費用ですので、地元の方々に広く知っていただいて、認識した上でやるというのが基本です。二葉３・４丁目につきましては、間もなく第１回目、整備構想をまとめてまいりたいと考えています。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その協議会は、一般の方も入れるようにということなんですが、一般の方の募集のやり方ですとか、協議会の人数はどのぐらいになるのかを、説明を求めました。","respondent":"浜脇住環境整備課長","answer":"その中でアンケートも行いまして、こういう状況で、こういう回答があったということをニュースで流しました。町会とか、商店会のほうには、人選をお願いしています。","id":"exchange-016"},{"speaker":"原委員","kind":"質問・要望","question":"この委員会でどう取り上げていくかということを考えていかないと、これからの中できちっと精査していかないと、特定事件調査にならない。どういう視点でまちづくりに関連してくるのか、そういうところも含めて、方向づけをしていただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/408110?Template=document&Id=6278#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":24093,"voices":86}}]);
